    @Override
    public void onInitializeClient() {
        activeClient = this;
        // Register lifted objective executors before the tick loop starts. Only MineStone is lifted
        // so far; every other action falls through to the unchanged resolveControl chain.
        objectiveRegistry.register(mineStoneExecutor);
        objectiveRegistry.register(retrieveTableExecutor);
        objectiveRegistry.register(useBedExecutor);
        objectiveRegistry.register(craft2x2Executor);
        objectiveRegistry.register(huntSheepExecutor);
        objectiveRegistry.register(gatherLogExecutor);
        objectiveRegistry.register(placeWorkstationExecutor);
        objectiveRegistry.register(descentExecutor);
        objectiveRegistry.register(villageOpportunityExecutor);
        LOGGER.info("MCBot Fabric spike loaded. instanceId={} brainUrl={}", instanceId, brainUri);
        LOGGER.info(
            "motion.gaze.mode instanceId={} mode={} configured={}",
            instanceId,
            motionMode.wireName(),
            motionModeResolution.configuredValue()
        );
        LOGGER.info(
            "motion.locomotion.mode instanceId={} mode={} configured={}",
            instanceId,
            motionMode.wireName(),
            motionModeResolution.configuredValue()
        );
        LOGGER.info(
            "motion.interaction.mode instanceId={} mode={} configured={}",
            instanceId,
            motionMode.wireName(),
            motionModeResolution.configuredValue()
        );
        LOGGER.info(
            "opportunity.mode instanceId={} mode={} configured={}",
            instanceId,
            opportunityMode.wireName(),
            opportunityModeResolution.configuredValue()
        );
        LOGGER.info(
            "world_action.target_protection instanceId={} readable={} status={} configuredRegions={}",
            instanceId,
            targetProtection.configurationReadable(),
            targetProtection.configurationStatus(),
            targetProtection.configuredRegionCount()
        );
        if (!targetProtection.configurationReadable()) {
            LOGGER.warn(
                "world_action.target_protection_unavailable instanceId={} status={} blockActions=deny",
                instanceId,
                targetProtection.configurationStatus()
            );
        }
        if (motionModeResolution.rejected()) {
            LOGGER.warn(
                "motion.gaze.mode_rejected instanceId={} configured={} fallback=legacy",
                instanceId,
                motionModeResolution.configuredValue()
            );
        }
        if (opportunityModeResolution.rejected()) {
            LOGGER.warn(
                "opportunity.mode_rejected instanceId={} configured={} fallback=off",
                instanceId,
                opportunityModeResolution.configuredValue()
            );
        }
        LOGGER.info("IPC protocol invariant: first request line is instanceId:{}", instanceId);
        cockpitLayout = CockpitLayout.load(cockpitConfigPath());
        if (EXPLORE_ENABLED || opportunityMode.observes()) {
            ClientChunkEvents.CHUNK_LOAD.register(this::onFarPerceptionChunkLoaded);
            ClientChunkEvents.CHUNK_UNLOAD.register(this::onFarPerceptionChunkUnloaded);
        }
        if (opportunityMode.observes()) {
            ClientEntityEvents.ENTITY_LOAD.register(opportunityObservationCollector::onEntityLoaded);
            ClientEntityEvents.ENTITY_UNLOAD.register(opportunityObservationCollector::onEntityUnloaded);
            ClientEntityEvents.ENTITY_LOAD.register(this::onOpportunityEntityLoaded);
            ClientEntityEvents.ENTITY_UNLOAD.register(this::onOpportunityEntityUnloaded);
        }
        // ClientPlayerEntity has no copy of ServerPlayerEntity's spawn-point fields.  Observe the
        // exact translatable game message emitted only after the server commits a bed/anchor spawn.
        // ALLOW_GAME sees the received server message even if another listener later hides it; this
        // listener never blocks or modifies the message.
        ClientReceiveMessageEvents.ALLOW_GAME.register((message, overlay) -> {
            observeRespawnConfirmation(message);
            return true;
        });
        ClientTickEvents.START_CLIENT_TICK.register(
            interactionAuthority::prepareItemContinuation);
        ClientTickEvents.END_CLIENT_TICK.register(this::onClientTick);
        ClientLifecycleEvents.CLIENT_STOPPING.register((client) -> {
            clearMissionIronExposureState();
            logLiveEvidenceTerminalState(client);
            clearGatherTreeForLifecycle();
            clearSurfaceReturnState();
            clearPerceptionWorld();
            clearOpportunityHostiles();
            villageOpportunityExecutor.clearForLifecycle(
                client,
                client == null ? null : client.player,
                System.currentTimeMillis(),
                "client_stopping"
            );
            respawnVerificationTracker.clear();
            gazeAuthority.reset();
            interactionAuthority.lifecycleCleanup(client);
            if (activeClient == this) {
                activeClient = null;
            }
            movementAuthority.release(
                client,
                client == null ? null : client.player,
                "client_stopping",
                System.currentTimeMillis()
            );
            brainLink.shutdown();
            LOGGER.info("MCBot Fabric spike stopped. instanceId={}", instanceId);
        });
        // Observability cockpit: hotkeys (UNBOUND by default — operator binds them in vanilla Controls)
        // + the status HUD. Purely additive; the HUD render is fail-safe (see renderCockpitHud).
        toggleBotKey = KeyBindingHelper.registerKeyBinding(new KeyBinding(
            "key.mcbot.toggle_bot", InputUtil.Type.KEYSYM, GLFW.GLFW_KEY_UNKNOWN, "category.mcbot"));
        toggleHudKey = KeyBindingHelper.registerKeyBinding(new KeyBinding(
            "key.mcbot.toggle_hud", InputUtil.Type.KEYSYM, GLFW.GLFW_KEY_UNKNOWN, "category.mcbot"));
        togglePathKey = KeyBindingHelper.registerKeyBinding(new KeyBinding(
            "key.mcbot.toggle_path", InputUtil.Type.KEYSYM, GLFW.GLFW_KEY_UNKNOWN, "category.mcbot"));
        openEditorKey = KeyBindingHelper.registerKeyBinding(new KeyBinding(
            "key.mcbot.open_editor", InputUtil.Type.KEYSYM, GLFW.GLFW_KEY_UNKNOWN, "category.mcbot"));
        // Boot-time observability for the reported dead path-overlay key: log what each
        // cockpit binding actually resolved to (a silently-unbound binding shows up here instantly).
        ClientTickEvents.END_CLIENT_TICK.register(new net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents.EndTick() {
            private boolean logged = false;

            @Override
            public void onEndTick(MinecraftClient client) {
                if (logged || client == null) {
                    return;
                }
                logged = true;
                LOGGER.info(
                    "cockpit.keybinds_resolved instanceId={} bot={} hud={} path={} editor={}",
                    instanceId,
                    toggleBotKey.getBoundKeyLocalizedText().getString(),
                    toggleHudKey.getBoundKeyLocalizedText().getString(),
                    togglePathKey.getBoundKeyLocalizedText().getString(),
                    openEditorKey.getBoundKeyLocalizedText().getString()
                );
            }
        });
        HudRenderCallback.EVENT.register((drawContext, tickCounter) -> renderCockpitHud(drawContext));
        WorldRenderEvents.AFTER_TRANSLUCENT.register(this::renderPathOverlay);
    }

    private void onFarPerceptionChunkLoaded(ClientWorld world, WorldChunk chunk) {
        if (world == null || chunk == null) {
            return;
        }
        ensureFarPerceptionWorld(world);
        farPerceptionScanner.onChunkLoaded(chunk.getPos().x, chunk.getPos().z);
    }

    private void onFarPerceptionChunkUnloaded(ClientWorld world, WorldChunk chunk) {
        if (world == null || chunk == null || world != farPerceptionWorld) {
            return;
        }
        farPerceptionScanner.onChunkUnloaded(chunk.getPos().x, chunk.getPos().z);
        if (opportunityMode.observes()) {
            opportunityObservationCollector.onChunkUnloaded(world, chunk);
        }
    }

    private void ensureFarPerceptionWorld(ClientWorld world) {
        if (world == farPerceptionWorld) {
            return;
        }
        farPerceptionScanner.clear();
        opportunityObservationCollector.clear();
        villageOpportunityExecutor.clearForLifecycle();
        clearOpportunityHostiles();
        opportunityHostileWorld = world;
        latestOpportunityDiscoveries = List.of();
        latestOpportunityDiscoveriesTruncated = false;
        lastOpportunitySnapshotFingerprint = null;
        opportunityScannerRevision = 0L;
        opportunityScanOrigin = null;
        opportunityScanAtMs = 0L;
        farPerceptionWorld = world;
    }

    private void clearPerceptionWorld() {
        farPerceptionScanner.clear();
        opportunityObservationCollector.clear();
        villageOpportunityExecutor.clearForLifecycle();
        clearOpportunityHostiles();
        latestOpportunityDiscoveries = List.of();
        latestOpportunityDiscoveriesTruncated = false;
        farPerceptionWorld = null;
        opportunityScanOrigin = null;
        opportunityScanAtMs = 0L;
        lastOpportunitySnapshotFingerprint = null;
        opportunityScannerRevision = 0L;
    }

    private void observeRespawnConfirmation(net.minecraft.text.Text message) {
        if (message == null || !(message.getContent() instanceof TranslatableTextContent translatable)) {
            return;
        }
        MinecraftClient client = MinecraftClient.getInstance();
        WorldIdentityResolver.Resolution identity = resolveSnapshotWorldIdentity(client);
        if (respawnVerificationTracker.observeServerGameMessage(
            identity == null ? "" : identity.opaqueWorldId(),
            translatable.getKey()
        )) {
            LOGGER.info(
                "player.respawn_verified instanceId={} worldIdentity={} evidence=server_game_message:{}",
                instanceId,
                identity.opaqueWorldId(),
                translatable.getKey()
            );
        }
    }

    private Optional<FarPerceptionScanner.ChunkObservation> scanFarPerceptionChunk(FarPerceptionScanner.ChunkKey key) {
        ClientWorld world = farPerceptionWorld;
        if (world == null) {
            return Optional.empty();
        }
        WorldChunk chunk = world.getChunkManager().getWorldChunk(key.x(), key.z(), false);
        // Opportunity classification intentionally shares the existing throttled far-perception
        // probe. Chunk lifecycle callbacks only enqueue/evict; neither the tick loop nor snapshot
        // assembly performs a chunk/world scan.
        if (opportunityMode.observes() && chunk != null) {
            opportunityObservationCollector.onChunkScanned(
                world,
                chunk,
                opportunityScanOrigin,
                opportunityScanAtMs
            );
        }
        return FarPerceptionScanner.scanLoadedChunk(world, chunk);
    }

    private void tickFarPerception(ClientWorld world, ClientPlayerEntity player, long nowMs) {
        ensureFarPerceptionWorld(world);
        opportunityScanOrigin = opportunityMode.observes()
            ? player.getBlockPos().toImmutable()
            : null;
        opportunityScanAtMs = opportunityMode.observes() ? nowMs : 0L;
        FarPerceptionScanner.TickStats stats;
        try {
            stats = farPerceptionScanner.tick(player.age);
        } finally {
            opportunityScanOrigin = null;
            opportunityScanAtMs = 0L;
        }
        if (nowMs - lastFarPerceptionLogAtMs < FAR_PERCEPTION_LOG_INTERVAL_MS) {
            return;
        }
        lastFarPerceptionLogAtMs = nowMs;
        FarPerceptionScanner.Summary summary = farPerceptionScanner.summary(
            player.getX(),
            player.getZ(),
            FAR_PERCEPTION_WOOD_TARGET_LIMIT
        );
        int woodTargets = summary.resources().isEmpty() ? 0 : summary.resources().getFirst().targets().size();
        LOGGER.info(
            "exploration.perception.summary instanceId={} loadedChunks={} scannedChunks={} attemptedThisTick={} updatedThisTick={} woodTargets={}",
            instanceId,
            summary.loadedChunkCount(),
            summary.scannedChunkCount(),
            stats.attemptedChunks(),
            stats.updatedChunks(),
            woodTargets
        );
    }

    private FarPerceptionScanner.Summary farPerceptionSummary(ClientPlayerEntity player) {
        if (!EXPLORE_ENABLED || player == null) {
            return null;
        }
        return farPerceptionScanner.summary(player.getX(), player.getZ(), FAR_PERCEPTION_WOOD_TARGET_LIMIT);
    }

    private void onOpportunityEntityLoaded(Entity entity, ClientWorld world) {
        if (!(entity instanceof HostileEntity hostile) || world == null) {
            return;
        }
        if (opportunityHostileWorld != world) {
            clearOpportunityHostiles();
            opportunityHostileWorld = world;
        }
        opportunityTrackedHostiles.put(hostile.getUuid(), hostile);
        while (opportunityTrackedHostiles.size() > 512) {
            opportunityTrackedHostiles.remove(
                opportunityTrackedHostiles.keySet().iterator().next());
        }
    }

    private void onOpportunityEntityUnloaded(Entity entity, ClientWorld world) {
        if (entity == null || world == null || world != opportunityHostileWorld) {
            return;
        }
        opportunityTrackedHostiles.remove(entity.getUuid());
    }

    private void clearOpportunityHostiles() {
        opportunityTrackedHostiles.clear();
        opportunityHostileWorld = null;
    }

    private int nearbyOpportunityHostileCount(ClientPlayerEntity player) {
        if (player == null || player.getWorld() != opportunityHostileWorld) {
            return 0;
        }
        int count = 0;
        double radiusSq = VillageOpportunityExecutor.HOSTILE_RADIUS
            * VillageOpportunityExecutor.HOSTILE_RADIUS;
        for (HostileEntity hostile : opportunityTrackedHostiles.values()) {
            if (hostile != null && hostile.isAlive() && !hostile.isRemoved()
                && hostile.squaredDistanceTo(player) <= radiusSq) {
                count += 1;
            }
        }
        return count;
    }

    private VillageOpportunityExecutor.DiscoveryFact lookupVillageOpportunity(String id) {
        if (id == null || id.isBlank()) {
            return null;
        }
        return latestOpportunityDiscoveries.stream()
            .filter(discovery -> id.equals(discovery.id()))
            .findFirst()
            .map(discovery -> new VillageOpportunityExecutor.DiscoveryFact(
                discovery.id(),
                opportunityScannerRevision,
                discovery.type(),
                new BlockPos(discovery.x(), discovery.y(), discovery.z()),
                discovery.status(),
                discovery.executorReady(),
                discovery.signals()
            ))
            .orElse(null);
    }

    private void refreshVillageOpportunitySnapshot(
        MinecraftClient client,
        ClientPlayerEntity player,
        long nowMs
    ) {
        if (client == null || client.world == null || player == null
            || !opportunityMode.observes()) {
            latestOpportunityDiscoveries = List.of();
            latestOpportunityDiscoveriesTruncated = false;
            return;
        }
        WorldIdentityResolver.Resolution identity = resolveSnapshotWorldIdentity(client);
        refreshOpportunitySnapshot(
            client.world,
            player,
            identity,
            client.world.getRegistryKey().getValue().toString(),
            nowMs
        );
    }

    /**
     * Reclassifies exactly the loaded chunk containing the frozen discovery anchor before reducing
     * the opportunity snapshot. This arrival-only path bypasses the ordinary 30-second cache while
     * remaining bounded to one chunk and current event-cached entities.
     */
    private VillageOpportunityExecutor.DiscoveryFact forceRefreshVillageOpportunity(
        String opportunityId,
        BlockPos frozenTarget,
        MinecraftClient client,
        ClientPlayerEntity player,
        long nowMs
    ) {
        BlockPos target = frozenTarget == null ? null : frozenTarget.toImmutable();
        if (target == null || client == null
            || client.world == null || player == null || !opportunityMode.observes()) {
            return null;
        }
        int chunkX = Math.floorDiv(target.getX(), 16);
        int chunkZ = Math.floorDiv(target.getZ(), 16);
        WorldChunk chunk = client.world.getChunkManager().getWorldChunk(
            chunkX, chunkZ, false);
        if (chunk == null) {
            LOGGER.warn(
                "village.opportunity.revalidate.live_refresh instanceId={} opportunityId={} chunkX={} chunkZ={} result=target_chunk_unloaded",
                instanceId, opportunityId, chunkX, chunkZ);
            return null;
        }
        OpportunityObservationCache.RefreshResult refresh =
            opportunityObservationCollector.forceChunkRefresh(
                client.world, chunk, player.getBlockPos(), nowMs);
        refreshVillageOpportunitySnapshot(client, player, nowMs);
        VillageOpportunityExecutor.DiscoveryFact live =
            lookupVillageOpportunity(opportunityId);
        LOGGER.info(
            "village.opportunity.revalidate.live_refresh instanceId={} opportunityId={} chunkX={} chunkZ={} changed={} geometryRevision={} result={}",
            instanceId, opportunityId, chunkX, chunkZ, refresh.changed(),
            refresh.geometryRevision(),
            live != null && live.safelyExecutable() ? "verified" : "rejected");
        return live;
    }

    private VillageOpportunityExecutor.WorldScope currentVillageWorldScope() {
        MinecraftClient client = MinecraftClient.getInstance();
        if (client == null || client.world == null) {
            return new VillageOpportunityExecutor.WorldScope("", "", "", 0);
        }
        WorldIdentityResolver.Resolution identity = resolveSnapshotWorldIdentity(client);
        return new VillageOpportunityExecutor.WorldScope(
            identity.opaqueWorldId(),
            client.world.getRegistryKey().getValue().toString(),
            "",
            nearbyOpportunityHostileCount(client.player)
        );
    }

    private OpportunitySnapshotWire refreshOpportunitySnapshot(
        ClientWorld world,
        ClientPlayerEntity player,
        WorldIdentityResolver.Resolution worldIdentity,
        String dimension,
        long nowMs
    ) {
        if (!opportunityMode.observes() || world == null || player == null || worldIdentity == null) {
            latestOpportunityDiscoveries = List.of();
            latestOpportunityDiscoveriesTruncated = false;
            return OpportunitySnapshotWire.empty();
        }
        OpportunityExecutorCapabilityRegistry.RuntimeState executorRuntime =
            opportunityExecutorRuntime(world, player);
        OpportunityObservationCollector.Snapshot observed =
            opportunityObservationCollector.refreshSnapshot(
                world,
                worldIdentity.opaqueWorldId(),
                dimension,
                player.getBlockPos(),
                nowMs,
                executorRuntime,
                (discoveryId, golem) -> evaluateIronGolemOpportunityReadiness(
                    world,
                    player,
                    executorRuntime,
                    discoveryId,
                    golem
                )
            );
        latestOpportunityDiscoveries = observed.discoveries();
        int discoveryCount = observed.scanResult().discoveries().size();
        boolean truncated = observed.scanResult().truncated()
            || observed.wireMaps().size() > OPPORTUNITY_WIRE_DISCOVERY_LIMIT;
        latestOpportunityDiscoveriesTruncated = truncated;
        List<Map<String, Object>> boundedDiscoveries = observed.wireMaps().stream()
            .limit(OPPORTUNITY_WIRE_DISCOVERY_LIMIT)
            .map(map -> Collections.unmodifiableMap(new LinkedHashMap<>(map)))
            .toList();
        OpportunitySnapshotFingerprint fingerprint = opportunityFingerprint(
            worldIdentity.opaqueWorldId(),
            dimension == null ? "" : dimension,
            observed.discoveries().stream()
                .limit(OPPORTUNITY_WIRE_DISCOVERY_LIMIT)
                .toList(),
            discoveryCount,
            truncated
        );
        if (!fingerprint.equals(lastOpportunitySnapshotFingerprint)) {
            opportunityScannerRevision += 1L;
            lastOpportunitySnapshotFingerprint = fingerprint;
        }
        return new OpportunitySnapshotWire(
            boundedDiscoveries,
            opportunityScannerRevision,
            discoveryCount,
            truncated
        );
    }

    static OpportunitySnapshotFingerprint opportunityFingerprint(
        String worldIdentity,
        String dimension,
        List<OpportunityObservationCollector.WireDiscovery> discoveries,
        int discoveryCount,
        boolean truncated
    ) {
        List<OpportunityDiscoveryFingerprint> semanticDiscoveries = discoveries == null
            ? List.of()
            : discoveries.stream()
                .filter(Objects::nonNull)
                .map(discovery -> new OpportunityDiscoveryFingerprint(
                    discovery.id(),
                    discovery.type(),
                    discovery.x(),
                    discovery.y(),
                    discovery.z(),
                    discovery.memberCount(),
                    discovery.confidence(),
                    discovery.signals(),
                    discovery.status(),
                    discovery.capabilityId(),
                    discovery.executorId(),
                    discovery.executorReady(),
                    discovery.readinessReason(),
                    discovery.readinessSource()
                ))
                .toList();
        return new OpportunitySnapshotFingerprint(
            worldIdentity == null ? "" : worldIdentity,
            dimension == null ? "" : dimension,
            semanticDiscoveries,
            Math.max(0, discoveryCount),
            truncated
        );
    }

    record OpportunityDiscoveryFingerprint(
        String id,
        String type,
        int x,
        int y,
        int z,
        int memberCount,
        double confidence,
        List<String> signals,
        String status,
        String capabilityId,
        String executorId,
        boolean executorReady,
        String readinessReason,
        String readinessSource
    ) {
        OpportunityDiscoveryFingerprint {
            signals = signals == null ? List.of() : List.copyOf(signals);
            status = status == null ? "observed" : status;
            capabilityId = capabilityId == null ? "" : capabilityId;
            executorId = executorId == null ? "" : executorId;
            readinessReason = readinessReason == null ? "" : readinessReason;
            readinessSource = readinessSource == null ? "" : readinessSource;
        }
    }

    record OpportunitySnapshotFingerprint(
        String worldIdentity,
        String dimension,
        List<OpportunityDiscoveryFingerprint> discoveries,
        int discoveryCount,
        boolean truncated
    ) {
    }

    private OpportunityExecutorCapabilityRegistry.RuntimeState opportunityExecutorRuntime(
        ClientWorld world,
        ClientPlayerEntity player
    ) {
        if (player == null) {
            return OpportunityExecutorCapabilityRegistry.RuntimeState.none();
        }
        List<String> itemIds = new ArrayList<>();
        int stoneSwordRemainingDurability = 0;
        int fillerBlocks = 0;
        int end = Math.min(36, player.getInventory().size());
        for (int slot = 0; slot < end; slot++) {
            ItemStack stack = player.getInventory().getStack(slot);
            if (stack == null || stack.isEmpty()) {
                continue;
            }
            String itemId = net.minecraft.registry.Registries.ITEM.getId(stack.getItem()).toString();
            if (itemId.endsWith("_pickaxe")) {
                itemIds.add(itemId);
            }
            String itemPath = itemId.contains(":")
                ? itemId.substring(itemId.indexOf(':') + 1) : itemId;
            if ("stone_sword".equals(itemPath)
                || "iron_sword".equals(itemPath)
                || "diamond_sword".equals(itemPath)
                || "netherite_sword".equals(itemPath)) {
                int remaining = stack.isDamageable()
                    ? Math.max(0, stack.getMaxDamage() - stack.getDamage())
                    : stack.getCount();
                stoneSwordRemainingDurability = Math.max(
                    stoneSwordRemainingDurability,
                    remaining
                );
            }
            if (InventoryCounter.isCobblestoneItemId(itemPath)) {
                fillerBlocks += stack.getCount();
            }
        }
        OpportunityExecutorCapabilityRegistry.RuntimeState tools =
            OpportunityExecutorCapabilityRegistry.RuntimeState.fromCanonicalItemIds(itemIds);
        return new OpportunityExecutorCapabilityRegistry.RuntimeState(
            tools.woodenOrBetterPickaxe(),
            tools.stoneOrBetterPickaxe(),
            player.getHealth(),
            player.getHungerManager().getFoodLevel(),
            stoneSwordRemainingDurability,
            fillerBlocks,
            3,
            nearbyOpportunityHostileCount(player),
            opportunityObservationCollector.liveTrackedIronGolemCount(world)
        );
    }

    private OpportunityExecutorCapabilityRegistry.TargetReadiness evaluateIronGolemOpportunityReadiness(
        ClientWorld world,
        ClientPlayerEntity player,
        OpportunityExecutorCapabilityRegistry.RuntimeState runtime,
        String discoveryId,
        IronGolemEntity golem
    ) {
        if (world == null || player == null || golem == null
            || golem.getWorld() != world || !golem.isAlive() || golem.isRemoved()
            || opportunityObservationCollector.resolveExactIronGolem(world, discoveryId) != golem) {
            return OpportunityExecutorCapabilityRegistry.TargetReadiness.unavailable();
        }
        VoxelCell start = voxelFeet(player);
        BlockPos targetCell = golem.getBlockPos();
        int margin = 8;
        int verticalMargin = 8;
        WorldVoxelPerception voxels = new WorldVoxelPerception(
            world,
            Math.min(start.x(), targetCell.getX()) - margin,
            Math.max(start.x(), targetCell.getX()) + margin,
            Math.min(start.y(), targetCell.getY()) - verticalMargin,
            Math.max(start.y(), targetCell.getY()) + verticalMargin,
            Math.min(start.z(), targetCell.getZ()) - margin,
            Math.max(start.z(), targetCell.getZ()) + margin
        );
        IronGolemDefensePackagePlanner.Perception perception =
            ironGolemDefensePerception(world, voxels);
        Box bounds = golem.getBoundingBox();
        IronGolemDefensePackagePlanner.Target target =
            new IronGolemDefensePackagePlanner.Target(
                golem.getUuidAsString(),
                new IronGolemDefensePackagePlanner.EntityBounds(
                    bounds.minX,
                    bounds.minY,
                    bounds.minZ,
                    bounds.maxX,
                    bounds.maxY,
                    bounds.maxZ
                )
            );
        IronGolemDefensePackagePlanner.Readiness readiness =
            new IronGolemDefensePackagePlanner.Readiness(
                runtime.health(),
                runtime.foodLevel(),
                runtime.stoneSwordRemainingDurability(),
                runtime.totalFiller(),
                runtime.reservedFiller(),
                runtime.nearbyHostileCount(),
                runtime.liveIronGolemCount()
            );
        IronGolemDefensePackagePlanner.Plan plan =
            IronGolemDefensePackagePlanner.plan(perception, start, target, readiness);
        return new OpportunityExecutorCapabilityRegistry.TargetReadiness(
            plan.accepted(),
            plan.accepted() ? "defense_ready" : plan.reason()
        );
    }

    private static IronGolemDefensePackagePlanner.Perception ironGolemDefensePerception(
        ClientWorld world,
        WorldVoxelPerception delegate
    ) {
        return new IronGolemDefensePackagePlanner.Perception() {
            @Override public int minX() { return delegate.minX(); }
            @Override public int maxX() { return delegate.maxX(); }
            @Override public int minY() { return delegate.minY(); }
            @Override public int maxY() { return delegate.maxY(); }
            @Override public int minZ() { return delegate.minZ(); }
            @Override public int maxZ() { return delegate.maxZ(); }
            @Override public boolean isSolid(int x, int y, int z) {
                return delegate.isSolid(x, y, z);
            }
            @Override public boolean isHazard(int x, int y, int z) {
                return delegate.isHazard(x, y, z);
            }
            @Override public boolean isWater(int x, int y, int z) {
                return delegate.isWater(x, y, z);
            }
            @Override public boolean isLava(int x, int y, int z) {
                return delegate.isLava(x, y, z);
            }
            @Override public boolean isFullHeightSupport(int x, int y, int z) {
                return delegate.isFullHeightSupport(x, y, z);
            }
            @Override public boolean isProtectedBlock(int x, int y, int z) {
                BlockPos pos = new BlockPos(x, y, z);
                BlockState state = world.getBlockState(pos);
                return state.isOf(Blocks.BEDROCK)
                    || state.isOf(Blocks.BARRIER)
                    || state.isOf(Blocks.COMMAND_BLOCK)
                    || state.isOf(Blocks.CHAIN_COMMAND_BLOCK)
                    || state.isOf(Blocks.REPEATING_COMMAND_BLOCK)
                    || state.hasBlockEntity();
            }
            @Override public boolean isContainerBlock(int x, int y, int z) {
                BlockState state = world.getBlockState(new BlockPos(x, y, z));
                return state.isOf(Blocks.CHEST)
                    || state.isOf(Blocks.TRAPPED_CHEST)
                    || state.isOf(Blocks.BARREL)
                    || state.isIn(BlockTags.SHULKER_BOXES);
            }
            @Override public boolean isExistingProtectedAttackStance(
                VoxelCell stance,
                IronGolemDefensePackagePlanner.EntityBounds targetBounds
            ) {
                // Existing protected combat geometry needs an explicit code-owned recognizer.
                // Until one exists, fail closed and admit only the exact three-block package.
                return false;
            }
        };
    }

    private record OpportunitySnapshotWire(
        List<Map<String, Object>> discoveries,
        long scannerRevision,
        int discoveryCount,
        boolean truncated
    ) {
        private OpportunitySnapshotWire {
            discoveries = discoveries == null ? List.of() : List.copyOf(discoveries);
            scannerRevision = Math.max(0L, scannerRevision);
            discoveryCount = Math.max(0, discoveryCount);
        }

        private static OpportunitySnapshotWire empty() {
            return new OpportunitySnapshotWire(List.of(), 0L, 0, false);
        }
    }

    // PERF: the snapshot's reachable-logs scan (16-radius sweep + a route probe per found log) is the
    // dominant cost of a dispatch tick. The brain only needs it fresh enough for objective selection,
    // so reuse the last result briefly and re-scan when the player has actually moved.
    private static final long SNAPSHOT_LOG_SCAN_CACHE_MS = 2_000L;
    // 8 blocks: at walking speed (~4.3 blocks/s) a 4-block tolerance invalidated on nearly every
    // ~1/s dispatch while traveling, so the cache never engaged exactly when the scan is least
    // useful (mid-travel). Half the 16-block scan radius keeps the staleness immaterial.
    private static final double SNAPSHOT_LOG_SCAN_CACHE_MOVE_SQ = 64.0D; // 8 blocks
    private List<LogTarget> snapshotLogsCache = List.of();
    private long snapshotLogsCacheAtMs = 0L;
    private BlockPos snapshotLogsCachePos = null;

    private List<LogTarget> snapshotNearbyLogsCached(MinecraftClient client, ClientPlayerEntity player, long nowMs) {
        BlockPos pos = player.getBlockPos();
        if (snapshotLogsCachePos != null
            && nowMs - snapshotLogsCacheAtMs < SNAPSHOT_LOG_SCAN_CACHE_MS
            && snapshotLogsCachePos.getSquaredDistance(pos) <= SNAPSHOT_LOG_SCAN_CACHE_MOVE_SQ) {
            return snapshotLogsCache;
        }
        List<LogTarget> scanned = LogPerception.nearbyReachableLogs(
            client.world,
            player,
            LOG_SCAN_RADIUS,
            LOG_SCAN_DOWN,
            LOG_SCAN_UP,
            LOG_SCAN_LIMIT
        );
        // Run-9 loop (119 commands in 113 s): the snapshot kept advertising a log whose column the
        // zero-cluster guard had ignored, so the orchestrator re-hinted it every command. Ignored
        // columns never re-enter the snapshot — the loop is cut at the source.
        if (!ignoredGatherTreeColumns.isEmpty() && !scanned.isEmpty()) {
            List<LogTarget> filtered = new ArrayList<>(scanned.size());
            for (LogTarget logTarget : scanned) {
                if (!ignoredGatherTreeColumns.contains(new GridCell(logTarget.x(), logTarget.z()))) {
                    filtered.add(logTarget);
                }
            }
            scanned = filtered;
        }
        snapshotLogsCache = scanned;
        snapshotLogsCacheAtMs = nowMs;
        snapshotLogsCachePos = pos.toImmutable();
        return snapshotLogsCache;
    }

    private WorldIdentityResolver.Resolution resolveSnapshotWorldIdentity(MinecraftClient client) {
        ClientWorld currentWorld = client == null ? null : client.world;
        if (currentWorld == snapshotIdentityWorld && snapshotWorldIdentity != null) {
            return snapshotWorldIdentity;
        }
        snapshotIdentityWorld = currentWorld;
        snapshotIdentityWorldRevision++;
        snapshotWorldActionIdentity = null;
        snapshotIdentityLocalSaveName = "";
        String verifiedLocalSavePath = "";
        String verifiedLocalWorldFingerprint = "";
        WorldIdentityResolver.ConnectionKind connectionKind = WorldIdentityResolver.ConnectionKind.REMOTE_SERVER;
        if (client != null && client.isIntegratedServerRunning() && client.getServer() != null) {
            connectionKind = WorldIdentityResolver.ConnectionKind.LOCAL_SINGLEPLAYER;
            try {
                Path saveRoot = client.getServer().getSavePath(WorldSavePath.ROOT).toAbsolutePath().normalize();
                LocalWorldIdentityFingerprint.Resolution localIdentity =
                    LocalWorldIdentityFingerprint.resolve(saveRoot);
                if (localIdentity.verified()) {
                    verifiedLocalSavePath = localIdentity.canonicalSavePath();
                    verifiedLocalWorldFingerprint = localIdentity.creationFingerprint();
                    Path saveName = saveRoot.getFileName();
                    snapshotIdentityLocalSaveName = saveName == null
                        ? ""
                        : saveName.toString();
                }
            } catch (RuntimeException ignored) {
                // Fail closed to this world's isolated process-session identity.
                verifiedLocalSavePath = "";
                verifiedLocalWorldFingerprint = "";
            }
        }
        snapshotWorldIdentity = WorldIdentityResolver.resolve(new WorldIdentityResolver.Request(
            connectionKind,
            System.getenv(WorldIdentityResolver.CONFIG_ENV),
            verifiedLocalSavePath,
            verifiedLocalWorldFingerprint,
            "",
            instanceId + ":world-session:" + snapshotIdentityWorldRevision
        ));
        // Action authority never accepts the general-purpose configured world id as proof that a
        // local save is fresh or is the declared fixture. Bind it independently to the verified
        // save path + creation marker so MCBOT_WORLD_ID cannot elevate physical privileges.
        snapshotWorldActionIdentity = WorldIdentityResolver.resolve(
            new WorldIdentityResolver.Request(
                connectionKind,
                null,
                verifiedLocalSavePath,
                verifiedLocalWorldFingerprint,
                "",
                instanceId + ":world-action-identity:" + snapshotIdentityWorldRevision
            )
        );
        LOGGER.info(
            "world_action.identity instanceId={} worldIdentity={} source={} persistent={} configuredProtectionRegions={}",
            instanceId,
            snapshotWorldActionIdentity.opaqueWorldId(),
            snapshotWorldActionIdentity.source().name().toLowerCase(Locale.ROOT),
            snapshotWorldActionIdentity.persistent(),
            targetProtection.configuredRegionCount()
        );
        return snapshotWorldIdentity;
    }

    private FabricWorldActionAuthorization.ObservationResult observeWorldActionAuthorization(
        MinecraftClient client
    ) {
        resolveSnapshotWorldIdentity(client);
        WorldIdentityResolver.Resolution identity = snapshotWorldActionIdentity;
        String opaqueWorldIdentity = identity != null && identity.resolved()
            ? identity.opaqueWorldId()
            : "";
        boolean persistentLocalIdentity = identity != null
            && identity.persistent()
            && identity.source() == WorldIdentityResolver.Source.LOCAL_SAVE;
        if (freshWorldCreationSubmitted
            && createdFreshWorldIdentity.isEmpty()
            && persistentLocalIdentity
            && freshWorldPreexistingSaveInventoryCaptured
            && !snapshotIdentityLocalSaveName.isEmpty()
            && !freshWorldPreexistingSaveNames.contains(snapshotIdentityLocalSaveName)) {
            createdFreshWorldIdentity = opaqueWorldIdentity;
        }
        boolean createdFreshWorld = freshWorldCreationSubmitted
            && persistentLocalIdentity
            && !createdFreshWorldIdentity.isEmpty()
            && createdFreshWorldIdentity.equals(opaqueWorldIdentity);
        boolean developmentFixtureAuthorized = developmentFixtureAuthorizedFor(
            evidenceProfile,
            developmentFixtureRequested,
            configuredDevelopmentFixtureWorld,
            configuredQuickPlayWorld,
            snapshotIdentityLocalSaveName,
            identity,
            autoCreateNewWorld
        );
        boolean previouslyRevoked = !opaqueWorldIdentity.isEmpty()
            && revokedDisposableWorldIdentities.contains(opaqueWorldIdentity);
        if (previouslyRevoked) {
            createdFreshWorld = false;
            developmentFixtureAuthorized = false;
        }
        String sessionIdentity = instanceId
            + ":world-action-session:"
            + snapshotIdentityWorldRevision;
        int connectedPlayerCount = connectedWorldAuthorizationPlayerCount(client);
        FabricWorldActionAuthorization.ObservationResult observation =
            interactionAuthority.observeWorldAuthorization(
                client,
                new FabricWorldActionAuthorization.WorldObservation(
                    sessionIdentity,
                    opaqueWorldIdentity,
                    createdFreshWorld ? opaqueWorldIdentity : "",
                    developmentFixtureAuthorized ? opaqueWorldIdentity : "",
                    createdFreshWorld,
                    developmentFixtureAuthorized,
                    client != null && client.isInSingleplayer(),
                    connectedPlayerCount
                )
            );
        if (interactionAuthority.disposableWorldTrustRevoked()
            && !opaqueWorldIdentity.isEmpty()) {
            revokedDisposableWorldIdentities.add(opaqueWorldIdentity);
        }
        if (observation.disposableTrustRevokedNow()) {
            LOGGER.warn(
                "world_action.disposable_trust_revoked instanceId={} world={} playerCount={} pendingFixtureCommands=suppressed",
                instanceId,
                opaqueWorldIdentity,
                connectedPlayerCount
            );
        }
        return observation;
    }

    private static int connectedWorldAuthorizationPlayerCount(MinecraftClient client) {
        if (client == null) {
            return 0;
        }
        MinecraftServer server = client.getServer();
        if (client.isIntegratedServerRunning()
            && server != null
            && server.getPlayerManager() != null) {
            return server.getPlayerManager().getCurrentPlayerCount();
        }
        return client.world == null ? 0 : client.world.getPlayers().size();
    }

    static boolean developmentFixtureAuthorizedFor(
        String profile,
        boolean requested,
        String configuredFixtureWorld,
        String quickPlayWorld,
        String verifiedLocalSaveName,
        WorldIdentityResolver.Resolution identity,
        boolean createNewWorld
    ) {
        return !createNewWorld
            && requested
            && "development_fixture.v1".equals(profile)
            && configuredFixtureWorld != null
            && !configuredFixtureWorld.isBlank()
            && configuredFixtureWorld.equals(quickPlayWorld)
            && configuredFixtureWorld.equals(verifiedLocalSaveName)
            && identity != null
            && identity.persistent()
            && identity.source() == WorldIdentityResolver.Source.LOCAL_SAVE;
    }

    // ----- ShellServices accessors (PR-0 seam) -----
    // These expose shell-owned state to extracted ObjectiveExecutors. Visibility-only / thin
    // accessors; no behavior change.
    @Override
    public Logger logger() {
        return LOGGER;
    }

    @Override
    public String instanceId() {
        return instanceId;
    }

    @Override
    public BlockBreakController blockBreakController() {
        return blockBreakController;
    }

    @Override
    public BlockPlaceController blockPlaceController() {
        return blockPlaceController;
    }

    @Override
    public void completeCurrentCommand(String commandId, String reason, long nowMs) {
        brainLink.completeCurrentCommand(commandId, reason, nowMs);
    }

    private void onClientTick(MinecraftClient client) {
        long tickStartNs = System.nanoTime();
        long nowMs = System.currentTimeMillis();
        ClientPlayerEntity player = client.player;
        // Observe even during a transient null-world/loading tick.  Once a
        // trusted world has existed, that transition suspends and irrevocably
        // revokes disposable trust for this client process instead of letting
        // a later world/session revision re-arm it.
        observeWorldActionAuthorization(client);
        if (player == null || client.world == null) {
            clearSurfaceReturnState();
            clearMissionIronRunLifecycleState(activeMineNearbyIron);
            clearMissionIronExposureState();
            if (farPerceptionWorld != null) {
                clearPerceptionWorld();
            } else {
                villageOpportunityExecutor.clearForLifecycle(
                    client, player, nowMs, "no_player_or_world");
            }
            gazeAuthority.reset();
            interactionAuthority.release(
                client,
                player,
                LookDemand.Owner.NORMAL,
                "uncommanded",
                "release:no_player_or_world",
                "no_player_or_world",
                nowMs
            );
            currentInputState = movementAuthority.release(
                client,
                player,
                "no_player_or_world",
                nowMs
            );
            maybeDriveAutoSingleplayerMenu(client, nowMs);
            return;
        }
        // Re-evaluate the code-owned world/session capability before any command, fixture, or
        // physical interaction can run on this tick. LAN sharing keeps isInSingleplayer() true,
        // so the connected-player count is part of the authorization observation.
        interactionAuthority.observeContainerScreenTransition(client, player, nowMs);
        recordTrajectoryCell(player);

        // Cockpit hotkeys are polled BEFORE the singleplayer/death early-returns: the operator must be
        // able to toggle the HUD/path overlay (and the bot itself) while watching a Paper-server session
        // too — previously the !isInSingleplayer() return above this made every cockpit key dead on the
        // local server.
        pollCockpitKeybinds();

        // Harness runs never need the real cursor (camera and clicks are programmatic) — vanilla
        // re-grabs the system pointer at launch and after every screen close, yanking the
        // operator's mouse while they work in other windows. With MCBOT_NO_CURSOR_GRAB=1 (set by
        // live-gather-log.ps1) any grab is undone the same tick.
        // V1: only release the pointer while the bot is DRIVING (controlEnabled) -- it steers via
        // programmatic yaw/pitch and doesn't need the cursor, so releasing it keeps the operator's
        // mouse free for other windows. When toggled OFF for manual control, leave the grab alone so
        // the operator gets normal mouse-look (the toggle-off path re-locks it; see restoreManualInput).
        SUPPRESS_CURSOR_GRAB = NO_CURSOR_GRAB && controlEnabled;
        if (NO_CURSOR_GRAB && controlEnabled && client.mouse != null && client.mouse.isCursorLocked()) {
            client.mouse.unlockCursor();
        }

        if (!client.isInSingleplayer()) {
            villageOpportunityExecutor.clearForLifecycle(
                client, player, nowMs, "not_singleplayer");
            gazeAuthority.commit(player, null, nowMs);
            interactionAuthority.release(
                client,
                player,
                LookDemand.Owner.NORMAL,
                "uncommanded",
                "release:not_singleplayer",
                "not_singleplayer",
                nowMs
            );
            currentInputState = movementAuthority.release(
                client,
                player,
                "not_singleplayer",
                nowMs
            );
            return;
        }

        if (!liveEvidenceInitialStateLogged) {
            liveEvidenceInitialStateLogged = true;
            logLiveEvidenceWorldState(client, "initial");
        }

        if (maybeHonorLiveEvidenceStopRequest(client)) {
            return;
        }

        if (player.getHealth() <= 0.0F || player.isDead()) {
            villageOpportunityExecutor.clearForLifecycle(
                client, player, nowMs, "dead_or_zero_health");
            gazeAuthority.commit(player, null, nowMs);
            interactionAuthority.release(
                client,
                player,
                LookDemand.Owner.SURVIVAL,
                "uncommanded",
                "release:dead_or_zero_health",
                "dead_or_zero_health",
                nowMs
            );
            currentInputState = movementAuthority.release(
                client,
                player,
                "dead_or_zero_health",
                nowMs
            );
            // A same-world respawn is a new physical excursion. Never retain a dead player's
            // canonical surface trail or an in-flight return controller across that boundary.
            clearSurfaceReturnState();
            if (autoRespawn) {
                maybeRequestRespawn(player, nowMs);
            }
            return;
        }

        // Cockpit master toggle: when the bot is toggled OFF, hand input BACK to the player (restore
        // vanilla KeyboardInput) and skip the brain poll + control so it can't drift the mission state.
        // The bot's Input is (re)installed only while running. Default ON.
        if (!controlEnabled) {
            villageOpportunityExecutor.prepareForManualTakeover(
                client, player, nowMs);
            gazeAuthority.commit(player, null, nowMs);
            interactionAuthority.release(
                client,
                player,
                LookDemand.Owner.NORMAL,
                "manual",
                "release:manual_takeover",
                "manual_takeover",
                nowMs
            );
            currentInputState = movementAuthority.release(
                client,
                player,
                "manual_takeover",
                nowMs
            );
            restoreManualInput(player, client);
            hudActiveLayer = "stopped";
            return;
        }
        ensureControlledInput(player);
        if (EXPLORE_ENABLED || opportunityMode.observes()) {
            tickFarPerception(client.world, player, nowMs);
        }

        // The command the client has been executing (from the last poll); whether it has finished lets
        // the brain reuse the same commandId while a multi-tick command runs and mint a fresh id only
        // once it is done.
        BrainLink.Intent priorIntent = brainLink.effectiveIntent(nowMs);
        boolean currentCommandCompleted = priorIntent != null && isCommandCompleted(priorIntent.commandId(), priorIntent.action());
        String currentCommandCompletionReason = currentCommandCompleted
            ? commandCompletionReason(priorIntent)
            : "";
        observeMiningWorkspaceTransactionCompletion(
            client,
            player,
            priorIntent,
            currentCommandCompleted,
            currentCommandCompletionReason,
            nowMs
        );
        if (currentCommandCompleted && !"stop".equals(priorIntent.action())) {
            brainLink.completeCurrentCommand(priorIntent.commandId(), currentCommandCompletionReason, nowMs);
        }

        // Snapshot is built on the client thread; BrainLink dispatches the brain call
        // off-thread and never blocks this tick.
        // PERF: build + serialize ONLY on ticks where BrainLink will actually dispatch — poll()
        // discards the payload otherwise. ClientSnapshot.from runs a nearby-reachable-logs world
        // scan (plus inventory sweeps + JSON serialization); paying that every tick was the
        // dominant render-thread tax (sustained 80-340 ms ticks, worst in forests).
        String snapshotJson = null;
        VoxelCell snapshotStableAnchor = null;
        boolean brainDispatchCandidate = brainLink.wouldDispatch(nowMs);
        long dispatchedRequestsBeforePoll = brainDispatchCandidate
            ? brainLink.diagnostics(nowMs).dispatchedRequestCount()
            : -1L;
        if (brainDispatchCandidate) {
            MiningWorkspaceSnapshot workspaceSnapshot = miningWorkspaceSnapshot(client, player);
            WorldIdentityResolver.Resolution worldIdentity = resolveSnapshotWorldIdentity(client);
            String snapshotDimension = client.world == null
                ? ""
                : client.world.getRegistryKey().getValue().toString();
            OpportunitySnapshotWire opportunitySnapshot = refreshOpportunitySnapshot(
                client.world,
                player,
                worldIdentity,
                snapshotDimension,
                nowMs
            );
            long snapshotWorldTime = Math.floorMod(client.world.getTimeOfDay(), 24_000L);
            int snapshotNearbyHostiles = nearbyOpportunityHostileCount(player);
            RespawnVerificationTracker.Snapshot respawnVerification =
                respawnVerificationTracker.snapshot(worldIdentity.opaqueWorldId());
            if (player.isOnGround() && !player.isTouchingWater()) {
                // Keep the exact grounded/dry position carried by this request. The mission brain
                // freezes its surface anchor from the same snapshot; associating admission with
                // the dispatched request prevents a delayed reply from anchoring at the player's
                // newer (possibly underground) live feet.
                snapshotStableAnchor = voxelFeet(player);
            }
            // Reuse the existing command-context field to identify the exact command whose
            // terminal result this snapshot acknowledges. This avoids a wire-schema expansion and
            // lets the brain distinguish a retransmitted old completion from a newly executed retry.
            String snapshotCommandContextId = currentCommandCompleted && priorIntent != null
                ? priorIntent.commandId()
                : activeNavigationCommandId;
            ClientSnapshot snapshot = ClientSnapshot.from(
                instanceId,
                player,
                nowMs,
                currentInputState,
                snapshotCommandContextId,
                currentCommandCompleted,
                currentCommandCompletionReason,
                activeNavigationRouteComputed,
                activeNavigationWaypoints,
                activeNavigationWaypointIndex,
                client.world,
                terrainColumnProbe,
                snapshotNearbyLogsCached(client, player, nowMs),
                farPerceptionSummary(player),
                nowMs - nav3dLastDigActiveMs < NAV_DIG_ACTIVE_WINDOW_MS,
                workspaceSnapshot,
                worldIdentity,
                snapshotDimension,
                respawnVerification,
                opportunitySnapshot,
                snapshotWorldTime,
                snapshotNearbyHostiles,
                villageOpportunityExecutor.receiptSnapshot()
            );
            snapshotJson = GSON.toJson(snapshot);
        }
        brainLink.poll(snapshotJson, nowMs);
        BrainLink.Intent effective = brainLink.effectiveIntent(nowMs);
        villageOpportunityExecutor.observeEffectiveIntentHandoff(
            client, player, effective, nowMs);
        boolean villageHandoffPending =
            villageOpportunityExecutor.handoffCleanupPending();
        if (!villageHandoffPending) {
            observeSurfaceReturnTrail(client, player, effective, nowMs);
        }
        BrainLink.Diagnostics brainDiagnostics = brainLink.diagnostics(nowMs);
        if (snapshotStableAnchor != null
            && brainDiagnostics.dispatchedRequestCount() > dispatchedRequestsBeforePoll) {
            surfaceReturnLastDispatchedStableAnchor = snapshotStableAnchor;
        }
        hudDiagnostics = brainDiagnostics;
        hudEffective = effective;
        logTtlExpiry(effective, brainDiagnostics);
        if (!villageHandoffPending) {
            applyServerCommands(client, effective);
            enforceGatherTreeCommandDeadlineBeforeReflex(client, player, effective, nowMs);
            enforceMineNearbyStoneCompletionBeforeReflex(client, player, effective, nowMs);
        }
        villageOpportunityExecutor.enforceInventoryTerminalBeforeReflex(
            client, player, effective, nowMs);
        ControlDecision engagedGolemSafetyBarrier =
            villageOpportunityExecutor.resolveEngagedGolemSafetyBeforeReflex(
                client, player, nowMs);
        if (engagedGolemSafetyBarrier == null) {
        // R7 combat reflex: highest-priority fast-loop guard. Threat response (engage/flee/logout)
        // preempts everything else — the bot fights or bails before it eats or runs its normal task.
        CombatController.Result combat = combatController.tick(client, player, nowMs);
        if (combat.active()) {
            villageOpportunityExecutor.preemptForReflex(
                client, player, effective, nowMs, "combat");
            FabricMovementAuthority.Applied appliedMovement = movementAuthority.commit(
                client,
                player,
                combat.input(),
                LocomotionDemand.passthrough(
                    LookDemand.Owner.COMBAT,
                    combat.input(),
                    false,
                    effective == null ? "combat" : effective.commandId(),
                    combat.reason()
                ),
                FabricMovementAuthority.GuardOverride.PREEMPTION,
                nowMs
            );
            currentInputState = appliedMovement.input();
            gazeAuthority.commit(player, combat.lookDemand(), nowMs);
            InteractionAppliedReceipt interactionReceipt = interactionAuthority.commit(
                client,
                player,
                combat.interactionDemand(),
                combat.interactionPayload(),
                nowMs
            );
            combatController.acknowledgeInteraction(interactionReceipt);
            hudActiveLayer = "combat";
            logBrainTiming(nowMs, tickStartNs, brainDiagnostics);
            return;
        }
        // R6 survival reflex: a fast-loop guard that preempts normal control when the bot must
        // eat, retreat, or log out. Brain polling above still runs so intent stays warm; we only
        // override the control output for this tick. Same preempt-and-return shape as the respawn
        // guard earlier in this method.
        SurvivalController.Result survival = survivalController.tick(client, player, nowMs);
        if (survival.active()) {
            villageOpportunityExecutor.preemptForReflex(
                client, player, effective, nowMs, "survival");
            FabricMovementAuthority.Applied appliedMovement = movementAuthority.commit(
                client,
                player,
                survival.input(),
                LocomotionDemand.passthrough(
                    LookDemand.Owner.SURVIVAL,
                    survival.input(),
                    false,
                    effective == null ? "survival" : effective.commandId(),
                    survival.reason()
                ),
                FabricMovementAuthority.GuardOverride.PREEMPTION,
                nowMs
            );
            currentInputState = appliedMovement.input();
            gazeAuthority.commit(player, survival.lookDemand(), nowMs);
            interactionAuthority.commit(
                client,
                player,
                survival.interactionDemand(),
                survival.interactionPayload(),
                nowMs
            );
            traceNav3dTick(player, currentInputState, survival.reason(), true);
            hudActiveLayer = "survival";
            logBrainTiming(nowMs, tickStartNs, brainDiagnostics);
            return;
        }
        }
        ControlDecision villageHandoffCleanup =
            villageOpportunityExecutor.resolveEffectiveIntentHandoffCleanup(
                client, player, effective, nowMs);
        // Reuse the per-tick context for the objective registry (PR-0 scaffolding: reset every tick
        // before dispatch; the registry is empty in PR-0 so resolveControl behavior is unchanged).
        tickContext.reset(client, player, nowMs, effective);
        ControlDecision decision = engagedGolemSafetyBarrier != null
            ? engagedGolemSafetyBarrier
            : villageHandoffCleanup != null
                ? villageHandoffCleanup
                : resolveControl(client, player, effective, nowMs);
        currentInputState = decision.input();
        LookDemand.Owner movementOwner = decision.lookDemand() != null
            && decision.lookDemand().owner() == LookDemand.Owner.HUNT
                ? LookDemand.Owner.HUNT
                : LookDemand.Owner.NORMAL;
        LocomotionDemand locomotionDemand = decision.locomotionDemand() == null
            ? LocomotionDemand.passthrough(
                movementOwner,
                decision.input(),
                sprintEligibleReason(decision.intent().reason()),
                decision.intent().commandId(),
                decision.intent().reason()
            )
            : decision.locomotionDemand();
        double locomotionObservationYaw = gazeAuthority.locomotionObservationYaw(player);
        InputState movementGuardInput = movementAuthority.previewInput(
            client,
            player,
            currentInputState,
            locomotionDemand,
            locomotionObservationYaw,
            nowMs
        );
        FabricMovementAuthority.GuardOverride movementGuard =
            FabricMovementAuthority.GuardOverride.NONE;
        // GLOBAL edge-guard (an observed death: a routed search leg walked into a natural
        // shaft mouth and fell 44 blocks — the per-path guard only covered direct fallbacks). Any
        // full-forward, on-ground, non-sneaking walk now gets the >3-drop lookahead as a final-line
        // reflex regardless of which code path drives it: staircase steps (1-drop) and water
        // landings remain allowed by the guard itself; sneak work (bridging overhang) is exempt.
        if (movementGuardInput.pressingForward()
            && !movementGuardInput.sneaking()
            && player.isOnGround()
            && !player.isTouchingWater()
            && !isStaircaseDrivenIntent(decision.intent())
            && edgeGuardBlocksForward(
                client,
                player,
                edgeGuardYaw(player, decision),
                edgeGuardLookaheadForIntent(client, player, decision.intent())
            )) {
            currentInputState = InputState.stop();
            movementGuard = FabricMovementAuthority.GuardOverride.EDGE_GUARD;
            // Veto-FEEDBACK (observed: machinery retried into the veto for up to 189
            // ticks): record the refused cells so route perception blocks them, and after a short
            // streak force the active route to recompute — it then paths around the edge, or fails
            // into the existing target_rejected_no_path / abandon flows.
            recordEdgeVeto(player, nowMs);
            String vetoCommandId = decision.intent().commandId() == null ? "" : decision.intent().commandId();
            int edgeVetoCount = edgeVetoStreak.record(vetoCommandId);
            if (edgeVetoCount % EDGE_VETO_REROUTE_STREAK == 0) {
                clearNavigationState();
                LOGGER.warn(
                    "navigation.edge_guard_feedback instanceId={} commandId={} streak={} vetoedCells={}",
                    instanceId,
                    vetoCommandId,
                    edgeVetoCount,
                    vetoedEdgeCells.size()
                );
            }
            // Channel 2 — LAST RESORT (regression: at 10 ticks this killed legitimate tree
            // approaches; 7 clusters found, 0 logs gathered). Only after ~3 s of continuous veto,
            // when rerouting demonstrably did not help, abandon the gather target so selection
            // replaces it.
            if (edgeVetoCount % EDGE_VETO_ABANDON_STREAK == 0) {
                if (activeGatherTree != null && vetoCommandId.startsWith(activeGatherTree.commandId)) {
                    if (activeGatherTree.currentTarget != null) {
                        activeGatherTree.abandonedTargets.add(activeGatherTree.currentTarget);
                        // Also blacklist the target's XZ column: without this the immediate reselect
                        // rebuilds the SAME drop/trunk and re-arms the veto streak -- the collect-side
                        // reset-churn that loops at multi-second/tick on a lip the edge-guard keeps vetoing
                        // (run 215046). recordGatherTreeAbandonedDropColumns tolerates a null drop.
                        recordGatherTreeAbandonedDropColumns(activeGatherTree, activeGatherTree.currentTarget, null);
                        LOGGER.warn(
                            "navigation.edge_guard_abandon instanceId={} commandId={} target={} streak={}",
                            instanceId,
                            vetoCommandId,
                            activeGatherTree.currentTarget.toShortString(),
                            edgeVetoCount
                        );
                    }
                    resetGatherTreeCurrentTarget(activeGatherTree);
                } else if (activeGatherTreeSearch != null
                    && vetoCommandId.startsWith(activeGatherTreeSearch.commandId)) {
                    GridCell vetoedColumn = new GridCell(
                        (int) Math.floor(player.getX()), (int) Math.floor(player.getZ()));
                    rejectGatherTreeSearchEdgeRoute(
                        activeGatherTreeSearch,
                        vetoCommandId,
                        vetoedColumn,
                        edgeVetoCount,
                        nowMs
                    );
                }
            }
            if (nowMs - lastEdgeGuardLogAtMs > 1_000L) {
                lastEdgeGuardLogAtMs = nowMs;
                LOGGER.warn(
                    "navigation.edge_guard_global instanceId={} commandId={} reason={} x={} y={} z={}",
                    instanceId,
                    decision.intent().commandId(),
                    decision.intent().reason(),
                    (int) Math.floor(player.getX()),
                    (int) Math.floor(player.getY()),
                    (int) Math.floor(player.getZ())
                );
            }
        } else {
            edgeVetoStreak.reset();
        }
        // Vanilla-parity fairness guard (reported: bot walking with a crafting GUI open —
        // impossible for a human, whose movement keys go to the GUI). Any movement intent while a
        // container screen is open closes the screen FIRST (what a human does: ESC, then walk) and
        // stands still for this tick. Craft/smelt flows are stationary while their screens are open,
        // so this only fires on the leaky transitions that forgot to close.
        if (inputWantsMovement(movementGuardInput)
            && client.currentScreen instanceof net.minecraft.client.gui.screen.ingame.HandledScreen) {
            player.closeHandledScreen();
            currentInputState = InputState.stop();
            movementGuard = FabricMovementAuthority.GuardOverride.SCREEN_GUARD;
            if (nowMs - lastScreenCloseGuardLogMs > 1_000L) {
                lastScreenCloseGuardLogMs = nowMs;
                LOGGER.warn(
                    "fairness.screen_close_before_move instanceId={} commandId={} reason={}",
                    instanceId,
                    decision.intent().commandId(),
                    decision.intent().reason()
                );
            }
        }
        FabricMovementAuthority.Applied appliedMovement = movementAuthority.commit(
            client,
            player,
            currentInputState,
            locomotionDemand,
            movementGuard,
            locomotionObservationYaw,
            nowMs
        );
        currentInputState = appliedMovement.input();
        traceNav3dTick(player, currentInputState, decision.intent().reason(), false);
        hudActiveLayer = "control";
        hudLastControlReason = decision.intent().reason();
        logIntentTransition(decision.intent(), brainDiagnostics);
        LookDemand lookDemand = decision.lookDemand() == null
            ? LookDemand.fromNormalDecision(
                decision.intent(),
                currentInputState,
                player.getYaw(),
                player.getPitch()
            )
            : decision.lookDemand();
        gazeAuthority.commit(player, lookDemand, decision.legacyLookDemand(), nowMs);
        String verifiedPlacementRequestId = blockPlaceController.consumeVerifiedRequestId();
        if (!verifiedPlacementRequestId.isBlank()) {
            interactionAuthority.recordUseVerification(
                verifiedPlacementRequestId,
                true,
                nowMs
            );
        }
        InteractionAppliedReceipt interactionReceipt = interactionAuthority.commit(
            client,
            player,
            decision.interactionDemand(),
            decision.interactionPayload(),
            nowMs
        );
        blockPlaceController.acceptReceipt(interactionReceipt);
        acknowledgeContainerInteraction(interactionReceipt);
        huntSheepExecutor.acknowledgeInteraction(interactionReceipt);
        useBedExecutor.observeInteractionReceipt(interactionReceipt);
        villageOpportunityExecutor.observeInteractionReceipt(interactionReceipt);
        logBrainTiming(nowMs, tickStartNs, brainDiagnostics);
    }

    private void acknowledgeContainerInteraction(InteractionAppliedReceipt receipt) {
        if (receipt == null
            || !receipt.applied()
            || receipt.action() != InteractionDemand.Action.USE_BLOCK) {
            return;
        }
        if (activeCraft3x3 != null
            && receipt.requestId().equals(activeCraft3x3.pendingTableOpenRequestId)) {
            Craft3x3Run run = activeCraft3x3;
            run.tableOpenAttempts++;
            run.tableOpenInteractedAtMs = receipt.timestampMs();
            run.tableOpenTarget = run.pendingTableOpenTarget;
            run.appliedTableOpenRequestId = receipt.requestId();
            run.containerAccessRequestId = receipt.requestId();
            run.pendingTableOpenRequestId = "";
            run.pendingTableOpenTarget = null;
            run.pendingTableOpenHit = null;
            run.lastTableOpenWaitLogAtMs = 0L;
        }
        if (activeSmeltCharcoal != null
            && receipt.requestId().equals(activeSmeltCharcoal.pendingFurnaceOpenRequestId)) {
            SmeltCharcoalRun run = activeSmeltCharcoal;
            run.directFurnaceOpenAttempts++;
            run.furnaceOpenInteractedAtMs = receipt.timestampMs();
            run.appliedFurnaceOpenRequestId = receipt.requestId();
            run.containerAccessRequestId = receipt.requestId();
            run.pendingFurnaceOpenRequestId = "";
            run.pendingFurnaceOpenHit = null;
        }
    }

    private ControlDecision blockUseDecision(
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        String requestId,
        String stage,
        String stageIdentity,
        BlockHitResult hit,
        String reason
    ) {
        int emptyHandSlot = selectTableOpenHotbarSlot(player);
        if (emptyHandSlot < 0) {
            return new ControlDecision(
                stopFrom(effective, reason + "_empty_main_hand_required"),
                InputState.stop()
            );
        }
        BlockPos target = hit.getBlockPos().toImmutable();
        Direction side = hit.getSide() == null ? Direction.UP : hit.getSide();
        String commandId = effective == null ? "uncommanded" : effective.commandId();
        InteractionDemand demand = InteractionDemand.useBlock(
            requestId,
            LookDemand.Owner.NORMAL,
            commandId,
            stage + ":" + stageIdentity,
            formatBlockPos(target),
            formatBlockPos(target) + ":" + side.asString(),
            reason
        );
        return new ControlDecision(
            stopFrom(effective, reason),
            InputState.stop(),
            null,
            null,
            null,
            demand,
            FabricInteractionAuthority.Payload.blockUse(
                hit,
                Hand.MAIN_HAND,
                FabricWorldActionAuthorization.BlockAuthorization.naturalAnchor()
            )
        );
    }

    private static String tableOpenRequestId(
        String commandId,
        int attempt,
        BlockPos target,
        Direction side
    ) {
        return containerOpenRequestId("table", commandId, attempt, target, side);
    }

    private static String furnaceOpenRequestId(
        String commandId,
        int attempt,
        BlockPos target,
        Direction side
    ) {
        return containerOpenRequestId("furnace", commandId, attempt, target, side);
    }

    private static String containerOpenRequestId(
        String kind,
        String commandId,
        int attempt,
        BlockPos target,
        Direction side
    ) {
        return "open:" + kind + ":"
            + (commandId == null || commandId.isBlank() ? "uncommanded" : commandId)
            + ":" + Math.max(1, attempt)
            + ":" + formatBlockPos(target)
            + ":" + (side == null ? "unknown" : side.asString());
    }

    private void pollCockpitKeybinds() {
        if (toggleBotKey != null) {
            while (toggleBotKey.wasPressed()) {
                controlEnabled = !controlEnabled;
                LOGGER.info("cockpit.toggle_bot instanceId={} controlEnabled={}", instanceId, controlEnabled);
            }
        }
        if (toggleHudKey != null) {
            while (toggleHudKey.wasPressed()) {
                cockpitHudEnabled = !cockpitHudEnabled;
                LOGGER.info("cockpit.toggle_hud instanceId={} enabled={}", instanceId, cockpitHudEnabled);
            }
        }
        if (togglePathKey != null) {
            while (togglePathKey.wasPressed()) {
                pathOverlayEnabled = !pathOverlayEnabled;
                LOGGER.info("cockpit.toggle_path instanceId={} enabled={}", instanceId, pathOverlayEnabled);
            }
        }
        // Pipeline-split diagnostic for the dead overlay key: when the PHYSICAL right-arrow is down,
        // log it (1/s). Raw hit + no toggle log above = the vanilla keybind layer lost the binding;
        // no raw hit = the press never reaches the game window (focus). Remove once diagnosed.
        MinecraftClient diagClient = MinecraftClient.getInstance();
        if (diagClient != null && diagClient.getWindow() != null) {
            long nowDiagMs = System.currentTimeMillis();
            if (nowDiagMs >= nextRawRightProbeLogMs
                && InputUtil.isKeyPressed(diagClient.getWindow().getHandle(), GLFW.GLFW_KEY_RIGHT)) {
                nextRawRightProbeLogMs = nowDiagMs + 1000L;
                LOGGER.info("cockpit.raw_right_arrow_down instanceId={}", instanceId);
            }
        }
        if (openEditorKey != null) {
            while (openEditorKey.wasPressed()) {
                MinecraftClient mc = MinecraftClient.getInstance();
                if (mc != null && cockpitLayout != null) {
                    mc.setScreen(new CockpitScreen(cockpitLayout, cockpitConfigPath()));
                    LOGGER.info("cockpit.open_editor instanceId={}", instanceId);
                }
            }
        }
    }

    // Fail-safe status HUD: a top-left panel of what the bot + brain are doing. Reads only hoisted state +
    // the live player (same client thread as the tick), and is fully wrapped so a render error can NEVER
    // crash the client or a normal run — on any throw it disables itself and logs once. Respects F1.
    private void renderCockpitHud(DrawContext context) {
        try {
            if (!cockpitHudEnabled || context == null) {
                return;
            }
            MinecraftClient client = MinecraftClient.getInstance();
            if (client == null || client.player == null || client.textRenderer == null) {
                return;
            }
            if (client.options != null && client.options.hudHidden) {
                return;
            }
            // A menu/editor is open: the in-play HUD must NOT draw behind it. (HudRenderCallback still
            // fires while a Screen is open, which otherwise renders the live HUD as ghost text behind the
            // cockpit editor's dimmed background.)
            if (client.currentScreen != null) {
                return;
            }
            ClientPlayerEntity player = client.player;
            BrainLink.Diagnostics d = hudDiagnostics;
            // Debounce the "thinking" indicator: flag it only when a brain call has actually been
            // outstanding a while, so the panels don't flicker THINKING/ok on every fast local poll.
            boolean brainThinking = controlEnabled && d != null && d.inFlight() && d.currentRequestAgeMs() >= 250L;
            CockpitHud.Status status = new CockpitHud.Status(
                controlEnabled,
                hudActiveLayer,
                d == null ? "" : d.currentAction(),
                d == null ? "" : d.currentReason(),
                hudLastControlReason,
                brainThinking,
                d == null ? 0L : d.currentIntentRemainingTtlMs(),
                d == null ? -1L : d.lastRoundTripMs(),
                d == null ? "" : d.currentCommandId(),
                player.getHealth(),
                (int) Math.floor(player.getY()),
                d == null ? -1L : d.msSinceResponseMs()
            );
            renderCockpitPanel(context, client, CockpitLayout.STATUS,
                CockpitHud.lines(status), controlEnabled ? 0xFF55FF55 : 0xFFFF5555);
            renderCockpitPanel(context, client, CockpitLayout.DEEPSEEK,
                CockpitHud.deepSeekLines(
                    d == null ? "none" : d.planSource(),
                    d == null ? "" : d.planReason(),
                    brainThinking),
                0xFF55FFFF);
        } catch (Throwable t) {
            cockpitHudEnabled = false;
            LOGGER.warn("cockpit.hud_render_failed instanceId={} disabling reason={}", instanceId, String.valueOf(t));
        }
    }

    /** Draw a layout panel at its configured position/scale, honoring collapsed (title-only) + enabled. */
    private void renderCockpitPanel(DrawContext context, MinecraftClient client, String panelId, List<String> lines, int headerColor) {
        if (cockpitLayout == null) {
            return;
        }
        CockpitLayout.PanelConfig cfg = cockpitLayout.get(panelId);
        if (cfg == null || !cfg.enabled) {
            return;
        }
        List<String> shown = cfg.collapsed && !lines.isEmpty() ? List.of(lines.get(0)) : lines;
        MatrixStack matrices = context.getMatrices();
        matrices.push();
        matrices.translate(cfg.x, cfg.y, 0.0);
        float scale = cfg.clampedScale();
        if (scale != 1.0f) {
            matrices.scale(scale, scale, 1.0f);
        }
        drawCockpitPanel(context, client, 0, 0, shown, headerColor);
        matrices.pop();
    }

    private Path cockpitConfigPath() {
        try {
            return FabricLoader.getInstance().getConfigDir().resolve("mcbot_cockpit.json");
        } catch (Throwable t) {
            return null; // CockpitLayout.load(null) -> defaults
        }
    }

    /** Draw one labeled HUD panel (translucent backing + colored header line); returns its bottom Y. */
    private int drawCockpitPanel(DrawContext context, MinecraftClient client, int x, int y, List<String> lines, int headerColor) {
        int lineHeight = client.textRenderer.fontHeight + 2;
        int width = 0;
        for (String line : lines) {
            width = Math.max(width, client.textRenderer.getWidth(line));
        }
        context.fill(x - 2, y - 2, x + width + 2, y + lines.size() * lineHeight, 0x90000000);
        int cursorY = y;
        for (int i = 0; i < lines.size(); i++) {
            context.drawText(client.textRenderer, lines.get(i), x, cursorY, i == 0 ? headerColor : 0xFFFFFFFF, true);
            cursorY += lineHeight;
        }
        return y + lines.size() * lineHeight;
    }

    // Fail-safe world-space path overlay (default OFF): the bot's nav waypoints drawn as a translucent
    // cyan line ribbon at feet level — an ORIGINAL visual, not a Baritone clone. Waypoints are 2-D grid
    // cells (x,z); the path height is the player's feet Y. Fully wrapped so a wrong/blind render transform
    // can never crash the client — on any throw it disables itself and logs once.
    private void renderPathOverlay(WorldRenderContext context) {
        try {
            if (!pathOverlayEnabled || context == null) {
                return;
            }
            // Render the path the bot actually follows: the client-computed A* route in
            // activeNavigationWaypoints. The brain intent's waypoints() are almost always empty (the route is
            // computed locally from a target, not sent by the brain), so reading hudEffective.waypoints() left
            // the overlay with nothing to draw every frame -- the "completely invisible" path.
            // Prefer the live 3-D collect route (populated while the 3-D nav drives); else the 2-D A* route.
            // activeNavigationWaypoints is empty during a 3-D collect, which is why the overlay had no data.
            List<GridCell> waypoints =
                nav3dOverlayWaypoints.size() >= 2 ? nav3dOverlayWaypoints : activeNavigationWaypoints;
            if (waypoints == null || waypoints.size() < 2) {
                return;
            }
            MatrixStack matrices = context.matrixStack();
            VertexConsumerProvider consumers = context.consumers();
            Camera camera = context.camera();
            MinecraftClient client = MinecraftClient.getInstance();
            if (matrices == null || consumers == null || camera == null || client == null || client.player == null) {
                return;
            }
            Vec3d cam = camera.getPos();
            double pathY = Math.floor(client.player.getY()) + 0.05D;
            VertexConsumer buffer = consumers.getBuffer(RenderLayer.getLines());
            MatrixStack.Entry entry = matrices.peek();
            Matrix4f positionMatrix = entry.getPositionMatrix();
            for (int i = 0; i < waypoints.size() - 1; i++) {
                GridCell a = waypoints.get(i);
                GridCell b = waypoints.get(i + 1);
                float ax = (float) (a.x() + 0.5D - cam.x);
                float ay = (float) (pathY - cam.y);
                float az = (float) (a.z() + 0.5D - cam.z);
                float bx = (float) (b.x() + 0.5D - cam.x);
                float by = (float) (pathY - cam.y);
                float bz = (float) (b.z() + 0.5D - cam.z);
                float nx = bx - ax;
                float ny = by - ay;
                float nz = bz - az;
                float len = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);
                if (len <= 0.0001F) {
                    continue;
                }
                nx /= len;
                ny /= len;
                nz /= len;
                buffer.vertex(positionMatrix, ax, ay, az).color(80, 230, 255, 170).normal(entry, nx, ny, nz);
                buffer.vertex(positionMatrix, bx, by, bz).color(80, 230, 255, 170).normal(entry, nx, ny, nz);
            }
            // AFTER_TRANSLUCENT does not reliably auto-flush the lines layer, so draw it explicitly -- this is why
            // the overlay had real data + a valid render context yet stayed completely invisible.
            if (consumers instanceof VertexConsumerProvider.Immediate immediate) {
                immediate.draw(RenderLayer.getLines());
            }
        } catch (Throwable t) {
            pathOverlayEnabled = false;
            LOGGER.warn("cockpit.path_overlay_failed instanceId={} disabling reason={}", instanceId, String.valueOf(t));
        }
    }

    /** Real HTTP transport for {@link BrainLink}. Runs on the brain-ipc thread, not the client thread. */
    private String sendToBrain(String body) throws Exception {
        HttpRequest request = HttpRequest.newBuilder(brainUri)
            .timeout(Duration.ofMillis(BRAIN_HTTP_TIMEOUT_MS))
            .header("content-type", "text/plain; charset=utf-8")
            .POST(HttpRequest.BodyPublishers.ofString(body))
            .build();
        return httpClient.send(request, HttpResponse.BodyHandlers.ofString()).body();
    }

    private void ensureControlledInput(ClientPlayerEntity player) {
        if (!(player.input instanceof McbotControlledInput)) {
            player.input = new McbotControlledInput();
            LOGGER.info("input.install instanceId={} mode=direct_state_control", instanceId);
        }
    }

    /** Hand control back to the human: swap the bot's Input out for vanilla keyboard input so the player
     * can walk/look normally while the bot is toggled OFF. No-op once already on vanilla input. */
    private void restoreManualInput(ClientPlayerEntity player, MinecraftClient client) {
        if (player.input instanceof McbotControlledInput && client.options != null) {
            player.input = new KeyboardInput(client.options);
            currentInputState = InputState.stop();
            // V1: re-grab the pointer so the operator gets mouse-look in manual mode -- the bot-driving
            // ticks released it (NO_CURSOR_GRAB). Fires once on the toggle-off transition (the guard
            // above no-ops once already on vanilla input); vanilla maintains the grab afterward.
            if (client.mouse != null) {
                client.mouse.lockCursor();
            }
            LOGGER.info("input.restore instanceId={} mode=manual_keyboard", instanceId);
        }
    }

    private void maybeDriveAutoSingleplayerMenu(MinecraftClient client, long nowMs) {
        if (!autoSingleplayer || nowMs - lastAutoSingleplayerStepMs < 1000L) {
            return;
        }
        Screen screen = client.currentScreen;
        if (screen == null) {
            return;
        }

        boolean pressed = autoCreateNewWorld
            ? pressButton(screen, "Singleplayer") || pressButton(screen, "Create New World")
            : pressButton(screen, "Singleplayer")
                || pressButton(screen, "Play Selected World")
                || pressButton(screen, "Create New World");
        if (pressed) {
            lastAutoSingleplayerStepMs = nowMs;
        }
    }

    private boolean pressButton(Screen screen, String label) {
        for (Element child : screen.children()) {
            if (child instanceof ButtonWidget button
                && button.active
                && button.visible
                && label.equals(button.getMessage().getString())) {
                boolean submitsFreshWorld = autoCreateNewWorld
                    && screen instanceof CreateWorldScreen
                    && "Create New World".equals(label);
                LOGGER.info("auto_singleplayer.press screen={} button={}", screen.getTitle().getString(), label);
                Set<String> preexistingSaveNames = submitsFreshWorld
                    ? captureLocalSaveDirectoryNames()
                    : null;
                button.onPress();
                if (submitsFreshWorld) {
                    freshWorldCreationSubmitted = true;
                    createdFreshWorldIdentity = "";
                    freshWorldPreexistingSaveInventoryCaptured = preexistingSaveNames != null;
                    freshWorldPreexistingSaveNames = preexistingSaveNames == null
                        ? Set.of()
                        : preexistingSaveNames;
                }
                return true;
            }
        }
        return false;
    }

    private static Set<String> captureLocalSaveDirectoryNames() {
        Path savesDirectory = FabricLoader.getInstance().getGameDir().resolve("saves");
        if (!Files.isDirectory(savesDirectory)) {
            return Set.of();
        }
        try (var entries = Files.list(savesDirectory)) {
            return entries
                .filter(Files::isDirectory)
                .map(Path::getFileName)
                .filter(Objects::nonNull)
                .map(Path::toString)
                .collect(java.util.stream.Collectors.toUnmodifiableSet());
        } catch (java.io.IOException | SecurityException unavailable) {
            return null;
        }
    }

    private void maybeRequestRespawn(ClientPlayerEntity player, long nowMs) {
        if (nowMs - lastRespawnRequestMs < 1000L) {
            return;
        }
        lastRespawnRequestMs = nowMs;
        currentInputState = InputState.stop();
        player.requestRespawn();
        LOGGER.warn("player.respawn_request instanceId={} reason=dead_or_zero_health", instanceId);
    }

    // Whether a brain command (by id) has FINISHED — completed or failed (both are recorded). Lets the
    // brain reuse the same commandId while a multi-tick command runs (the client continues a command on
    // the same id but RESTARTS on a new id) and mint a fresh id only once it is done — fixing 2x2-craft
    // restart spam and repeated-action dedup. Uses recorded completions (not transient "active" state)
    // so a craft that finishes within a single tick, between brain polls, is still detected.
    private boolean isCommandCompleted(String commandId) {
        if (commandId == null || commandId.isEmpty()) {
            return false;
        }
        return gatherLogExecutor.isFinished(commandId)
            || completedGatherTreeCommandIds.contains(commandId)
            || mineStoneExecutor.isFinished(commandId)
            || completedBreakBlockCommandIds.contains(commandId)
            || craft2x2Executor.isFinished(commandId)
            || completedCraft3x3CommandIds.contains(commandId)
            || completedSmeltCharcoalCommandIds.contains(commandId)
            || completedMakeCharcoalCommandIds.contains(commandId)
            || placeWorkstationExecutor.isFinishedTable(commandId)
            || placeWorkstationExecutor.isFinishedFurnace(commandId)
            || retrieveTableExecutor.isFinished(commandId)
            || finishedEquipArmorCommandReasons.containsKey(commandId)
            || finishedEatCommandReasons.containsKey(commandId)
            || finishedWorkspaceFallbackCommandReasons.containsKey(commandId)
            || finishedWorkspaceSuppressedCommandReasons.containsKey(commandId)
            || descentExecutor.isFinished(commandId)
            || finishedMineNearbyStoneCommandReasons.containsKey(commandId)
            || finishedMineNearbyIronCommandReasons.containsKey(commandId)
            || finishedMineNearbyDiamondCommandReasons.containsKey(commandId)
            || finishedMineNearbyCoalCommandReasons.containsKey(commandId)
            || finishedReturnStaircaseCommandReasons.containsKey(commandId)
            || finishedR2MineStoneReturnCommandReasons.containsKey(commandId)
            || finishedR5IronChainCommandReasons.containsKey(commandId)
            || huntSheepExecutor.isFinished(commandId)
            || useBedExecutor.isFinished(commandId)
            || villageOpportunityExecutor.isFinished(commandId)
            || finishedNavigationCommandReasons.containsKey(commandId);
    }

    private boolean isCommandCompleted(String commandId, String action) {
        if (commandId == null || commandId.isEmpty()) {
            return false;
        }
        String normalizedAction = action == null ? "" : action;
        if (finishedWorkspaceFallbackCommandReasons.containsKey(commandId)
            || finishedWorkspaceSuppressedCommandReasons.containsKey(commandId)) {
            return true;
        }
        if (normalizedAction.isBlank() || "stop".equals(normalizedAction)) {
            return isCommandCompleted(commandId);
        }
        if ("break_block".equals(normalizedAction)) {
            return completedBreakBlockCommandIds.contains(commandId);
        }
        if ("gather_log".equals(normalizedAction)) {
            return gatherLogExecutor.isFinished(commandId);
        }
        if ("gather_tree".equals(normalizedAction)) {
            return completedGatherTreeCommandIds.contains(commandId);
        }
        if ("mine_stone".equals(normalizedAction)) {
            return mineStoneExecutor.isFinished(commandId);
        }
        if ("descend_staircase".equals(normalizedAction)) {
            return descentExecutor.isFinished(commandId);
        }
        if ("mine_nearby_stone".equals(normalizedAction)) {
            return finishedMineNearbyStoneCommandReasons.containsKey(commandId);
        }
        if ("mine_nearby_iron".equals(normalizedAction)) {
            return finishedMineNearbyIronCommandReasons.containsKey(commandId);
        }
        if ("mine_nearby_diamond".equals(normalizedAction)) {
            return finishedMineNearbyDiamondCommandReasons.containsKey(commandId);
        }
        if ("mine_nearby_coal".equals(normalizedAction)) {
            return finishedMineNearbyCoalCommandReasons.containsKey(commandId);
        }
        if ("return_staircase".equals(normalizedAction)) {
            return finishedReturnStaircaseCommandReasons.containsKey(commandId);
        }
        if ("navigate_to_point".equals(normalizedAction)) {
            return finishedNavigationCommandReasons.containsKey(commandId);
        }
        if (Craft2x2RecipePlanner.isCraftAction(normalizedAction)) {
            return craft2x2Executor.isFinished(commandId);
        }
        if (Craft3x3RecipePlanner.isCraftAction(normalizedAction)) {
            return completedCraft3x3CommandIds.contains(commandId);
        }
        if (FurnaceSmeltRecipe.fromAction(normalizedAction) != null) {
            return completedSmeltCharcoalCommandIds.contains(commandId);
        }
        if ("make_charcoal".equals(normalizedAction)) {
            return completedMakeCharcoalCommandIds.contains(commandId);
        }
        if ("place_table".equals(normalizedAction)) {
            return placeWorkstationExecutor.isFinishedTable(commandId);
        }
        if ("place_furnace".equals(normalizedAction)) {
            return placeWorkstationExecutor.isFinishedFurnace(commandId);
        }
        if ("retrieve_table".equals(normalizedAction)) {
            return retrieveTableExecutor.isFinished(commandId);
        }
        if ("equip_armor".equals(normalizedAction)) {
            return finishedEquipArmorCommandReasons.containsKey(commandId);
        }
        if ("eat".equals(normalizedAction)) {
            return finishedEatCommandReasons.containsKey(commandId);
        }
        if ("r2_mine_stone_return".equals(normalizedAction)) {
            return finishedR2MineStoneReturnCommandReasons.containsKey(commandId);
        }
        if ("r5_iron_chain".equals(normalizedAction)) {
            return finishedR5IronChainCommandReasons.containsKey(commandId);
        }
        if ("hunt_sheep".equals(normalizedAction)) {
            return huntSheepExecutor.isFinished(commandId);
        }
        if ("use_bed".equals(normalizedAction)) {
            return useBedExecutor.isFinished(commandId);
        }
        if (villageOpportunityExecutor.handles(normalizedAction)) {
            return villageOpportunityExecutor.isFinished(commandId);
        }
        return isCommandCompleted(commandId);
    }

    private String commandCompletionReason(String commandId, String fallbackAction) {
        String fallback = fallbackAction == null || fallbackAction.isBlank()
            ? "command_complete"
            : fallbackAction + "_recorded_complete";
        if (commandId == null || commandId.isEmpty()) {
            return fallback;
        }
        String workspaceFallback = finishedWorkspaceFallbackCommandReasons.get(commandId);
        if (workspaceFallback != null && !workspaceFallback.isBlank()) {
            return workspaceFallback;
        }
        String action = fallbackAction == null ? "" : fallbackAction;
        if (!action.isBlank() && !"stop".equals(action)) {
            String actionReason = commandCompletionReasonForAction(commandId, action);
            return actionReason == null || actionReason.isBlank() ? fallback : actionReason;
        }
        String navigationReason = finishedNavigationCommandReasons.get(commandId);
        if (navigationReason != null && !navigationReason.isBlank()) {
            return navigationReason;
        }
        String gatherReason = gatherLogExecutor.finishedReason(commandId);
        if (gatherReason != null && !gatherReason.isBlank()) {
            return gatherReason;
        }
        String villageReason = villageOpportunityExecutor.finishedReason(commandId);
        if (villageReason != null && !villageReason.isBlank()) {
            return villageReason;
        }
        String gatherTreeReason = finishedGatherTreeCommandReasons.get(commandId);
        if (gatherTreeReason != null && !gatherTreeReason.isBlank()) {
            return gatherTreeReason;
        }
        String craft2x2Reason = craft2x2Executor.finishedReason(commandId);
        if (craft2x2Reason != null && !craft2x2Reason.isBlank()) {
            return craft2x2Reason;
        }
        String craft3x3Reason = finishedCraft3x3CommandReasons.get(commandId);
        if (craft3x3Reason != null && !craft3x3Reason.isBlank()) {
            return craft3x3Reason;
        }
        String smeltReason = finishedSmeltCommandReasons.get(commandId);
        if (smeltReason != null && !smeltReason.isBlank()) {
            return smeltReason;
        }
        String makeCharcoalReason = finishedMakeCharcoalCommandReasons.get(commandId);
        if (makeCharcoalReason != null && !makeCharcoalReason.isBlank()) {
            return makeCharcoalReason;
        }
        String placeTableReason = placeWorkstationExecutor.finishedReasonTable(commandId);
        if (placeTableReason != null && !placeTableReason.isBlank()) {
            return placeTableReason;
        }
        String placeFurnaceReason = placeWorkstationExecutor.finishedReasonFurnace(commandId);
        if (placeFurnaceReason != null && !placeFurnaceReason.isBlank()) {
            return placeFurnaceReason;
        }
        String retrieveTableReason = retrieveTableExecutor.finishedReason(commandId);
        if (retrieveTableReason != null && !retrieveTableReason.isBlank()) {
            return retrieveTableReason;
        }
        String equipArmorReason = finishedEquipArmorCommandReasons.get(commandId);
        if (equipArmorReason != null && !equipArmorReason.isBlank()) {
            return equipArmorReason;
        }
        String descentReason = descentExecutor.finishedReason(commandId);
        if (descentReason != null && !descentReason.isBlank()) {
            return descentReason;
        }
        String stoneReason = finishedMineNearbyStoneCommandReasons.get(commandId);
        if (stoneReason != null && !stoneReason.isBlank()) {
            return stoneReason;
        }
        String ironReason = finishedMineNearbyIronCommandReasons.get(commandId);
        if (ironReason != null && !ironReason.isBlank()) {
            return ironReason;
        }
        String diamondReason = finishedMineNearbyDiamondCommandReasons.get(commandId);
        if (diamondReason != null && !diamondReason.isBlank()) {
            return diamondReason;
        }
        String returnReason = finishedReturnStaircaseCommandReasons.get(commandId);
        if (returnReason != null && !returnReason.isBlank()) {
            return returnReason;
        }
        String r2Reason = finishedR2MineStoneReturnCommandReasons.get(commandId);
        if (r2Reason != null && !r2Reason.isBlank()) {
            return r2Reason;
        }
        String r5Reason = finishedR5IronChainCommandReasons.get(commandId);
        if (r5Reason != null && !r5Reason.isBlank()) {
            return r5Reason;
        }
        String eatReason = finishedEatCommandReasons.get(commandId);
        if (eatReason != null && !eatReason.isBlank()) {
            return eatReason;
        }
        return fallback;
    }

    private String commandCompletionReason(BrainLink.Intent priorIntent) {
        if (priorIntent == null) {
            return "command_complete";
        }
        String action = priorIntent.action();
        String reason = priorIntent.reason();
        if ("stop".equals(action) && isRecordedCompletionReason(reason)) {
            return reason;
        }
        return commandCompletionReason(priorIntent.commandId(), action);
    }

    static boolean isRecordedCompletionReason(String reason) {
        if (reason == null || reason.isBlank()) {
            return false;
        }
        return reason.contains("_complete") || reason.contains("_failed");
    }

    private String commandCompletionReasonForAction(String commandId, String action) {
        String workspaceFallback = finishedWorkspaceFallbackCommandReasons.get(commandId);
        if (workspaceFallback != null) {
            return workspaceFallback;
        }
        String suppressed = finishedWorkspaceSuppressedCommandReasons.get(commandId);
        if (suppressed != null) {
            return suppressed;
        }
        if ("navigate_to_point".equals(action)) {
            return finishedNavigationCommandReasons.get(commandId);
        }
        if ("gather_log".equals(action)) {
            return gatherLogExecutor.finishedReason(commandId);
        }
        if ("hunt_sheep".equals(action)) {
            return huntSheepExecutor.finishedReason(commandId);
        }
        if ("use_bed".equals(action)) {
            return useBedExecutor.finishedReason(commandId);
        }
        if (villageOpportunityExecutor.handles(action)) {
            return villageOpportunityExecutor.finishedReason(commandId);
        }
        if ("gather_tree".equals(action)) {
            return finishedGatherTreeCommandReasons.get(commandId);
        }
        if (Craft2x2RecipePlanner.isCraftAction(action)) {
            return craft2x2Executor.finishedReason(commandId);
        }
        if (Craft3x3RecipePlanner.isCraftAction(action)) {
            return finishedCraft3x3CommandReasons.get(commandId);
        }
        if (FurnaceSmeltRecipe.fromAction(action) != null) {
            return finishedSmeltCommandReasons.get(commandId);
        }
        if ("make_charcoal".equals(action)) {
            return finishedMakeCharcoalCommandReasons.get(commandId);
        }
        if ("place_table".equals(action)) {
            return placeWorkstationExecutor.finishedReasonTable(commandId);
        }
        if ("place_furnace".equals(action)) {
            return placeWorkstationExecutor.finishedReasonFurnace(commandId);
        }
        if ("retrieve_table".equals(action)) {
            return retrieveTableExecutor.finishedReason(commandId);
        }
        if ("equip_armor".equals(action)) {
            return finishedEquipArmorCommandReasons.get(commandId);
        }
        if ("descend_staircase".equals(action)) {
            return descentExecutor.finishedReason(commandId);
        }
        if ("mine_nearby_stone".equals(action)) {
            return finishedMineNearbyStoneCommandReasons.get(commandId);
        }
        if ("mine_nearby_iron".equals(action)) {
            return finishedMineNearbyIronCommandReasons.get(commandId);
        }
        if ("mine_nearby_diamond".equals(action)) {
            return finishedMineNearbyDiamondCommandReasons.get(commandId);
        }
        if ("mine_nearby_coal".equals(action)) {
            return finishedMineNearbyCoalCommandReasons.get(commandId);
        }
        if ("return_staircase".equals(action)) {
            return finishedReturnStaircaseCommandReasons.get(commandId);
        }
        if ("r2_mine_stone_return".equals(action)) {
            return finishedR2MineStoneReturnCommandReasons.get(commandId);
        }
        if ("r5_iron_chain".equals(action)) {
            return finishedR5IronChainCommandReasons.get(commandId);
        }
        if ("eat".equals(action)) {
            return finishedEatCommandReasons.get(commandId);
        }
        return null;
    }

    private String finishMakeCharcoalCommand(String commandId, String completionReason) {
        recordFinishedCommand(completedMakeCharcoalCommandIds, finishedMakeCharcoalCommandReasons, commandId, completionReason);
        return completionReason;
    }

    private String finishEquipArmorCommand(String commandId, String completionReason) {
        if (commandId != null && !commandId.isBlank() && completionReason != null && !completionReason.isBlank()) {
            finishedEquipArmorCommandReasons.put(commandId, completionReason);
        }
        return completionReason;
    }

    private void recordFinishedCommand(
        Set<String> completedIds,
        Map<String, String> finishedReasons,
        String commandId,
        String completionReason
    ) {
        completedIds.add(commandId);
        if (commandId != null && !commandId.isBlank() && completionReason != null && !completionReason.isBlank()) {
            finishedReasons.put(commandId, completionReason);
        }
    }

    private void logIntentTransition(BrainLink.Intent effective, BrainLink.Diagnostics diagnostics) {
        String state = effective.action() + ":" + effective.reason();
        if (!state.equals(lastAppliedAction)) {
            LOGGER.info(
                "intent.apply instanceId={} action={} reason={} commandId={} intentAgeMs={} remainingTtlMs={} inFlight={} lastBrainRoundTripMs={}",
                instanceId,
                effective.action(),
                effective.reason(),
                effective.commandId(),
                diagnostics.currentIntentAgeMs(),
                diagnostics.currentIntentRemainingTtlMs(),
                diagnostics.inFlight(),
                diagnostics.lastRoundTripMs()
            );
            lastAppliedAction = state;
        }
    }

    private void logTtlExpiry(BrainLink.Intent effective, BrainLink.Diagnostics diagnostics) {
        if (!"stop".equals(effective.action()) || !"intent_expired".equals(effective.reason())) {
            lastTtlExpiryKey = "";
            return;
        }
        String key = diagnostics.currentCommandId()
            + ":"
            + diagnostics.currentAction()
            + ":"
            + diagnostics.currentReason()
            + ":"
            + diagnostics.completedRequestCount();
        if (key.equals(lastTtlExpiryKey)) {
            return;
        }
        lastTtlExpiryKey = key;
        LOGGER.warn(
            "brain.ttl_expired instanceId={} staleAction={} staleReason={} commandId={} intentAgeMs={} remainingTtlMs={} inFlight={} requestAgeMs={} lastBrainRoundTripMs={}",
            instanceId,
            diagnostics.currentAction(),
            diagnostics.currentReason(),
            diagnostics.currentCommandId(),
            diagnostics.currentIntentAgeMs(),
            diagnostics.currentIntentRemainingTtlMs(),
            diagnostics.inFlight(),
            diagnostics.currentRequestAgeMs(),
            diagnostics.lastRoundTripMs()
        );
    }

    // Perf backstop: the control loop and its world scans run inside the client tick on the render
    // thread, so a slow tick here IS a frame stall. Warn (throttled) whenever the bot's tick work
    // exceeds the budget, independent of brain in-flight state, so scan regressions like the 2026-06-08
    // gather-search one are visible in any run's log instead of needing a profiler.
    private static final long TICK_BUDGET_WARN_MS = 50L;
    private long nextTickBudgetWarnAtMs = 0L;

    private void logBrainTiming(long nowMs, long tickStartNs, BrainLink.Diagnostics diagnostics) {
        long budgetTickMs = Math.max(0L, (System.nanoTime() - tickStartNs) / 1_000_000L);
        if (budgetTickMs >= TICK_BUDGET_WARN_MS && nowMs >= nextTickBudgetWarnAtMs) {
            nextTickBudgetWarnAtMs = nowMs + 1_000L;
            LOGGER.warn(
                "mcbot.tick_budget_exceeded instanceId={} tickMs={} budgetMs={}",
                instanceId,
                budgetTickMs,
                TICK_BUDGET_WARN_MS
            );
        }
        if (!diagnostics.inFlight() || nowMs - lastBrainTimingLogMs < 1000L) {
            return;
        }
        lastBrainTimingLogMs = nowMs;
        long tickMs = Math.max(0L, (System.nanoTime() - tickStartNs) / 1_000_000L);
        LOGGER.info(
            "brain.tick_timing instanceId={} tickMs={} inFlight={} requestAgeMs={} dispatched={} completed={} currentIntentAgeMs={} remainingTtlMs={} lastBrainRoundTripMs={}",
            instanceId,
            tickMs,
            diagnostics.inFlight(),
            diagnostics.currentRequestAgeMs(),
            diagnostics.dispatchedRequestCount(),
            diagnostics.completedRequestCount(),
            diagnostics.currentIntentAgeMs(),
            diagnostics.currentIntentRemainingTtlMs(),
            diagnostics.lastRoundTripMs()
        );
    }

    private ControlDecision resolveControl(MinecraftClient client, ClientPlayerEntity player, BrainLink.Intent effective, long nowMs) {
        if (!isGatherTree(effective) && activeGatherTree != null) {
            clearGatherTreeExecutionState(activeGatherTree);
            activeGatherTree = null;
        }
        if (!isGatherTree(effective)) {
            clearGatherTreeInventoryRequirement();
        }
        if (!isMineNearbyStone(effective)) {
            missionStoneInventoryCompletion.clear();
            missionStoneFrontierCompletion.clear();
        }
        ControlDecision workspaceTransaction = resolveMiningWorkspaceTransaction(client, player, effective, nowMs);
        if (workspaceTransaction != null) {
            return workspaceTransaction;
        }
        observeMiningWorkspaceRecoveryBreadcrumb(client, player, effective);
        ControlDecision shaftResume = resolveMissionStoneShaftResume(
            client, player, effective, nowMs);
        if (shaftResume != null) {
            return shaftResume;
        }
        // Strangler dispatch: objectives lifted into the registry are consulted first. tickContext was
        // reset() earlier this tick (in onClientTick) before resolveControl ran. Unregistered actions
        // return null and fall through to the unchanged if/return chain below — identical behavior.
        ObjectiveExecutor ex = effective == null ? null : objectiveRegistry.forAction(effective.action());
        if (ex != null) {
            return ex.tick(tickContext);
        }
        if (isBreakBlock(effective)) {
            return resolveBreakBlockControl(client, player, effective, nowMs);
        }
        if (isGatherTree(effective)) {
            return resolveGatherTreeControl(client, player, effective, nowMs);
        }
        if (isMineNearbyStone(effective)) {
            return resolveMineNearbyStoneControl(client, player, effective, nowMs);
        }
        if (isMineNearbyIron(effective)) {
            return resolveMineNearbyIronControl(client, player, effective, nowMs);
        }
        if (isMineNearbyCoal(effective)) {
            return resolveMineNearbyOreControl(client, player, effective, nowMs, OreKind.COAL);
        }
        if (isMineNearbyDiamond(effective)) {
            return resolveMineNearbyDiamondControl(client, player, effective, nowMs);
        }
        if (isReturnStaircase(effective)) {
            return resolveReturnStaircaseControl(client, player, effective, nowMs);
        }
        if (isNav3dDriveTest(effective)) {
            return resolveNav3dDriveTestControl(client, player, effective, nowMs);
        }
        if (isR2MineStoneReturn(effective)) {
            return resolveR2MineStoneReturnControl(client, player, effective, nowMs);
        }
        if (isCraft3x3(effective)) {
            return resolveCraft3x3Control(client, player, effective, nowMs);
        }
        if (isEquipArmor(effective)) {
            return resolveEquipArmorControl(client, player, effective, nowMs);
        }
        if (isSmelt(effective)) {
            return resolveSmeltCharcoalControl(client, player, effective, nowMs);
        }
        if (isMakeCharcoal(effective)) {
            return resolveMakeCharcoalControl(client, player, effective, nowMs);
        }
        if (isR5IronChain(effective)) {
            return resolveR5IronChainControl(client, player, effective, nowMs);
        }
        if (isEat(effective)) {
            return resolveEatControl(player, effective);
        }
        if (isNavigationProbe(effective)) {
            return resolveNavigationProbeControl(client, player, effective);
        }
        if (hasNavigation(effective)) {
            return resolveNavigationControl(client, player, effective);
        }
        activeNavigationCommandId = "";
        activeNavigationWaypointIndex = 0;
        activeNavigationProgress = PathFollower.Progress.initial();
        return new ControlDecision(effective, BrainLink.inputStateFor(effective));
    }

