    @Override
    public void recordMiningWorkspace(MiningWorkspaceStore.Workspace workspace) {
        MinecraftClient client = MinecraftClient.getInstance();
        if (client == null || client.world == null) {
            miningWorkspaceStore.invalidate();
            return;
        }
        miningWorkspaceStore.observeContext(
            Integer.toString(System.identityHashCode(client.world)),
            client.world.getRegistryKey().getValue().toString()
        );
        miningWorkspaceStore.record(workspace);
    }

    @Override
    public boolean hasValidMiningWorkspace(MinecraftClient client) {
        if (client == null || client.world == null) {
            miningWorkspaceStore.invalidate();
            return false;
        }
        miningWorkspaceStore.observeContext(
            Integer.toString(System.identityHashCode(client.world)),
            client.world.getRegistryKey().getValue().toString()
        );
        return miningWorkspaceValid(client, miningWorkspaceStore.workspace());
    }

    @Override
    public boolean hasValidMiningWorkspaceAtDepth(
        MinecraftClient client,
        String commandId,
        Double targetY
    ) {
        if (client == null || client.world == null) {
            miningWorkspaceStore.invalidate();
            return false;
        }
        miningWorkspaceStore.observeContext(
            Integer.toString(System.identityHashCode(client.world)),
            client.world.getRegistryKey().getValue().toString()
        );
        MiningWorkspaceStore.Workspace workspace = miningWorkspaceStore.workspace();
        if (!miningWorkspaceValid(client, workspace)) {
            return false;
        }
        if (MiningWorkspaceDepthPolicy.workspaceStanceAllowed(workspace.stance(), targetY)) {
            return true;
        }
        LOGGER.warn(
            "mining.workspace.invalidated instanceId={} commandId={} workspaceId={} tablePlacement={} furnacePlacement={} targetY={} actualY={} atTargetDepth=false reason=outside_target_depth",
            instanceId,
            commandId == null ? "" : commandId,
            workspace.id(),
            workspace.tablePlacement(),
            workspace.furnacePlacement(),
            targetY,
            workspace.stance() == null ? null : workspace.stance().y()
        );
        miningWorkspaceStore.invalidate();
        if (activeMineNearbyIron != null) {
            clearMiningWorkspaceTravel(activeMineNearbyIron);
        }
        return false;
    }

