    @Override
    public VillageNestedCraftCleanupResult prepareVillageNestedCraftCleanup(
        MinecraftClient client,
        ClientPlayerEntity player,
        long nowMs
    ) {
        VillageNestedCraftCleanupResult tableCleanup =
            prepareCraft3x3AbortCleanup(client, player, nowMs);
        if (tableCleanup.status() != VillageNestedCraftCleanupResult.Status.CLEAN) {
            return tableCleanup;
        }
        VillageNestedCraftCleanupResult result =
            craft2x2Executor.prepareAbortCleanup(client, player, nowMs);
        if (result.status() != VillageNestedCraftCleanupResult.Status.CLEAN) {
            return result;
        }
        return VillageNestedCraftCleanupResult.clean();
    }

    private VillageNestedCraftCleanupResult prepareCraft3x3AbortCleanup(
        MinecraftClient client,
        ClientPlayerEntity player,
        long nowMs
    ) {
        Craft3x3Run run = activeCraft3x3;
        if (run == null) {
            return VillageNestedCraftCleanupResult.clean();
        }
        if (client == null || player == null || client.interactionManager == null
            || player.currentScreenHandler == null) {
            return new VillageNestedCraftCleanupResult(
                VillageNestedCraftCleanupResult.Status.REJECTED,
                player == null || player.currentScreenHandler == null
                    || player.currentScreenHandler.getCursorStack().isEmpty(),
                0,
                false,
                "craft3x3_screen_unavailable");
        }
        if (!(player.currentScreenHandler instanceof CraftingScreenHandler handler)) {
            // Either the table was never opened or vanilla has completed the requested close and
            // returned its grid. No 3x3 click is still in flight at this point.
            if (run.lastClickAtMs <= 0L
                || nowMs - run.lastClickAtMs >= CRAFT_CLICK_SETTLE_MS) {
                activeCraft3x3 = null;
                return VillageNestedCraftCleanupResult.clean();
            }
            return new VillageNestedCraftCleanupResult(
                VillageNestedCraftCleanupResult.Status.PENDING,
                player.currentScreenHandler.getCursorStack().isEmpty(),
                0,
                false,
                "craft3x3_click_settle");
        }
        if (run.abortScreenCloseRequested) {
            return new VillageNestedCraftCleanupResult(
                VillageNestedCraftCleanupResult.Status.PENDING,
                handler.getCursorStack().isEmpty(),
                occupiedCraft3x3Inputs(handler),
                false,
                "craft3x3_screen_close_settle");
        }
        if (run.lastClickAtMs > 0L
            && nowMs - run.lastClickAtMs < CRAFT_CLICK_SETTLE_MS) {
            return new VillageNestedCraftCleanupResult(
                VillageNestedCraftCleanupResult.Status.PENDING,
                handler.getCursorStack().isEmpty(),
                occupiedCraft3x3Inputs(handler),
                false,
                "craft3x3_click_settle");
        }
        ItemStack cursor = handler.getCursorStack();
        if (cursor != null && !cursor.isEmpty()) {
            int returnSlot = findCraft3x3CursorReturnScreenSlot(handler, cursor);
            if (returnSlot < 0) {
                return new VillageNestedCraftCleanupResult(
                    VillageNestedCraftCleanupResult.Status.REJECTED,
                    false,
                    occupiedCraft3x3Inputs(handler),
                    false,
                    "craft3x3_cursor_return_unavailable");
            }
            if (!clickCraft3x3Slot(
                client, player, handler, run, returnSlot, 0,
                SlotActionType.PICKUP, "handoff_return_cursor", nowMs)) {
                return new VillageNestedCraftCleanupResult(
                    VillageNestedCraftCleanupResult.Status.REJECTED,
                    false,
                    occupiedCraft3x3Inputs(handler),
                    false,
                    "craft3x3_slot_authorization_denied");
            }
            return new VillageNestedCraftCleanupResult(
                VillageNestedCraftCleanupResult.Status.PENDING,
                false,
                occupiedCraft3x3Inputs(handler),
                true,
                "craft3x3_cursor_returned");
        }
        int end = Math.min(TABLE_CRAFTING_INPUT_END, handler.slots.size());
        for (int slot = TABLE_CRAFTING_INPUT_START; slot < end; slot++) {
            ItemStack input = handler.getSlot(slot).getStack();
            if (input == null || input.isEmpty()) {
                continue;
            }
            if (!clickCraft3x3Slot(
                client, player, handler, run, slot, 0,
                SlotActionType.QUICK_MOVE, "handoff_return_input", nowMs)) {
                return new VillageNestedCraftCleanupResult(
                    VillageNestedCraftCleanupResult.Status.REJECTED,
                    true,
                    occupiedCraft3x3Inputs(handler),
                    false,
                    "craft3x3_slot_authorization_denied");
            }
            return new VillageNestedCraftCleanupResult(
                VillageNestedCraftCleanupResult.Status.PENDING,
                true,
                occupiedCraft3x3Inputs(handler),
                true,
                "craft3x3_input_returned");
        }
        player.closeHandledScreen();
        run.abortScreenCloseRequested = true;
        LOGGER.info(
            "village.opportunity.nested_craft3x3.cleanup_screen_closed instanceId={} commandId={} action={} cursorEmpty=true occupiedInputSlots=0",
            instanceId, run.commandId, run.recipe.action());
        return new VillageNestedCraftCleanupResult(
            VillageNestedCraftCleanupResult.Status.PENDING,
            true,
            0,
            false,
            "craft3x3_screen_close_requested");
    }

    private static int occupiedCraft3x3Inputs(ScreenHandler handler) {
        if (handler == null) {
            return 0;
        }
        int occupied = 0;
        int end = Math.min(TABLE_CRAFTING_INPUT_END, handler.slots.size());
        for (int slot = TABLE_CRAFTING_INPUT_START; slot < end; slot++) {
            ItemStack stack = handler.getSlot(slot).getStack();
            if (stack != null && !stack.isEmpty()) {
                occupied += 1;
            }
        }
        return occupied;
    }

    private static int findCraft3x3CursorReturnScreenSlot(
        ScreenHandler handler,
        ItemStack cursor
    ) {
        if (handler == null || cursor == null || cursor.isEmpty()) {
            return -1;
        }
        int empty = -1;
        for (int slot = TABLE_CRAFTING_INPUT_END; slot < handler.slots.size(); slot++) {
            ItemStack stack = handler.getSlot(slot).getStack();
            if (stack == null || stack.isEmpty()) {
                if (empty < 0) {
                    empty = slot;
                }
            } else if (ItemStack.areItemsAndComponentsEqual(stack, cursor)
                && stack.getCount() + cursor.getCount() <= stack.getMaxCount()) {
                return slot;
            }
        }
        return empty;
    }

