    @Override
    public int moveInventoryItemToHotbar(
        MinecraftClient client,
        ClientPlayerEntity player,
        Predicate<String> itemPredicate,
        String commandId,
        String logPrefix
    ) {
        if (client == null || client.interactionManager == null || player == null || itemPredicate == null) {
            return -1;
        }
        if (player.currentScreenHandler != null && player.currentScreenHandler != player.playerScreenHandler) {
            String previousHandler = player.currentScreenHandler.getClass().getSimpleName();
            player.closeHandledScreen();
            LOGGER.info(
                "{}.hotbar_move_close_screen instanceId={} commandId={} handler={}",
                logPrefix,
                instanceId,
                commandId,
                previousHandler
            );
            return -2;
        }
        int sourceInventorySlot = findInventorySlot(player, itemPredicate, false);
        if (sourceInventorySlot < 0) {
            return -1;
        }
        int hotbarSlot = firstEmptyHotbarSlot(player);
        if (hotbarSlot < 0) {
            hotbarSlot = Math.max(0, Math.min(8, player.getInventory().selectedSlot));
        }
        int sourceScreenSlot = playerInventoryScreenSlot(sourceInventorySlot);
        if (!clickAuthorizedPlayerInventorySlot(
            client, player, player.playerScreenHandler,
            sourceScreenSlot, hotbarSlot, SlotActionType.SWAP)) {
            return -1;
        }
        LOGGER.info(
            "{}.hotbar_move instanceId={} commandId={} sourceInventorySlot={} sourceScreenSlot={} hotbarSlot={}",
            logPrefix,
            instanceId,
            commandId,
            sourceInventorySlot,
            sourceScreenSlot,
            hotbarSlot
        );
        return hotbarSlot;
    }

    @Override
    public int moveInventoryItemToHotbarSlot(
        MinecraftClient client,
        ClientPlayerEntity player,
        Predicate<String> itemPredicate,
        int hotbarSlot,
        String commandId,
        String logPrefix
    ) {
        if (client == null || client.interactionManager == null || player == null
            || itemPredicate == null || hotbarSlot < 0 || hotbarSlot > 8) {
            return -1;
        }
        if (player.currentScreenHandler != null
            && player.currentScreenHandler != player.playerScreenHandler) {
            String previousHandler = player.currentScreenHandler.getClass().getSimpleName();
            player.closeHandledScreen();
            LOGGER.info(
                "{}.hotbar_move_exact_close_screen instanceId={} commandId={} handler={} hotbarSlot={}",
                logPrefix, instanceId, commandId, previousHandler, hotbarSlot);
            return -2;
        }
        int sourceInventorySlot = findInventorySlot(player, itemPredicate, false);
        if (sourceInventorySlot < 0) {
            return -1;
        }
        ItemStack displaced = player.getInventory().getStack(hotbarSlot);
        String displacedItemId = displaced == null || displaced.isEmpty() ? "empty" : itemId(displaced);
        int displacedCount = displaced == null || displaced.isEmpty() ? 0 : displaced.getCount();
        int sourceScreenSlot = playerInventoryScreenSlot(sourceInventorySlot);
        if (!clickAuthorizedPlayerInventorySlot(
            client,
            player,
            player.playerScreenHandler,
            sourceScreenSlot,
            hotbarSlot,
            SlotActionType.SWAP)) {
            return -1;
        }
        LOGGER.info(
            "{}.hotbar_move_exact instanceId={} commandId={} sourceInventorySlot={} sourceScreenSlot={} hotbarSlot={} displacedItemId={} displacedCount={}",
            logPrefix, instanceId, commandId, sourceInventorySlot, sourceScreenSlot,
            hotbarSlot, displacedItemId, displacedCount);
        return hotbarSlot;
    }

    @Override
    public int moveExactInventorySlotToHotbar(
        MinecraftClient client,
        ClientPlayerEntity player,
        int sourceInventorySlot,
        String commandId,
        String logPrefix
    ) {
        if (client == null
            || client.interactionManager == null
            || player == null
            || sourceInventorySlot < 9
            || sourceInventorySlot >= Math.min(36, player.getInventory().size())) {
            return -1;
        }
        if (player.currentScreenHandler != null
            && player.currentScreenHandler != player.playerScreenHandler) {
            String previousHandler = player.currentScreenHandler.getClass().getSimpleName();
            player.closeHandledScreen();
            LOGGER.info(
                "{}.hotbar_move_exact_source_close_screen instanceId={} commandId={} handler={} sourceInventorySlot={}",
                logPrefix,
                instanceId,
                commandId,
                previousHandler,
                sourceInventorySlot
            );
            return -2;
        }
        ItemStack source = player.getInventory().getStack(sourceInventorySlot);
        if (source == null || source.isEmpty()) {
            return -1;
        }
        int hotbarSlot = firstEmptyHotbarSlot(player);
        if (hotbarSlot < 0) {
            hotbarSlot = Math.max(0, Math.min(8, player.getInventory().selectedSlot));
        }
        ItemStack displaced = player.getInventory().getStack(hotbarSlot);
        String displacedItemId = displaced == null || displaced.isEmpty() ? "empty" : itemId(displaced);
        int sourceScreenSlot = playerInventoryScreenSlot(sourceInventorySlot);
        if (!clickAuthorizedPlayerInventorySlot(
            client,
            player,
            player.playerScreenHandler,
            sourceScreenSlot,
            hotbarSlot,
            SlotActionType.SWAP
        )) {
            return -1;
        }
        LOGGER.info(
            "{}.hotbar_move_exact_source instanceId={} commandId={} sourceInventorySlot={} sourceScreenSlot={} hotbarSlot={} sourceItemId={} sourceDurability={} displacedItemId={}",
            logPrefix,
            instanceId,
            commandId,
            sourceInventorySlot,
            sourceScreenSlot,
            hotbarSlot,
            itemId(source),
            remainingDurability(source),
            displacedItemId
        );
        return hotbarSlot;
    }

