    private int findInventorySlot(ClientPlayerEntity player, Predicate<String> itemPredicate, boolean includeHotbar) {
        if (player == null || itemPredicate == null) {
            return -1;
        }
        int start = includeHotbar ? 0 : 9;
        int end = Math.min(36, player.getInventory().size());
        for (int slot = start; slot < end; slot++) {
            ItemStack stack = player.getInventory().getStack(slot);
            if (stack == null || stack.isEmpty()) {
                continue;
            }
            if (itemPredicate.test(itemId(stack))) {
                return slot;
            }
        }
        return -1;
    }

    private int firstEmptyHotbarSlot(ClientPlayerEntity player) {
        if (player == null) {
            return -1;
        }
        for (int slot = 0; slot < 9; slot++) {
            ItemStack stack = player.getInventory().getStack(slot);
            if (stack == null || stack.isEmpty()) {
                return slot;
            }
        }
        return -1;
    }

    private static int playerInventoryScreenSlot(int inventorySlot) {
        if (inventorySlot >= 0 && inventorySlot < 9) {
            return 36 + inventorySlot;
        }
        return inventorySlot;
    }

    private void enforceGatherTreeCommandDeadlineBeforeReflex(
        MinecraftClient client,
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        long nowMs
    ) {
        String incomingCommandId = effective == null ? "" : effective.commandId();
        if (!isGatherTree(effective)) {
            if (activeGatherTree != null) {
                clearGatherTreeExecutionState(activeGatherTree);
                activeGatherTree = null;
            }
            clearGatherTreeInventoryRequirement();
            return;
        }
        GatherTreeRun run = activeGatherTree;
        if (run != null
            && (run.world != client.world
                || GatherTreeLivenessPolicy.commandChanged(run.commandId, incomingCommandId))) {
            clearGatherTreeExecutionState(run);
            activeGatherTree = null;
            run = null;
        }
        if (completedGatherTreeCommandIds.contains(incomingCommandId)) {
            return;
        }
        GatherTreeInventoryRequirementLatch.Requirement inventoryRequirement =
            gatherTreeInventoryRequirement(client.world, effective);
        if (maybeCompleteGatherTreeInventoryRequirement(
                client,
                player,
                effective,
                inventoryRequirement,
                "pre_reflex",
                nowMs
            ) != null) {
            return;
        }
        run = activeGatherTree;
        if (run == null) {
            return;
        }
        if (!GatherTreeLivenessPolicy.shouldEnforceCommandDeadline(
                isGatherTree(effective),
                true,
                run.commandId,
                incomingCommandId,
                run.commandDeadline,
                nowMs
            )) {
            return;
        }
        updateGatherTreeBreakStanceEpisodeMetrics(run, nowMs);
        InventoryCounter.InventoryLogSnapshot inventory = InventoryCounter.countPlayerLogs(player);
        reconcileGatherTreeInventoryGain(player, run, inventory, nowMs);
        expireGatherTreeCommand(client, player, inventory, effective, run, nowMs);
    }

    /**
     * Mission stone uses an absolute inventory postcondition, so pickup on a combat/survival tick
     * must terminate the command before either reflex can hide the ordinary executor. Historical
     * fixed-delta stone commands omit the field and remain disabled here.
     */
    private void enforceMineNearbyStoneCompletionBeforeReflex(
        MinecraftClient client,
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        long nowMs
    ) {
        if (!isMineNearbyStone(effective) || client == null || client.world == null || player == null) {
            missionStoneInventoryCompletion.clear();
            missionStoneFrontierCompletion.clear();
            return;
        }
        String commandId = effective.commandId() == null ? "" : effective.commandId();
        if (finishedMineNearbyStoneCommandReasons.containsKey(commandId)) {
            missionStoneFrontierCompletion.clear();
            return;
        }
        MissionStoneInventoryCompletionPolicy.Requirement requirement =
            missionStoneInventoryCompletion.freeze(
                client.world,
                commandId,
                isMissionCommandId(commandId)
                    ? effective.completionInventoryCobblestoneCount()
                    : null
            );
        InventoryCounter.InventoryCobblestoneSnapshot inventory =
            InventoryCounter.countPlayerCobblestone(player);
        boolean inventorySatisfied = MissionStoneInventoryCompletionPolicy.isSatisfied(
            requirement, inventory.cobblestoneCount());
        if (!inventorySatisfied) {
            missionStoneFrontierCompletion.observe(
                client.world,
                commandId,
                false,
                false,
                false
            );
            return;
        }

        MineNearbyStoneRun run = activeMineNearbyStone != null
            && commandId.equals(activeMineNearbyStone.commandId)
                ? activeMineNearbyStone
                : null;
        // An external pickup can satisfy the absolute target during a committed drop. Once the
        // player has departed, landing safety remains authoritative; finish that one-block motion
        // before terminal cleanup can remove its forward/landing controller.
        if (missionStoneCommittedMovementActive(run)) {
            return;
        }
        if (run != null) {
            reconcileMissionStoneAirConfirmationBeforeCompletion(
                client, player, run, inventory.cobblestoneCount(), nowMs);
            reconcileMissionStoneDropInventory(client, run, inventory.cobblestoneCount(), nowMs);
            reconcileMineNearbyStoneOwnedDropInventory(run, player, inventory, nowMs);
        }
        MissionStoneFrontierCompletionState.Evaluation frontierCompletion =
            missionStoneFrontierCompletion.observe(
                client.world,
                commandId,
                true,
                run != null && missionStoneShaftActiveForCurrentSession(),
                atVerifiedMissionStoneShaftFrontier(player)
            );
        long startedAtMs = run == null ? nowMs : run.startedAtMs;
        if (run == null || !run.inventoryRequirementSatisfiedEmitted) {
            LOGGER.info(
                "mine_nearby_stone.inventory_requirement_satisfied instanceId={} commandId={} stage=pre_reflex requiredCobblestone={} observedCobblestone={} baselineCobblestone={} method={} elapsedMs={} reason=inventory_requirement_satisfied",
                instanceId,
                commandId,
                requirement.requiredCobblestone(),
                inventory.cobblestoneCount(),
                run == null ? inventory.cobblestoneCount() : run.baselineCobblestone,
                run == null ? "none" : run.methodLogName(),
                Math.max(0L, nowMs - startedAtMs)
            );
            if (run != null) {
                run.inventoryRequirementSatisfiedEmitted = true;
            }
        }
        if (frontierCompletion.decision()
            == MissionStoneFrontierCompletionState.Decision.RETURN_TO_FRONTIER) {
            // Inventory is already authoritative. Withhold only the command-completion receipt;
            // resolveMissionStoneShaftResume owns every subsequent normal-control tick, so no new
            // stone plan, target, or break can be selected while the canonical return finishes.
            if (run != null && run.missionStonePlan != null) {
                emitMissionStonePlanComplete(
                    run,
                    inventory.cobblestoneCount(),
                    nowMs,
                    "inventory_requirement_satisfied"
                );
            }
            return;
        }
        if (run != null) {
            if (run.missionStonePlan != null) {
                emitMissionStonePlanComplete(
                    run,
                    inventory.cobblestoneCount(),
                    nowMs,
                    "inventory_requirement_satisfied"
                );
            }
            completeMineNearbyStone(
                effective,
                run,
                inventory,
                nowMs,
                "inventory_requirement_satisfied"
            );
            return;
        }

        String completionReason = "mine_nearby_stone_complete:inventory_requirement_satisfied";
        finishedMineNearbyStoneCommandReasons.put(commandId, completionReason);
        blockBreakController.reset();
        clearNavigationState();
        LOGGER.info(
            "mine_nearby_stone.complete instanceId={} commandId={} reason=inventory_requirement_satisfied inventoryCobblestoneBefore={} inventoryCobblestoneAfter={} targetDelta=0 completionInventoryCobblestoneCount={} inventoryRequirementSatisfied=1 method=none ownedDropsLatched=0 ownedDropsSettled=0 ownedDropNav3dSelected=0 ownedDropNav3dReached=0 ownedDropsRecovered=0 ownedDropsRejected=0 collectTimeouts=0 directStalls=0 elapsedMs=0 cobblestoneByItem={}",
            instanceId,
            commandId,
            inventory.cobblestoneCount(),
            inventory.cobblestoneCount(),
            requirement.requiredCobblestone(),
            inventory.cobblestoneByItem()
        );
        brainLink.completeCurrentCommand(commandId, completionReason, nowMs);
    }

    private void reconcileMissionStoneAirConfirmationBeforeCompletion(
        MinecraftClient client,
        ClientPlayerEntity player,
        MineNearbyStoneRun run,
        int authoritativeCobblestone,
        long nowMs
    ) {
        if (run == null
            || !run.missionStoneExecution.active()
            || run.missionStoneEngagedBreakTarget == null) {
            return;
        }
        MissionStoneExecutionController.Decision current = run.missionStoneExecution.tick(
            missionStoneObservation(client, player, run, authoritativeCobblestone),
            missionStoneGeometry(client, player),
            null,
            nowMs
        );
        BlockPos target = current.breakTarget();
        if (current.action() != MissionStoneExecutionController.Action.BREAK_BLOCK
            || target == null
            || !target.equals(run.missionStoneEngagedBreakTarget)
            || !client.world.getBlockState(target).isAir()) {
            return;
        }
        MissionStoneExecutionController.Decision terminal = run.missionStoneExecution.tick(
            missionStoneObservation(client, player, run, authoritativeCobblestone),
            missionStoneGeometry(client, player),
            new MissionStoneExecutionController.BreakFeedback(
                target,
                BlockBreakController.Status.BROKEN,
                "inventory_boundary_air_verified"
            ),
            nowMs
        );
        run.missionStoneEngagedBreakTarget = null;
        if (terminal.stoneProducedThisTick()) {
            recordMissionStoneProduction(client, run, target, terminal, nowMs);
        }
        if (terminal.action() == MissionStoneExecutionController.Action.COMPLETE
            || terminal.action() == MissionStoneExecutionController.Action.PLAN_EXHAUSTED) {
            emitMissionStonePlanComplete(
                run,
                authoritativeCobblestone,
                nowMs,
                "inventory_boundary_air_verified"
            );
        }
    }

    private GatherTreeInventoryRequirementLatch.Requirement gatherTreeInventoryRequirement(
        ClientWorld world,
        BrainLink.Intent effective
    ) {
        String commandId = effective == null || effective.commandId() == null
            ? ""
            : effective.commandId();
        return gatherTreeRequirementLatch.freeze(
            world,
            commandId,
            effective == null ? null : effective.completionInventoryLogCount(),
            effective == null ? null : effective.completionInventoryPlankCount()
        );
    }

    private void clearGatherTreeInventoryRequirement() {
        gatherTreeRequirementLatch.clear();
    }

    private ControlDecision maybeCompleteGatherTreeInventoryRequirement(
        MinecraftClient client,
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        GatherTreeInventoryRequirementLatch.Requirement requirement,
        String stageOverride,
        long nowMs
    ) {
        if (client == null
            || client.world == null
            || player == null
            || effective == null
            || requirement == null
            || !requirement.enabled()) {
            return null;
        }
        String commandId = effective.commandId() == null ? "" : effective.commandId();
        GatherTreeRun run = activeGatherTree != null
            && activeGatherTree.world == client.world
            && commandId.equals(activeGatherTree.commandId)
            ? activeGatherTree
            : null;
        GatherTreeSearchRun search = activeGatherTreeSearch != null
            && commandId.equals(activeGatherTreeSearch.commandId)
            ? activeGatherTreeSearch
            : null;
        InventoryCounter.InventoryLogSnapshot logs = InventoryCounter.countPlayerLogs(player);
        InventoryCounter.InventoryPlankSnapshot planks = InventoryCounter.countPlayerPlanks(player);
        BlockPos targetBeforeReconciliation = run == null ? null : run.currentTarget;
        if (run != null) {
            reconcileGatherTreeInventoryGain(player, run, logs, nowMs);
        }
        if (!GatherTreeInventoryCompletionPolicy.isSatisfied(
                requirement.requiredLogs(),
                requirement.requiredPlanks(),
                logs.logCount(),
                planks.plankCount()
            )) {
            return null;
        }
        String stage = stageOverride == null || stageOverride.isBlank()
            ? run != null ? "harvest" : search != null ? "search" : "pre_seed"
            : stageOverride;
        int baselineLogs = run != null
            ? run.baselineLogCount
            : search != null && search.inventoryLogsBefore >= 0
                ? search.inventoryLogsBefore
                : logs.logCount();
        long startedAtMs = run != null
            ? run.startedAtMs
            : search != null ? search.startedAtMs : nowMs;
        int selectionEpisode = run == null ? 0 : run.selectionEpisode;
        LOGGER.info(
            "gather_tree.inventory_requirement_satisfied instanceId={} commandId={} stage={} requiredLogs={} requiredPlanks={} inventoryLogs={} inventoryPlanks={} baselineLogs={} target={} elapsedMs={} selectionEpisode={} reason=inventory_requirement_satisfied",
            instanceId,
            commandId,
            stage,
            requirement.requiredLogs(),
            requirement.requiredPlanks(),
            logs.logCount(),
            planks.plankCount(),
            baselineLogs,
            targetBeforeReconciliation == null ? "" : targetBeforeReconciliation.toShortString(),
            Math.max(0L, nowMs - startedAtMs),
            selectionEpisode
        );
        if (run != null) {
            run.inventoryRequirementSatisfiedCount++;
            run.inventoryRequirementCompletionStage = stage;
            run.inventoryRequirementObservedLogs = logs.logCount();
            run.inventoryRequirementObservedPlanks = planks.plankCount();
            return completeGatherTree(
                client,
                logs,
                effective,
                run,
                nowMs,
                "inventory_requirement_satisfied"
            );
        }
        return completeGatherTreeBeforeSeed(
            effective,
            search,
            requirement,
            logs,
            planks,
            stage,
            nowMs
        );
    }

    private ControlDecision completeGatherTreeBeforeSeed(
        BrainLink.Intent effective,
        GatherTreeSearchRun search,
        GatherTreeInventoryRequirementLatch.Requirement requirement,
        InventoryCounter.InventoryLogSnapshot logs,
        InventoryCounter.InventoryPlankSnapshot planks,
        String stage,
        long nowMs
    ) {
        String commandId = effective == null || effective.commandId() == null
            ? ""
            : effective.commandId();
        int baselineLogs = search != null && search.inventoryLogsBefore >= 0
            ? search.inventoryLogsBefore
            : logs.logCount();
        long startedAtMs = search == null ? nowMs : search.startedAtMs;
        String completionReason = "gather_tree_complete:inventory_requirement_satisfied";
        completedGatherTreeCommandIds.add(commandId);
        finishedGatherTreeCommandReasons.put(commandId, completionReason);
        activeGatherTreeSearch = null;
        gatherWoodLocalEgress.clearActive();
        gatherWoodLocalEgress.canonicalOverride = null;
        clearNavigationState();
        LOGGER.info(
            "gather_tree.complete instanceId={} commandId={} seed={} reason=inventory_requirement_satisfied inventoryLogsBefore={} inventoryLogsAfter={} inventoryPlanksAfter={} logsGathered={} brokenLogs=0 leftUnreached=0 abandoned=0 reachableSeedFrontierSelected=0 reachableSeedFrontierProgress=0 reachableSeedFrontierReached=0 reachableSeedFrontierTargetReplanned=0 reachableSeedFrontierRejected=0 reachableSeedFrontierRejectionReasons=none reachableSeedFrontierMaximumRouteLength=0 reachableSeedFrontierMaximumExpandedCells=0 reachableSeedFrontierMaximumProgress=0.0 reachableSeedFrontierCursorRegression=0 reachableSeedFrontierDuplicateStageAttempts=0 reachableSeedFrontierPostStage2d=0 reachableSeedFrontierPostStage3d=0 reachableSeedFrontierTotalComputations=0 completionInventoryLogCount={} completionInventoryPlankCount={} inventoryRequirementSatisfied=1 inventoryRequirementSatisfactionCount=1 inventoryRequirementCompletionStage={} postSatisfactionTargetSelections=0 elapsedMs={} logsByItem={}",
            instanceId,
            commandId,
            "",
            baselineLogs,
            logs.logCount(),
            planks.plankCount(),
            Math.max(0, logs.logCount() - baselineLogs),
            requirement.requiredLogs(),
            requirement.requiredPlanks(),
            stage,
            Math.max(0L, nowMs - startedAtMs),
            logs.logsByItem()
        );
        return new ControlDecision(stopFrom(effective, completionReason), InputState.stop());
    }

    private void reconcileGatherTreeInventoryGain(
        ClientPlayerEntity player,
        GatherTreeRun run,
        InventoryCounter.InventoryLogSnapshot inventory,
        long nowMs
    ) {
        if (run == null
            || run.currentTarget == null
            || inventory.logCount() <= run.lastVerifiedLogCount) {
            return;
        }
        BlockPos collectedTarget = run.currentTarget;
        if (run.dropTracker.entityId() != null) {
            GatherTreeDropTracker.Position initial = run.dropTracker.initialPosition();
            GatherTreeDropTracker.Position settled = run.dropTracker.settledPosition();
            VoxelCell playerFeet = gatherTreePlayerFeet(player);
            if (GatherTreeOwnedDropTraversal.inventoryGainProvesSelectedRouteReached(
                run.ownedDropNav3dSelectedCount,
                run.ownedDropNav3dReachedCount,
                inventory.logCount(),
                run.lastVerifiedLogCount
            )) {
                markGatherTreeOwnedDropReached(run, collectedTarget, playerFeet, nowMs, "inventory_confirmed");
            }
            run.ownedDropRecoveredCount++;
            LOGGER.info(
                "gather_tree.collect_owned_drop_recovered instanceId={} commandId={} target={} entityId={} initialPosition={} settledPosition={} fallDepth={} pickupCell={} routeLength={} routeAttempts={} elapsedMs={}",
                instanceId,
                run.commandId,
                collectedTarget.toShortString(),
                run.dropTracker.entityId(),
                formatDropPosition(initial),
                formatDropPosition(settled),
                roundForLog(dropFallDepth(initial, settled)),
                run.ownedDropPickupCell,
                run.ownedDropRoute.size(),
                run.dropTracker.routeAttempts(),
                Math.max(0L, nowMs - run.collectStartedAtMs)
            );
        }
        run.completedTargets.add(collectedTarget);
        int delta = inventory.logCount() - run.lastVerifiedLogCount;
        run.lastVerifiedLogCount = inventory.logCount();
        LOGGER.info(
            "gather_tree.log_collected instanceId={} commandId={} target={} delta={} inventoryLogsAfter={} logsByItem={}",
            instanceId,
            run.commandId,
            collectedTarget.toShortString(),
            delta,
            inventory.logCount(),
            inventory.logsByItem()
        );
        run.abandonedDropColumns.clear();
        resetGatherTreeCurrentTarget(run);
    }

    private static void updateGatherTreeBreakStanceEpisodeMetrics(GatherTreeRun run, long nowMs) {
        if (run == null || run.breakStanceEpisode == null) {
            return;
        }
        run.breakStanceNav3dMaximumElapsedMs = Math.max(
            run.breakStanceNav3dMaximumElapsedMs,
            run.breakStanceEpisode.elapsedMs(nowMs)
        );
    }

    private ControlDecision expireGatherTreeCommand(
        MinecraftClient client,
        ClientPlayerEntity player,
        InventoryCounter.InventoryLogSnapshot inventory,
        BrainLink.Intent effective,
        GatherTreeRun run,
        long nowMs
    ) {
        run.executorDeadlineCount++;
        long elapsedMs = run.commandDeadline.elapsedMs(nowMs);
        LOGGER.warn(
            "gather_tree.executor_deadline instanceId={} commandId={} target={} stableFeet={} elapsedMs={} remainingDeadlineMs={} inventoryLogsBefore={} inventoryLogsAfter={} logsGathered={} reason=executor_deadline",
            instanceId,
            run.commandId,
            run.currentTarget == null ? "" : run.currentTarget.toShortString(),
            gatherTreePlayerFeet(player),
            elapsedMs,
            run.commandDeadline.remainingMs(nowMs),
            run.baselineLogCount,
            inventory.logCount(),
            Math.max(0, inventory.logCount() - run.baselineLogCount)
        );
        clearGatherTreeExecutionState(run);
        return completeGatherTree(client, inventory, effective, run, nowMs, "executor_deadline");
    }

    private ControlDecision expireGatherTreeBreakStanceTarget(
        BrainLink.Intent effective,
        GatherTreeRun run,
        long nowMs
    ) {
        GatherTreeLivenessPolicy.BreakStanceEpisode episode = run.breakStanceEpisode;
        long elapsedMs = episode == null ? 0L : episode.elapsedMs(nowMs);
        run.breakStanceNav3dDeadlineCount++;
        run.breakStanceNav3dMaximumElapsedMs = Math.max(
            run.breakStanceNav3dMaximumElapsedMs,
            elapsedMs
        );
        GatherTreeBreakStanceTraversalController traversal = run.breakStanceTraversal;
        boolean traversalActive = traversal.active();
        VoxelCell waypoint = traversalActive ? traversal.activeWaypoint() : run.breakStanceLastWaypoint;
        int waypointIndex = traversalActive ? traversal.waypointIndex() : run.breakStanceLastWaypointIndex;
        int remainingCells = traversalActive ? traversal.remainingCells() : run.breakStanceLastRemainingCells;
        VoxelCell stableFeet = traversalActive ? traversal.stableFeet() : run.breakStanceLastStableFeet;
        int maximumWaypointIndex = traversalActive
            ? traversal.maximumWaypointIndex()
            : run.breakStanceLastMaximumWaypointIndex;
        long progressAgeMs = traversalActive
            ? traversal.lastProgressAgeMs(nowMs)
            : Math.max(0L, nowMs - run.breakStanceLastProgressAtMs);
        String descentPhase = traversalActive
            ? traversal.descentPhase().name().toLowerCase(Locale.ROOT)
            : run.breakStanceLastDescentPhase;
        LOGGER.warn(
            "gather_tree.break_stance_nav3d_deadline instanceId={} commandId={} selectionEpisode={} target={} routeAttempt={} waypoint={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason=break_stance_deadline",
            instanceId,
            run.commandId,
            run.selectionEpisode,
            run.currentTarget == null ? "" : run.currentTarget.toShortString(),
            run.breakStanceRouteAttempts,
            waypoint,
            waypointIndex,
            remainingCells,
            stableFeet,
            maximumWaypointIndex,
            progressAgeMs,
            descentPhase,
            elapsedMs,
            episode == null ? 0L : episode.remainingMs(nowMs)
        );
        String trigger = run.breakStanceTrigger.isEmpty()
            ? run.breakStanceLastTrigger
            : run.breakStanceTrigger;
        return rejectGatherTreeBreakStance(
            effective,
            run,
            trigger,
            "break_stance_deadline",
            nowMs
        );
    }

    private ControlDecision completeGatherTree(
        MinecraftClient client,
        InventoryCounter.InventoryLogSnapshot inventory,
        BrainLink.Intent effective,
        GatherTreeRun run,
        long nowMs,
        String reason
    ) {
        // B2 pillar-up: before concluding "nothing reachable" with cluster logs still overhead
        // (observed tall-canopy class), try a bounded pillar to bring the lowest one into
        // the overhead-harvest envelope. Returns null when there is nothing pillarable / budget
        // spent, and the normal conclusion proceeds.
        if ("no_reachable_tree_logs".equals(reason)) {
            ControlDecision pillar = maybeResolveGatherPillarUp(client, effective, run, nowMs);
            if (pillar != null) {
                return pillar;
            }
        }
        Set<BlockPos> liveCluster = liveTreeCluster(client.world, run.cluster);
        int inventoryDelta = Math.max(0, inventory.logCount() - run.baselineLogCount);
        int leftUnreached = liveCluster.size();
        boolean inventoryRequirementSatisfied = "inventory_requirement_satisfied".equals(reason);
        int inventoryPlanks = InventoryCounter.countPlayerPlanks(client.player).plankCount();
        String completionReason = "gather_tree_complete:" + reason;
        if (!inventoryRequirementSatisfied && inventoryDelta == 0 && leftUnreached > 0) {
            completionReason = "gather_tree_failed:" + reason + ":left_unreached=" + leftUnreached;
        }
        if (!inventoryRequirementSatisfied) {
            rememberUnusableGatherTreeCluster(run, liveCluster, reason, inventoryDelta, leftUnreached);
        }
        completedGatherTreeCommandIds.add(run.commandId);
        finishedGatherTreeCommandReasons.put(run.commandId, completionReason);
        LOGGER.info(
            "gather_tree.complete instanceId={} commandId={} seed={} reason={} inventoryLogsBefore={} inventoryLogsAfter={} inventoryPlanksAfter={} logsGathered={} brokenLogs={} leftUnreached={} abandoned={} collectTimeouts={} ownedDropsLatched={} ownedDropsSettled={} ownedDropNav3dSelected={} ownedDropNav3dReached={} ownedDropsRecovered={} ownedDropsRejected={} reachableSeedNav3dSelected={} reachableSeedNav3dRejected={} reachableSeedInitialSelected={} reachableSeedClusterSelected={} reachableSeedInitialRejected={} reachableSeedClusterRejected={} reachableSeedMaximumRouteLength={} reachableSeedMaximumExpandedCells={} reachableSeedFrontierSelected={} reachableSeedFrontierProgress={} reachableSeedFrontierReached={} reachableSeedFrontierTargetReplanned={} reachableSeedFrontierRejected={} reachableSeedFrontierRejectionReasons={} reachableSeedFrontierMaximumRouteLength={} reachableSeedFrontierMaximumExpandedCells={} reachableSeedFrontierMaximumProgress={} reachableSeedFrontierCursorRegression={} reachableSeedFrontierDuplicateStageAttempts={} reachableSeedFrontierPostStage2d={} reachableSeedFrontierPostStage3d={} reachableSeedFrontierTotalComputations={} searchEdgeRouteRejected={} searchEdgeRouteRejectionReasons={} searchRepeatedRejectedRouteSignatures={} breakStanceNav3dSelected={} breakStanceNav3dReached={} breakStanceNav3dRejected={} breakStanceNav3dProgress={} breakStanceNav3dResync={} breakStanceNav3dReplanned={} breakStanceNav3dRouteStalls={} breakStanceNav3dDescentStarted={} breakStanceNav3dDescentLanded={} breakStanceNav3dDeadlines={} executorDeadlines={} completionInventoryLogCount={} completionInventoryPlankCount={} inventoryRequirementSatisfied={} inventoryRequirementSatisfactionCount={} inventoryRequirementCompletionStage={} postSatisfactionTargetSelections=0 breakStanceNav3dMaximumWaypointIndex={} breakStanceNav3dMaximumElapsedMs={} healthBefore={} minimumHealth={} healthAfter={} occludersBroken={} occlusionRepositions={} occlusionAbandons={} elapsedMs={} logsByItem={}",
            instanceId,
            run.commandId,
            run.seed.toShortString(),
            reason,
            run.baselineLogCount,
            inventory.logCount(),
            inventoryPlanks,
            inventoryDelta,
            run.completedTargets.size(),
            leftUnreached,
            run.abandonedTargets.size(),
            run.collectTimeouts,
            run.ownedDropLatchedCount,
            run.ownedDropSettledCount,
            run.ownedDropNav3dSelectedCount,
            run.ownedDropNav3dReachedCount,
            run.ownedDropRecoveredCount,
            run.ownedDropRejectedCount,
            run.reachableSeedNav3dSelectedCount,
            run.reachableSeedNav3dRejectedCount,
            run.reachableSeedInitialSelectedCount,
            run.reachableSeedClusterSelectedCount,
            run.reachableSeedInitialRejectedCount,
            run.reachableSeedClusterRejectedCount,
            run.reachableSeedMaximumRouteLength,
            run.reachableSeedMaximumExpandedCells,
            run.reachableSeedFrontierSelectedCount,
            run.reachableSeedFrontierProgressCount,
            run.reachableSeedFrontierReachedCount,
            run.reachableSeedFrontierTargetReplannedCount,
            run.reachableSeedFrontierRejectedCount,
            run.reachableSeedFrontierRejectionReasons,
            run.reachableSeedFrontierMaximumRouteLength,
            run.reachableSeedFrontierMaximumExpandedCells,
            roundForLog(run.reachableSeedFrontierMaximumProgress),
            run.reachableSeedFrontierCursorRegressionCount,
            run.reachableSeedFrontierDuplicateStageAttempts,
            run.reachableSeedFrontierPostStage2dCount,
            run.reachableSeedFrontierPostStage3dCount,
            run.reachableSeedFrontierSession.plannerComputations(),
            run.searchEdgeRouteRejectedCount,
            run.searchEdgeRouteRejectionReasons,
            run.searchRepeatedRejectedRouteSignatureCount,
            run.breakStanceNav3dSelectedCount,
            run.breakStanceNav3dReachedCount,
            run.breakStanceNav3dRejectedCount,
            run.breakStanceNav3dProgressCount,
            run.breakStanceNav3dResyncCount,
            run.breakStanceNav3dReplannedCount,
            run.breakStanceNav3dRouteStallCount,
            run.breakStanceNav3dDescentStartedCount,
            run.breakStanceNav3dDescentLandedCount,
            run.breakStanceNav3dDeadlineCount,
            run.executorDeadlineCount,
            run.completionInventoryLogCount,
            run.completionInventoryPlankCount,
            inventoryRequirementSatisfied ? 1 : 0,
            run.inventoryRequirementSatisfiedCount,
            run.inventoryRequirementCompletionStage,
            run.breakStanceNav3dMaximumWaypointIndex,
            run.breakStanceNav3dMaximumElapsedMs,
            roundForLog(run.baselineHealth),
            roundForLog(run.minimumHealth),
            roundForLog(client.player == null ? run.minimumHealth : client.player.getHealth()),
            run.occludersBroken,
            run.occlusionRepositions,
            run.occlusionAbandons,
            Math.max(0L, nowMs - run.startedAtMs),
            inventory.logsByItem()
        );
        clearGatherTreeExecutionState(run);
        activeGatherTree = null;
        return new ControlDecision(stopFrom(effective, completionReason), InputState.stop());
    }

    private void rememberUnusableGatherTreeCluster(
        GatherTreeRun run,
        Set<BlockPos> liveCluster,
        String reason,
        int inventoryDelta,
        int leftUnreached
    ) {
        if (run == null
            || liveCluster == null
            || leftUnreached <= 0
            || !shouldIgnoreUnusableGatherTreeCluster(run.cluster, reason)) {
            return;
        }
        int before = ignoredGatherTreeColumns.size();
        for (BlockPos log : run.cluster) {
            if (log != null) {
                ignoredGatherTreeColumns.add(new GridCell(log.getX(), log.getZ()));
            }
        }
        int added = ignoredGatherTreeColumns.size() - before;
        if (added > 0) {
            LOGGER.warn(
                "gather_tree.cluster_ignored instanceId={} commandId={} seed={} reason={} inventoryDelta={} leftUnreached={} clusterSize={} columnsAdded={}",
                instanceId,
                run.commandId,
                run.seed.toShortString(),
                reason,
                inventoryDelta,
                leftUnreached,
                run.cluster.size(),
                added
            );
        }
    }

    static boolean shouldIgnoreUnusableGatherTreeCluster(Set<BlockPos> cluster, String reason) {
        return isLargeMultiColumnTree(cluster)
            || "no_reachable_tree_logs".equals(reason)
            || "tree_exhausted".equals(reason)
            || "executor_deadline".equals(reason);
    }

    static boolean shouldRetryPartialGatherTreeExhaustion(
        String reason,
        int inventoryLogCount,
        int baselineLogCount,
        int retries
    ) {
        return "tree_exhausted".equals(reason)
            && retries < GATHER_TREE_PARTIAL_EXHAUSTION_RETRIES
            && inventoryLogCount > baselineLogCount
            && inventoryLogCount < GATHER_TREE_PARTIAL_EXHAUSTION_LOG_TARGET;
    }

    private static boolean isLargeMultiColumnTree(Set<BlockPos> cluster) {
        if (cluster == null || cluster.size() < 16) {
            return false;
        }
        Set<GridCell> columns = new HashSet<>();
        for (BlockPos log : cluster) {
            if (log != null) {
                columns.add(new GridCell(log.getX(), log.getZ()));
            }
        }
        return columns.size() >= 4;
    }

    private boolean isIgnoredGatherTreeSeed(BlockPos seed) {
        return seed != null && ignoredGatherTreeColumns.contains(new GridCell(seed.getX(), seed.getZ()));
    }

    // Exclude a drop-collect abandon's two XZ columns from gather_tree reselection: the abandoned drop's
    // own column AND the broken-log's column. Adding both stops selectNextTreeTarget from re-picking the
    // same trunk column's next log (climbing the stack into an identical unreachable drop). Survives the
    // resetGatherTreeCurrentTarget that follows each abandon; cleared only on pickup / partial retry.
    private void recordGatherTreeAbandonedDropColumns(GatherTreeRun run, BlockPos brokenLog, Vec3d drop) {
        if (run == null) {
            return;
        }
        if (drop != null) {
            run.abandonedDropColumns.add(new GridCell((int) Math.floor(drop.x), (int) Math.floor(drop.z)));
        }
        if (brokenLog != null) {
            run.abandonedDropColumns.add(new GridCell(brokenLog.getX(), brokenLog.getZ()));
        }
    }

    private void resetGatherTreeCurrentTarget(GatherTreeRun run) {
        run.currentTarget = null;
        run.currentAdjacentCell = null;
        run.currentAdjacentRoute = List.of();
        run.currentAdjacentReached = false;
        run.currentAdjacentLatchLogged = false;
        run.currentAdjacentLatchHoldLogged = false;
        run.targetOutOfReachRepositions = 0;
        run.currentAdjacentProgress.reset();
        run.excludedAdjacentCells.clear();
        run.pendingReachableSeedAttempt = null;
        if (run.reachableSeedFrontierSession.active()) {
            run.reachableSeedFrontierSession.rejectTarget("target_reset");
        }
        run.reachableSeedFrontierTraversal.clear();
        clearGatherTreeBreakStanceState(run, true);
        run.breakStarted = false;
        run.breakDone = false;
        run.collectStartedAtMs = 0L;
        run.collectProgress.reset();
        run.sideCollectStall.reset();
        clearGatherTreeOwnedDropState(run);
        clearNavigationState();
    }

    private void clearGatherTreeBreakStanceState(GatherTreeRun run, boolean resetAttempts) {
        if (run == null) {
            return;
        }
        run.breakStanceRoute = List.of();
        run.breakStanceCell = null;
        run.breakStanceTarget = null;
        run.breakStanceTrigger = "";
        run.breakStanceStart = null;
        run.breakStanceExpandedCells = 0;
        run.breakStanceReachDistance = 0.0D;
        run.breakStanceSelectedAtMs = 0L;
        run.breakStanceTraversal.clear();
        if (resetAttempts) {
            run.breakStanceRouteAttempts = 0;
            run.selectionEpisode = 0;
            run.excludedBreakStances.clear();
            run.breakStanceEpisode = null;
            run.breakStanceLastWaypoint = null;
            run.breakStanceLastWaypointIndex = -1;
            run.breakStanceLastRemainingCells = 0;
            run.breakStanceLastStableFeet = null;
            run.breakStanceLastMaximumWaypointIndex = -1;
            run.breakStanceLastProgressAtMs = 0L;
            run.breakStanceLastDescentPhase = "none";
            run.breakStanceLastTrigger = "";
        }
    }

    private void clearGatherTreeExecutionState(GatherTreeRun run) {
        if (run == null) {
            return;
        }
        blockBreakController.reset();
        resetGatherTreeCurrentTarget(run);
        gatherWoodLocalEgress.clearActive();
        gatherWoodLocalEgress.canonicalOverride = null;
    }

    private void clearGatherTreeForLifecycle() {
        if (activeGatherTree != null) {
            clearGatherTreeExecutionState(activeGatherTree);
            activeGatherTree = null;
        }
        activeGatherTreeSearch = null;
        gatherWoodLocalEgress.clearActive();
        gatherWoodLocalEgress.canonicalOverride = null;
        gatherTreeOwnedDropGazeCursor.resetAll();
        clearNavigationState();
        clearNav3dDriveState();
        clearGatherTreeInventoryRequirement();
    }

    private void clearGatherTreeOwnedDropState(GatherTreeRun run) {
        if (run == null) {
            return;
        }
        run.dropTracker.reset();
        run.ownedDropRoute = List.of();
        run.ownedDropRouteEntityId = null;
        run.ownedDropRoutePosition = null;
        run.ownedDropPickupCell = null;
        run.ownedDropReachedAtMs = 0L;
        run.ownedDropRecoveryRejected = false;
        gatherTreeOwnedDropGazeCursor.resetAll();
    }

    @Override
    public void clearNavigationState() {
        activeNavigationCommandId = "";
        activeNavigationWaypointIndex = 0;
        activeNavigationProgress = PathFollower.Progress.initial();
        activeNavigationWaypoints = List.of();
        activeNavigationRouteComputed = false;
        activeNavigationSuppliedRoute = false;
        activeNavigationJumpWaypointIndexes = Set.of();
        clearLocomotionNavigationRoute();
        navigationJumpRetryStreak.reset();
        abandonedJumpWaypointKey = "";
    }

    private void clearLocomotionNavigationRoute() {
        locomotionNavigationRouteReference = List.of();
        locomotionNavigationVoxelRoute = List.of();
        locomotionNavigationWorld = null;
    }

    private void clearNav3dDriveState() {
        nav3dCollectRoute = List.of();
        nav3dCollectRouteDrop = null;
        nav3dCollectRouteComputedMs = 0L;
        nav3dDriveGazeCursor.resetAll();
        nav3dOverlayWaypoints = List.of();
        nav3dLastProgressPos = null;
        nav3dLastProgressMs = 0L;
        nav3dLastTunnelDigTarget = null;
        nav3dLastTunnelBreakLogged = false;
        clearNav3dTunnelInteractionHold();
        nav3dConstructivePlan = null;
        nav3dConstructivePlanDrop = null;
        nav3dConstructivePlanComputedMs = 0L;
        nav3dPillarLandingMinFloorY = Integer.MIN_VALUE;
        nav3dPillarPlacedAtMs = 0L;
        nav3dPillarFoundation = null;
        nav3dNoRouteDrop = null;
        nav3dNoRouteBestDistSq = Double.MAX_VALUE;
        nav3dNoRouteSinceMs = 0L;
        nav3dNoRoutePlannedAtMs = 0L;
        nav3dDigCommandId = "";
        nav3dLastDigActiveMs = 0L;
        clearExploreFrontierState();
    }

    private List<VoxelCell> installNav3dCollectRoute(
        List<VoxelCell> candidate,
        Vec3d drop,
        long nowMs
    ) {
        if (!candidate.equals(nav3dCollectRoute)) {
            nav3dCollectRoute = List.copyOf(candidate);
            nav3dCollectRouteGeneration++;
            nav3dDriveGazeCursor.resetAll();
        }
        nav3dCollectRouteDrop = drop;
        nav3dCollectRouteComputedMs = nowMs;
        return nav3dCollectRoute;
    }

    private ControlDecision beginGatherTreeReachableSeedFrontierTraversal(
        MinecraftClient client,
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        GatherTreeRun run,
        GatherTreeReachableSeedAttempt attempt,
        long nowMs
    ) {
        if (attempt == null || !attempt.frontierFound() || run == null || run.currentTarget == null) {
            return null;
        }
        GatherTreeReachableSeedPlanner.FrontierPlan plan = attempt.result().frontierPlan();
        VoxelCell playerFeet = gatherTreePlayerFeet(player);
        String rejectionReason = "";
        if (run.reachableSeedFrontierSession.stageUsed()) {
            run.reachableSeedFrontierDuplicateStageAttempts++;
            rejectionReason = "stage_already_used";
        } else if (client == null || client.world == null || player == null || run.world != client.world) {
            rejectionReason = "world_changed";
        } else if (effective == null || !run.commandId.equals(effective.commandId())) {
            rejectionReason = "command_changed";
        } else if (plan == null || !run.currentTarget.equals(plan.target())) {
            rejectionReason = "target_changed";
        } else if (!client.world.getBlockState(plan.target()).isIn(BlockTags.LOGS)) {
            rejectionReason = "target_not_log";
        } else if (playerFeet == null || !playerFeet.equals(attempt.start()) || !playerFeet.equals(plan.origin())) {
            rejectionReason = "start_changed";
        } else if (plan.route().size() < 2 || !playerFeet.equals(plan.route().getFirst())) {
            rejectionReason = "route_start_mismatch";
        }
        if (!rejectionReason.isEmpty()) {
            return rejectGatherTreeReachableSeedFrontier(
                effective,
                run,
                attempt,
                rejectionReason,
                nowMs,
                null
            );
        }

        GatherTreeLivenessPolicy.BreakStanceEpisode episode =
            GatherTreeLivenessPolicy.beginBreakStanceEpisode(nowMs);
        GatherTreeReachableSeedFrontierSession.Transition transition =
            run.reachableSeedFrontierSession.beginStage(
                run.commandId,
                attempt.candidateFingerprint(),
                plan,
                episode,
                nowMs
            );
        if (!transition.accepted()) {
            return rejectGatherTreeReachableSeedFrontier(
                effective,
                run,
                attempt,
                transition.reason(),
                nowMs,
                null
            );
        }
        if (!run.reachableSeedFrontierTraversal.begin(
                plan.route(),
                playerFeet,
                nowMs,
                episode.deadlineAtMs()
            )) {
            run.reachableSeedFrontierSession.rejectTarget("route_start_mismatch");
            return rejectGatherTreeReachableSeedFrontier(
                effective,
                run,
                attempt,
                "route_start_mismatch",
                nowMs,
                null
            );
        }

        run.pendingReachableSeedAttempt = null;
        run.cachedTargetSelection = null;
        run.breakStanceRouteAttempts = 1;
        run.breakStanceEpisode = episode;
        run.breakStanceSelectedAtMs = nowMs;
        run.reachableSeedFrontierSelectedCount++;
        run.reachableSeedFrontierMaximumRouteLength = Math.max(
            run.reachableSeedFrontierMaximumRouteLength,
            plan.route().size()
        );
        run.reachableSeedFrontierMaximumExpandedCells = Math.max(
            run.reachableSeedFrontierMaximumExpandedCells,
            plan.expandedCells()
        );
        run.reachableSeedFrontierMaximumProgress = Math.max(
            run.reachableSeedFrontierMaximumProgress,
            plan.netProgress()
        );
        run.reachableSeedFrontierLastWaypointIndex =
            run.reachableSeedFrontierTraversal.waypointIndex();
        run.reachableSeedFrontierSource = attempt.source();
        run.reachableSeedFrontierCandidateCount = attempt.candidateCount();
        run.reachableSeedFrontierCacheStatus = attempt.cacheStatus();
        blockBreakController.reset();
        clearNavigationState();
        LOGGER.info(
            "gather_tree.reachable_seed_frontier_selected instanceId={} commandId={} source={} target={} candidateFingerprint={} stageEpisode={} origin={} frontier={} routeLength={} waypoint={} waypointIndex={} remainingCells={} startDistance={} remainingDistance={} netProgress={} candidateCount={} expandedCells={} totalComputations={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
            instanceId,
            run.commandId,
            attempt.source(),
            plan.target().toShortString(),
            Long.toUnsignedString(attempt.candidateFingerprint(), 16),
            run.reachableSeedFrontierSession.stageEpisode(),
            plan.origin(),
            plan.frontier(),
            plan.route().size(),
            run.reachableSeedFrontierTraversal.activeWaypoint(),
            run.reachableSeedFrontierTraversal.waypointIndex(),
            run.reachableSeedFrontierTraversal.remainingCells(),
            roundForLog(plan.startDistance()),
            roundForLog(plan.remainingDistance()),
            roundForLog(plan.netProgress()),
            attempt.candidateCount(),
            plan.expandedCells(),
            run.reachableSeedFrontierSession.plannerComputations(),
            run.reachableSeedFrontierTraversal.descentPhase().name().toLowerCase(Locale.ROOT),
            Math.max(0L, nowMs - run.startedAtMs),
            episode.remainingMs(nowMs),
            plan.reason()
        );
        return new ControlDecision(
            stopFrom(effective, "gather_tree_reachable_seed_frontier_selected"),
            InputState.stop()
        );
    }

    private ControlDecision resolveGatherTreeReachableSeedFrontierTraversal(
        MinecraftClient client,
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        GatherTreeRun run,
        long nowMs
    ) {
        GatherTreeReachableSeedFrontierSession session = run == null
            ? null
            : run.reachableSeedFrontierSession;
        if (client == null
            || client.world == null
            || player == null
            || run == null
            || session == null
            || !session.active()) {
            return rejectGatherTreeReachableSeedFrontier(
                effective,
                run,
                null,
                "lost_world_state",
                nowMs,
                null
            );
        }
        if (run.world != client.world || effective == null || !run.commandId.equals(effective.commandId())) {
            return rejectGatherTreeReachableSeedFrontier(
                effective,
                run,
                null,
                run.world != client.world ? "world_changed" : "command_changed",
                nowMs,
                null
            );
        }
        BlockPos target = session.target();
        if (target == null
            || run.currentTarget == null
            || !target.equals(run.currentTarget)
            || !client.world.getBlockState(target).isIn(BlockTags.LOGS)) {
            return rejectGatherTreeReachableSeedFrontier(
                effective,
                run,
                null,
                target == null || run.currentTarget == null || !target.equals(run.currentTarget)
                    ? "target_changed"
                    : "target_not_log",
                nowMs,
                null
            );
        }

        VoxelCell playerFeet = gatherTreePlayerFeet(player);
        GatherTreeReachableSeedFrontierController traversal = run.reachableSeedFrontierTraversal;
        VoxelCell activeWaypoint = traversal.activeWaypoint();
        boolean aligned = true;
        if (activeWaypoint != null) {
            Vec3d activeAim = new Vec3d(
                activeWaypoint.x() + 0.5D,
                activeWaypoint.y(),
                activeWaypoint.z() + 0.5D
            );
            LookAngles activeLook = lookAnglesToPoint(player, activeAim);
            aligned = Math.abs(wrapDegrees180(activeLook.yaw() - player.getYaw()))
                <= NAV3D_FORWARD_YAW_TOLERANCE_DEG;
        }
        GatherTreeReachableSeedFrontierController.Step step = traversal.tick(
            new GatherTreeBreakStanceTraversalController.Observation(
                playerFeet,
                player.getX(),
                player.getY(),
                player.getZ(),
                player.isOnGround(),
                aligned
            ),
            cell -> isSafeMiningWorkspaceTraversalCell(client, cell),
            nowMs
        );
        int previousWaypointIndex = run.reachableSeedFrontierLastWaypointIndex;
        if (step.waypointIndex() >= 0 && previousWaypointIndex >= 0
            && step.waypointIndex() < previousWaypointIndex) {
            run.reachableSeedFrontierCursorRegressionCount++;
        }
        run.reachableSeedFrontierLastWaypointIndex = Math.max(
            run.reachableSeedFrontierLastWaypointIndex,
            step.waypointIndex()
        );
        run.reachableSeedFrontierMaximumWaypointIndex = Math.max(
            run.reachableSeedFrontierMaximumWaypointIndex,
            step.maximumWaypointIndex()
        );
        if (step.waypointAdvanced()) {
            run.reachableSeedFrontierProgressCount++;
            LOGGER.info(
                "gather_tree.reachable_seed_frontier_progress instanceId={} commandId={} source={} target={} candidateFingerprint={} stageEpisode={} origin={} frontier={} routeLength={} waypoint={} waypointIndex={} remainingCells={} maximumWaypointIndex={} startDistance={} remainingDistance={} netProgress={} expandedCells={} totalComputations={} forwardResynchronized={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
                instanceId,
                run.commandId,
                run.reachableSeedFrontierSource,
                target.toShortString(),
                Long.toUnsignedString(session.candidateFingerprint(), 16),
                session.stageEpisode(),
                session.origin(),
                session.frontier(),
                session.stageRouteLength(),
                step.waypoint(),
                step.waypointIndex(),
                step.remainingCells(),
                step.maximumWaypointIndex(),
                roundForLog(session.startDistance()),
                roundForLog(session.plannedRemainingDistance()),
                roundForLog(session.startDistance() - session.plannedRemainingDistance()),
                session.expandedCells(),
                session.plannerComputations(),
                step.forwardResynchronized(),
                step.lastProgressAgeMs(),
                step.descentPhase().name().toLowerCase(Locale.ROOT),
                Math.max(0L, nowMs - run.startedAtMs),
                step.remainingDeadlineMs(),
                step.forwardResynchronized() ? "forward_resynchronized" : "cursor_advanced"
            );
        }

        if (step.outcome() == GatherTreeReachableSeedFrontierController.Outcome.REACHED) {
            GatherTreeReachableSeedFrontierSession.Transition reached = session.markFrontierReached(
                run.commandId,
                target,
                playerFeet,
                player.isOnGround(),
                nowMs
            );
            if (!reached.accepted()) {
                return rejectGatherTreeReachableSeedFrontier(
                    effective, run, null, reached.reason(), nowMs, step);
            }
            run.reachableSeedFrontierReachedCount++;
            run.reachableSeedFrontierMaximumProgress = Math.max(
                run.reachableSeedFrontierMaximumProgress,
                session.actualNetProgress()
            );
            LOGGER.info(
                "gather_tree.reachable_seed_frontier_reached instanceId={} commandId={} source={} target={} candidateFingerprint={} stageEpisode={} origin={} frontier={} actualFeet={} routeLength={} waypointIndex={} maximumWaypointIndex={} startDistance={} remainingDistance={} netProgress={} expandedCells={} totalComputations={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason=frontier_reached",
                instanceId,
                run.commandId,
                run.reachableSeedFrontierSource,
                target.toShortString(),
                Long.toUnsignedString(session.candidateFingerprint(), 16),
                session.stageEpisode(),
                session.origin(),
                session.frontier(),
                playerFeet,
                session.stageRouteLength(),
                step.waypointIndex(),
                step.maximumWaypointIndex(),
                roundForLog(session.startDistance()),
                roundForLog(session.actualRemainingDistance()),
                roundForLog(session.actualNetProgress()),
                session.expandedCells(),
                session.plannerComputations(),
                step.descentPhase().name().toLowerCase(Locale.ROOT),
                Math.max(0L, nowMs - run.startedAtMs),
                step.remainingDeadlineMs()
            );
            return new ControlDecision(
                stopFrom(effective, "gather_tree_reachable_seed_frontier_reached"),
                InputState.stop()
            );
        }
        if (step.outcome() == GatherTreeReachableSeedFrontierController.Outcome.HOLD_AT_FRONTIER) {
            GatherTreeReachableSeedFrontierSession.Transition held = session.completeStoppedHoldTick(
                run.commandId,
                target,
                playerFeet,
                player.isOnGround(),
                step.stopped(),
                nowMs
            );
            if (!held.accepted()) {
                return rejectGatherTreeReachableSeedFrontier(
                    effective, run, null, held.reason(), nowMs, step);
            }
            return new ControlDecision(
                stopFrom(effective, "gather_tree_reachable_seed_frontier_hold"),
                InputState.stop()
            );
        }
        if (step.outcome() == GatherTreeReachableSeedFrontierController.Outcome.READY_TO_REPLAN) {
            GatherTreeReachableSeedFrontierSession.ReplanReservation reservation =
                session.reserveSingletonReplan(
                    run.commandId,
                    target,
                    playerFeet,
                    player.isOnGround(),
                    nowMs
                );
            if (!reservation.granted()) {
                String reason = reservation.transition() == null
                    ? "singleton_replan_not_reserved"
                    : reservation.transition().reason();
                return rejectGatherTreeReachableSeedFrontier(
                    effective, run, null, reason, nowMs, step);
            }
            GatherTreeReachableSeedAttempt singletonAttempt = planGatherTreeReachableSeed(
                client,
                player,
                run.commandId,
                "frontier_target",
                List.of(target),
                run.excludedBreakStances,
                session.candidateFingerprint(),
                "bypass",
                false
            );
            GatherTreeReachableSeedFrontierSession.ReplanResolution resolution =
                session.resolveSingletonReplan(
                    reservation.permit(),
                    singletonAttempt == null ? null : singletonAttempt.result(),
                    nowMs
                );
            run.reachableSeedFrontierTargetReplannedCount++;
            int replanExpandedCells = singletonAttempt == null || singletonAttempt.result() == null
                ? 0
                : singletonAttempt.result().expandedCells();
            run.reachableSeedFrontierMaximumExpandedCells = Math.max(
                run.reachableSeedFrontierMaximumExpandedCells,
                replanExpandedCells
            );
            LOGGER.info(
                "gather_tree.reachable_seed_frontier_target_replanned instanceId={} commandId={} source={} target={} candidateFingerprint={} stageEpisode={} origin={} frontier={} actualFeet={} routeLength={} startDistance={} remainingDistance={} netProgress={} candidateCount={} expandedCells={} totalComputations={} outcome={} routeType={} replanOutcome={} finalStance={} finalRouteLength={} elapsedMs={} remainingDeadlineMs={} reason={}",
                instanceId,
                run.commandId,
                run.reachableSeedFrontierSource,
                target.toShortString(),
                Long.toUnsignedString(session.candidateFingerprint(), 16),
                session.stageEpisode(),
                session.origin(),
                session.frontier(),
                playerFeet,
                session.stageRouteLength(),
                roundForLog(session.startDistance()),
                roundForLog(session.actualRemainingDistance()),
                roundForLog(session.actualNetProgress()),
                run.reachableSeedFrontierCandidateCount,
                replanExpandedCells,
                session.plannerComputations(),
                resolution.accepted() ? "selected" : "rejected",
                resolution.accepted() ? "3d" : "none",
                resolution.accepted() ? "final_stance" : "rejected",
                resolution.plan() == null ? "" : resolution.plan().stance(),
                resolution.plan() == null ? 0 : resolution.plan().route().size(),
                Math.max(0L, nowMs - run.startedAtMs),
                run.breakStanceEpisode == null ? 0L : run.breakStanceEpisode.remainingMs(nowMs),
                resolution.transition() == null ? "singleton_replan_missing" : resolution.transition().reason()
            );
            if (!resolution.accepted()) {
                String reason = resolution.transition() == null
                    ? "singleton_replan_missing"
                    : resolution.transition().reason();
                return rejectGatherTreeReachableSeedFrontier(
                    effective, run, singletonAttempt, reason, nowMs, step);
            }
            run.reachableSeedFrontierPostStage3dCount++;
            run.reachableSeedFrontierTraversal.clear();
            ControlDecision finalTraversal = beginGatherTreeReachableSeedTraversal(
                client,
                player,
                effective,
                run,
                singletonAttempt,
                nowMs,
                true
            );
            if (finalTraversal != null) {
                return finalTraversal;
            }
            return rejectGatherTreeReachableSeedFrontier(
                effective,
                run,
                singletonAttempt,
                "singleton_route_admission_failed",
                nowMs,
                step
            );
        }
        if (step.outcome() == GatherTreeReachableSeedFrontierController.Outcome.REJECTED) {
            return rejectGatherTreeReachableSeedFrontier(
                effective, run, null, step.reason(), nowMs, step);
        }
        if (step.outcome() == GatherTreeReachableSeedFrontierController.Outcome.IDLE
            || step.waypoint() == null) {
            return rejectGatherTreeReachableSeedFrontier(
                effective, run, null, "traversal_inactive", nowMs, step);
        }

        Vec3d aim = new Vec3d(
            step.waypoint().x() + 0.5D,
            step.waypoint().y(),
            step.waypoint().z() + 0.5D
        );
        LookAngles look = lookAnglesToPoint(player, aim);
        boolean forward = step.forward() && !step.waypointAdvanced();
        InputState input = new InputState(
            forward,
            false,
            false,
            false,
            forward && step.jump(),
            step.sneak(),
            forward ? 1.0F : 0.0F,
            0.0F
        );
        String driveAction = step.descentExempt()
            ? "gather_tree_reachable_seed_frontier_nav3d_descend"
            : "gather_tree_reachable_seed_frontier_nav3d";
        return new ControlDecision(
            lookIntentForAngles(effective, look.yaw(), look.pitch(), driveAction),
            input
        );
    }

    private ControlDecision rejectGatherTreeReachableSeedFrontier(
        BrainLink.Intent effective,
        GatherTreeRun run,
        GatherTreeReachableSeedAttempt attempt,
        String reason,
        long nowMs,
        GatherTreeReachableSeedFrontierController.Step step
    ) {
        String normalizedReason = reason == null || reason.isBlank() ? "target_rejected" : reason;
        if (run == null) {
            return new ControlDecision(
                stopFrom(effective, "gather_tree_reachable_seed_frontier_rejected:" + normalizedReason),
                InputState.stop()
            );
        }
        GatherTreeReachableSeedFrontierSession session = run.reachableSeedFrontierSession;
        if (session.stageUsed()
            && session.phase() != GatherTreeReachableSeedFrontierSession.Phase.REJECTED) {
            session.rejectTarget(normalizedReason);
        }
        BlockPos target = run.currentTarget == null ? session.target() : run.currentTarget;
        run.reachableSeedFrontierRejectedCount++;
        run.reachableSeedFrontierRejectionReasons.merge(normalizedReason, 1, Integer::sum);
        LOGGER.warn(
            "gather_tree.reachable_seed_frontier_rejected instanceId={} commandId={} source={} target={} candidateFingerprint={} stageEpisode={} origin={} frontier={} routeLength={} waypoint={} waypointIndex={} remainingCells={} maximumWaypointIndex={} startDistance={} remainingDistance={} netProgress={} candidateCount={} expandedCells={} totalComputations={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
            instanceId,
            run.commandId,
            run.reachableSeedFrontierSource.isEmpty() && attempt != null
                ? attempt.source()
                : run.reachableSeedFrontierSource,
            target == null ? "" : target.toShortString(),
            Long.toUnsignedString(
                session.stageUsed()
                    ? session.candidateFingerprint()
                    : attempt == null ? 0L : attempt.candidateFingerprint(),
                16
            ),
            session.stageEpisode(),
            session.origin(),
            session.frontier(),
            session.stageRouteLength(),
            step == null ? run.reachableSeedFrontierTraversal.activeWaypoint() : step.waypoint(),
            step == null ? run.reachableSeedFrontierTraversal.waypointIndex() : step.waypointIndex(),
            step == null ? run.reachableSeedFrontierTraversal.remainingCells() : step.remainingCells(),
            step == null ? run.reachableSeedFrontierTraversal.maximumWaypointIndex() : step.maximumWaypointIndex(),
            roundForLog(session.startDistance()),
            roundForLog(Double.isFinite(session.actualRemainingDistance())
                ? session.actualRemainingDistance()
                : session.plannedRemainingDistance()),
            roundForLog(session.actualNetProgress()),
            run.reachableSeedFrontierCandidateCount > 0
                ? run.reachableSeedFrontierCandidateCount
                : attempt == null ? 0 : attempt.candidateCount(),
            session.expandedCells(),
            session.plannerComputations(),
            step == null
                ? run.reachableSeedFrontierTraversal.descentPhase().name().toLowerCase(Locale.ROOT)
                : step.descentPhase().name().toLowerCase(Locale.ROOT),
            Math.max(0L, nowMs - run.startedAtMs),
            run.breakStanceEpisode == null ? 0L : run.breakStanceEpisode.remainingMs(nowMs),
            normalizedReason
        );
        if (target != null) {
            run.abandonedTargets.add(target);
        }
        run.reachableSeedFrontierTraversal.clear();
        resetGatherTreeCurrentTarget(run);
        return new ControlDecision(
            stopFrom(effective, "gather_tree_reachable_seed_frontier_rejected:" + normalizedReason),
            InputState.stop()
        );
    }

    private ControlDecision beginGatherTreeReachableSeedTraversal(
        MinecraftClient client,
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        GatherTreeRun run,
        GatherTreeReachableSeedAttempt attempt,
        long nowMs,
        boolean fromFrontier
    ) {
        if (attempt == null || !attempt.found() || run == null || run.currentTarget == null) {
            return null;
        }
        GatherTreeReachableSeedPlanner.Plan plan = attempt.result().plan();
        run.pendingReachableSeedAttempt = null;
        run.breakStanceRouteAttempts = fromFrontier
            ? 2
            : Math.max(1, run.breakStanceRouteAttempts);
        VoxelCell playerFeet = gatherTreePlayerFeet(player);
        String rejectionReason = "";
        if (client == null || client.world == null || player == null || run.world != client.world) {
            rejectionReason = "world_changed";
        } else if (effective == null || !run.commandId.equals(effective.commandId())) {
            rejectionReason = "command_changed";
        } else if (!run.currentTarget.equals(plan.target())) {
            rejectionReason = "target_changed";
        } else if (!client.world.getBlockState(plan.target()).isIn(BlockTags.LOGS)) {
            rejectionReason = "target_not_log";
        } else if (playerFeet == null || !playerFeet.equals(attempt.start())) {
            rejectionReason = "start_changed";
        } else if (plan.route().isEmpty() || !playerFeet.equals(plan.route().getFirst())) {
            rejectionReason = "route_start_mismatch";
        }
        if (!rejectionReason.isEmpty()) {
            recordGatherTreeReachableSeedAdmissionRejected(run, attempt, rejectionReason, nowMs);
            return null;
        }

        run.breakStanceRoute = plan.route();
        run.breakStanceCell = plan.stance();
        run.breakStanceTarget = plan.target();
        run.breakStanceTrigger = fromFrontier
            ? "reachable_seed_frontier_3d"
            : "reachable_seed_3d";
        run.breakStanceStart = playerFeet;
        run.breakStanceExpandedCells = plan.expandedCells();
        run.breakStanceReachDistance = plan.reachDistance();
        run.breakStanceSelectedAtMs = nowMs;
        if (!fromFrontier || run.breakStanceEpisode == null) {
            run.breakStanceEpisode = GatherTreeLivenessPolicy.beginBreakStanceEpisode(nowMs);
        }
        if (!run.breakStanceTraversal.begin(
            plan.route(),
            playerFeet,
            nowMs,
            run.breakStanceEpisode.deadlineAtMs()
        )) {
            clearGatherTreeBreakStanceState(run, false);
            recordGatherTreeReachableSeedAdmissionRejected(run, attempt, "route_start_mismatch", nowMs);
            return null;
        }
        run.selectionEpisode = ++run.selectionEpisodeCounter;
        run.breakStanceNav3dSelectedCount++;
        run.reachableSeedNav3dSelectedCount++;
        if ("initial_seed".equals(attempt.source())) {
            run.reachableSeedInitialSelectedCount++;
        } else if ("cluster_target".equals(attempt.source())) {
            run.reachableSeedClusterSelectedCount++;
        }
        run.reachableSeedMaximumRouteLength = Math.max(
            run.reachableSeedMaximumRouteLength,
            plan.route().size()
        );
        run.reachableSeedMaximumExpandedCells = Math.max(
            run.reachableSeedMaximumExpandedCells,
            plan.expandedCells()
        );
        blockBreakController.reset();
        LOGGER.info(
            "gather_tree.reachable_seed_nav3d_selected instanceId={} commandId={} source={} start={} target={} stance={} routeLength={} candidateCount={} expandedCells={} reachDistance={} verticalDelta={} cacheStatus={} elapsedMs={} reason={}",
            instanceId,
            run.commandId,
            attempt.source(),
            playerFeet,
            plan.target().toShortString(),
            plan.stance(),
            plan.route().size(),
            attempt.candidateCount(),
            plan.expandedCells(),
            roundForLog(plan.reachDistance()),
            plan.verticalDelta(),
            attempt.cacheStatus(),
            Math.max(0L, nowMs - run.startedAtMs),
            plan.reason()
        );
        LOGGER.info(
            "gather_tree.break_stance_nav3d_selected instanceId={} commandId={} selectionEpisode={} target={} trigger={} start={} selectedStance={} routeLength={} routeAttempt={} expandedCells={} reachDistance={} verticalDelta={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
            instanceId,
            run.commandId,
            run.selectionEpisode,
            run.currentTarget.toShortString(),
            run.breakStanceTrigger,
            playerFeet,
            plan.stance(),
            plan.route().size(),
            run.breakStanceRouteAttempts,
            plan.expandedCells(),
            roundForLog(plan.reachDistance()),
            plan.verticalDelta(),
            run.breakStanceTraversal.waypointIndex(),
            run.breakStanceTraversal.remainingCells(),
            run.breakStanceTraversal.stableFeet(),
            run.breakStanceTraversal.maximumWaypointIndex(),
            run.breakStanceTraversal.lastProgressAgeMs(nowMs),
            run.breakStanceTraversal.descentPhase().name().toLowerCase(Locale.ROOT),
            run.breakStanceEpisode.elapsedMs(nowMs),
            run.breakStanceEpisode.remainingMs(nowMs),
            plan.reason()
        );
        return new ControlDecision(
            stopFrom(effective, "gather_tree_reachable_seed_nav3d_selected"),
            InputState.stop()
        );
    }

    private void recordGatherTreeReachableSeedAdmissionRejected(
        GatherTreeRun run,
        GatherTreeReachableSeedAttempt attempt,
        String reason,
        long nowMs
    ) {
        if (run == null || attempt == null || attempt.result() == null) {
            return;
        }
        run.reachableSeedNav3dRejectedCount++;
        if ("initial_seed".equals(attempt.source())) {
            run.reachableSeedInitialRejectedCount++;
        } else if ("cluster_target".equals(attempt.source())) {
            run.reachableSeedClusterRejectedCount++;
        }
        GatherTreeReachableSeedPlanner.Plan plan = attempt.result().plan();
        LOGGER.warn(
            "gather_tree.reachable_seed_nav3d_rejected instanceId={} commandId={} source={} start={} target={} stance={} routeLength={} candidateCount={} expandedCells={} reachDistance={} verticalDelta={} cacheStatus={} elapsedMs={} reason={}",
            instanceId,
            run.commandId,
            attempt.source(),
            attempt.start(),
            plan == null || plan.target() == null ? "" : plan.target().toShortString(),
            plan == null ? "" : plan.stance(),
            plan == null ? 0 : plan.route().size(),
            attempt.candidateCount(),
            attempt.result().expandedCells(),
            plan == null ? 0.0D : roundForLog(plan.reachDistance()),
            plan == null ? 0 : plan.verticalDelta(),
            attempt.cacheStatus(),
            Math.max(0L, nowMs - run.startedAtMs),
            reason
        );
    }

    private ControlDecision navigateToGatherTreeAdjacentCell(
        MinecraftClient client,
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        GatherTreeRun run,
        long nowMs
    ) {
        GridCell start = new GridCell((int) Math.floor(player.getX()), (int) Math.floor(player.getZ()));
        if (GatherTreeBreakStanceTraversal.active(run.breakStanceRoute, run.breakStanceTrigger)) {
            return resolveGatherTreeBreakStanceTraversal(
                client, player, effective, run, run.breakStanceTrigger, nowMs);
        }
        if (run.currentAdjacentCell == null) {
            int referenceFeetY = (int) Math.floor(player.getY());
            int targetX = run.currentTarget.getX();
            int targetZ = run.currentTarget.getZ();
            WorldGridPerception perception = new WorldGridPerception(
                client.world,
                referenceFeetY,
                Math.min(start.x(), targetX) - NAVIGATION_PERCEPTION_MARGIN,
                Math.max(start.x(), targetX) + NAVIGATION_PERCEPTION_MARGIN,
                Math.min(start.z(), targetZ) - NAVIGATION_PERCEPTION_MARGIN,
                Math.max(start.z(), targetZ) + NAVIGATION_PERCEPTION_MARGIN
            );
            GridPerception routePerception = maybeAnchorCurrentStart(client.world, perception, start, referenceFeetY, true);
            if (routePerception != perception) {
                LOGGER.info(
                    "navigation.start_anchored instanceId={} commandId={} reason=gather_tree_adjacent start={} referenceFeetY={} perceivedSurface={} anchoredSurface={}",
                    instanceId,
                    run.commandId,
                    start,
                    referenceFeetY,
                    formatSurface(perception, start),
                    referenceFeetY
                );
            }
            Set<GridCell> excludedBreakCells = gatherTreeBreakNavigationExclusions(client.world, run);
            GatherLogPlanner.AdjacentPlan plan = GatherLogPlanner.chooseBreakCell(
                routePerception,
                start,
                targetX,
                run.currentTarget.getY(),
                targetZ,
                excludedBreakCells
            );
            if (plan.cell() == null) {
                GatherLogPlanner.AdjacentPlan continuationPlan = chooseGatherTreeContinuationBreakCell(
                    client.world,
                    routePerception,
                    start,
                    run,
                    excludedBreakCells
                );
                if (continuationPlan != null && continuationPlan.cell() != null) {
                    LOGGER.info(
                        "gather_tree.adjacent_continuation_fallback instanceId={} commandId={} target={} previousReason={} adjacent={} routeLength={} reason={}",
                        instanceId,
                        run.commandId,
                        run.currentTarget.toShortString(),
                        plan.reason(),
                        continuationPlan.cell(),
                        continuationPlan.route().size(),
                        continuationPlan.reason()
                    );
                    plan = continuationPlan;
                }
            }
            if (plan.cell() == null) {
                LOGGER.warn(
                    "gather_tree.no_adjacent_path instanceId={} commandId={} target={} reason={}",
                    instanceId,
                    run.commandId,
                    run.currentTarget.toShortString(),
                    plan.reason()
                );
                return resolveGatherTreeBreakStanceTraversal(
                    client, player, effective, run, "no_2d_break_stance", nowMs);
            }
            run.currentAdjacentCell = plan.cell();
            run.currentAdjacentRoute = plan.route();
            run.currentAdjacentReached = false;
            run.currentAdjacentLatchLogged = false;
            run.currentAdjacentLatchHoldLogged = false;
            LOGGER.info(
                "gather_tree.adjacent_selected instanceId={} commandId={} target={} adjacent={} routeLength={} reason={}",
                instanceId,
                run.commandId,
                run.currentTarget.toShortString(),
                run.currentAdjacentCell,
                plan.route().size(),
                plan.reason()
            );
        }
        double distance = Math.hypot(PathFollower.center(run.currentAdjacentCell.x()) - player.getX(), PathFollower.center(run.currentAdjacentCell.z()) - player.getZ());
        if (run.currentAdjacentReached) {
            if (!run.currentAdjacentLatchHoldLogged && !start.equals(run.currentAdjacentCell)) {
                run.currentAdjacentLatchHoldLogged = true;
                LOGGER.info(
                    "gather_tree.adjacent_latch_hold instanceId={} commandId={} target={} adjacent={} centerDistance={}",
                    instanceId,
                    run.commandId,
                    run.currentTarget.toShortString(),
                    run.currentAdjacentCell,
                    roundForLog(distance)
                );
            }
            return null;
        }
        if (start.equals(run.currentAdjacentCell) || distance <= GATHER_ARRIVE_EPSILON) {
            run.currentAdjacentReached = true;
            run.currentAdjacentProgress.reset();
            if (!run.currentAdjacentLatchLogged) {
                run.currentAdjacentLatchLogged = true;
                LOGGER.info(
                    "gather_tree.adjacent_latched instanceId={} commandId={} target={} adjacent={} centerDistance={}",
                    instanceId,
                    run.commandId,
                    run.currentTarget.toShortString(),
                    run.currentAdjacentCell,
                    roundForLog(distance)
                );
            }
            if (start.equals(run.currentAdjacentCell) && distance > GATHER_ARRIVE_EPSILON) {
                LOGGER.info(
                    "gather_tree.adjacent_arrived_by_cell instanceId={} commandId={} target={} adjacent={} centerDistance={}",
                    instanceId,
                    run.commandId,
                    run.currentTarget.toShortString(),
                    run.currentAdjacentCell,
                    roundForLog(distance)
                );
            }
            return null;
        }
        AdjacentMoveProgressTracker.Result progress = run.currentAdjacentProgress.updateDistanceOnly(
            run.currentAdjacentCell,
            distance,
            nowMs,
            gatherAdjacentMoveStallMs(run.currentAdjacentRoute, distance),
            GATHER_ADJACENT_MOVE_IMPROVEMENT
        );
        if (progress.stalled()) {
            run.excludedAdjacentCells.add(run.currentAdjacentCell);
            recordGatherTreeFailedBreakStance(run, player);
            run.currentAdjacentMoveStalls++;
            LOGGER.warn(
                "gather_tree.adjacent_move_stall instanceId={} commandId={} target={} adjacent={} distance={} bestDistance={} stalledMs={} stalls={}",
                instanceId,
                run.commandId,
                run.currentTarget.toShortString(),
                run.currentAdjacentCell,
                roundForLog(distance),
                roundForLog(progress.bestDistance()),
                progress.stalledMs(),
                run.currentAdjacentMoveStalls
            );
            run.currentAdjacentCell = null;
            run.currentAdjacentRoute = List.of();
            run.currentAdjacentReached = false;
            run.currentAdjacentLatchLogged = false;
            run.currentAdjacentLatchHoldLogged = false;
            run.currentAdjacentProgress.reset();
            run.breakStanceTrigger = "adjacent_move_stall";
            clearNavigationState();
            return new ControlDecision(stopFrom(effective, "gather_tree_adjacent_move_stall_reposition"), InputState.stop());
        }
        BrainLink.Intent navIntent = new BrainLink.Intent(
            "navigate_to_point",
            false,
            false,
            false,
            false,
            false,
            false,
            null,
            null,
            PathFollower.center(run.currentAdjacentCell.x()),
            PathFollower.center(run.currentAdjacentCell.z()),
            run.currentAdjacentRoute,
            List.of(),
            GATHER_ARRIVE_EPSILON,
            List.of(),
            effective.expiresAtMs(),
            "gather_tree_nav_adjacent",
            run.commandId + ":tree:adjacent"
        );
        return resolveNavigationControl(client, player, navIntent);
    }

    private ControlDecision resolveGatherTreeBreakStanceTraversal(
        MinecraftClient client,
        ClientPlayerEntity player,
        BrainLink.Intent effective,
        GatherTreeRun run,
        String trigger,
        long nowMs
    ) {
        if (client == null || client.world == null || player == null || run == null || run.currentTarget == null) {
            return rejectGatherTreeBreakStance(effective, run, trigger, "lost_world_state", nowMs);
        }
        String effectiveTrigger = trigger == null || trigger.isBlank() ? run.breakStanceTrigger : trigger;
        boolean noTwoDimensionalStance = "no_2d_break_stance".equals(effectiveTrigger);
        boolean reachableSeedPlan = ("reachable_seed_3d".equals(effectiveTrigger)
            || "reachable_seed_frontier_3d".equals(effectiveTrigger))
            && GatherTreeBreakStanceTraversal.active(run.breakStanceRoute, run.breakStanceTrigger);
        if (!reachableSeedPlan && !GatherTreeBreakStanceTraversal.shouldAttempt(
            noTwoDimensionalStance,
            "adjacent_move_stall".equals(effectiveTrigger) ? 1 : 0,
            "target_out_of_reach".equals(effectiveTrigger) ? 1 : 0
        )) {
            return rejectGatherTreeBreakStance(effective, run, effectiveTrigger, "unsupported_trigger", nowMs);
        }
        if (run.breakStanceEpisode != null
            && run.breakStanceEpisode.expiredAt(nowMs)
            && !client.world.getBlockState(run.currentTarget).isAir()
            && !run.breakStanceTraversal.finalLandingGraceAt(nowMs)) {
            return expireGatherTreeBreakStanceTarget(effective, run, nowMs);
        }

        VoxelCell playerFeet = gatherWoodLocalEgressFeet(player, run.commandId);
        if (run.breakStanceRoute.isEmpty()) {
            VoxelCell targetCell = new VoxelCell(
                run.currentTarget.getX(), run.currentTarget.getY(), run.currentTarget.getZ());
            WorldVoxelPerception perception = new WorldVoxelPerception(
                client.world,
                playerFeet,
                targetCell,
                NAVIGATION_PERCEPTION_MARGIN,
                NAVIGATION_PERCEPTION_MARGIN
            );
            if (!perception.isStandable(playerFeet.x(), playerFeet.y(), playerFeet.z())
                || gatherWoodLocalEgressActive(run.commandId, "gather_tree.break_stance")) {
                ControlDecision localEgress = maybeResolveGatherWoodLocalEgress(
                    client,
                    player,
                    effective,
                    "gather_tree.break_stance",
                    "start_unstandable",
                    targetCell,
                    nowMs
                );
                if (localEgress != null) {
                    return localEgress;
                }
                playerFeet = gatherWoodLocalEgressFeet(player, run.commandId);
                perception = new WorldVoxelPerception(
                    client.world,
                    playerFeet,
                    targetCell,
                    NAVIGATION_PERCEPTION_MARGIN,
                    NAVIGATION_PERCEPTION_MARGIN
                );
                if (!perception.isStandable(playerFeet.x(), playerFeet.y(), playerFeet.z())) {
                    return rejectGatherTreeBreakStance(
                        effective, run, effectiveTrigger, "start_unstandable", nowMs);
                }
            }
            if (!GatherTreeBreakStanceTraversal.canCompute(run.breakStanceRouteAttempts)) {
                return rejectGatherTreeBreakStance(effective, run, effectiveTrigger, "route_attempt_limit", nowMs);
            }
            run.breakStanceRouteAttempts++;
            double interactionReach = Math.min(4.8D, Math.max(1.0D, player.getBlockInteractionRange()));
            GatherTreeBreakStancePlanner.Result result = GatherTreeBreakStancePlanner.plan(
                perception,
                playerFeet,
                run.currentTarget,
                interactionReach,
                run.excludedBreakStances
            );
            if (!result.found()) {
                return rejectGatherTreeBreakStance(
                    effective, run, effectiveTrigger, result.failureReason(), nowMs, result.expandedCells());
            }
            GatherTreeBreakStancePlanner.Plan plan = result.plan();
            run.breakStanceRoute = plan.route();
            run.breakStanceCell = plan.stance();
            run.breakStanceTarget = run.currentTarget.toImmutable();
            run.breakStanceTrigger = effectiveTrigger;
            run.breakStanceStart = playerFeet;
            run.breakStanceExpandedCells = plan.expandedCells();
            run.breakStanceReachDistance = plan.reachDistance();
            run.breakStanceSelectedAtMs = nowMs;
            if (run.breakStanceEpisode == null) {
                run.breakStanceEpisode = GatherTreeLivenessPolicy.beginBreakStanceEpisode(nowMs);
            } else {
                run.breakStanceEpisode = run.breakStanceEpisode.afterReplan();
            }
            if (!run.breakStanceTraversal.begin(
                plan.route(),
                playerFeet,
                nowMs,
                run.breakStanceEpisode.deadlineAtMs()
            )) {
                return rejectGatherTreeBreakStance(
                    effective, run, effectiveTrigger, "route_start_mismatch", nowMs);
            }
            run.selectionEpisode = ++run.selectionEpisodeCounter;
            run.breakStanceNav3dSelectedCount++;
            blockBreakController.reset();
            LOGGER.info(
                "gather_tree.break_stance_nav3d_selected instanceId={} commandId={} selectionEpisode={} target={} trigger={} start={} selectedStance={} routeLength={} routeAttempt={} expandedCells={} reachDistance={} verticalDelta={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
                instanceId,
                run.commandId,
                run.selectionEpisode,
                run.currentTarget.toShortString(),
                effectiveTrigger,
                playerFeet,
                plan.stance(),
                plan.route().size(),
                run.breakStanceRouteAttempts,
                plan.expandedCells(),
                roundForLog(plan.reachDistance()),
                plan.verticalDelta(),
                run.breakStanceTraversal.waypointIndex(),
                run.breakStanceTraversal.remainingCells(),
                run.breakStanceTraversal.stableFeet(),
                run.breakStanceTraversal.maximumWaypointIndex(),
                run.breakStanceTraversal.lastProgressAgeMs(nowMs),
                run.breakStanceTraversal.descentPhase().name().toLowerCase(Locale.ROOT),
                run.breakStanceEpisode.elapsedMs(nowMs),
                run.breakStanceEpisode.remainingMs(nowMs),
                plan.reason()
            );
            return new ControlDecision(stopFrom(effective, "gather_tree_break_stance_nav3d_selected"), InputState.stop());
        }

        if (!run.currentTarget.equals(run.breakStanceTarget)) {
            return rejectGatherTreeBreakStance(effective, run, effectiveTrigger, "target_changed", nowMs);
        }
        GatherTreeBreakStanceTraversalController traversal = run.breakStanceTraversal;
        VoxelCell activeWaypoint = traversal.activeWaypoint();
        boolean aligned = true;
        if (activeWaypoint != null) {
            Vec3d activeAim = new Vec3d(
                activeWaypoint.x() + 0.5D,
                activeWaypoint.y(),
                activeWaypoint.z() + 0.5D
            );
            LookAngles activeLook = lookAnglesToPoint(player, activeAim);
            aligned = Math.abs(wrapDegrees180(activeLook.yaw() - player.getYaw()))
                <= NAV3D_FORWARD_YAW_TOLERANCE_DEG;
        }
        GatherTreeBreakStanceTraversalController.Step step = traversal.tick(
            new GatherTreeBreakStanceTraversalController.Observation(
                playerFeet,
                player.getX(),
                player.getY(),
                player.getZ(),
                player.isOnGround(),
                aligned
            ),
            cell -> isSafeMiningWorkspaceTraversalCell(client, cell),
            nowMs
        );
        long episodeElapsedMs = run.breakStanceEpisode == null
            ? 0L
            : run.breakStanceEpisode.elapsedMs(nowMs);
        long remainingDeadlineMs = run.breakStanceEpisode == null
            ? 0L
            : run.breakStanceEpisode.remainingMs(nowMs);
        run.breakStanceNav3dMaximumWaypointIndex = Math.max(
            run.breakStanceNav3dMaximumWaypointIndex,
            step.maximumWaypointIndex()
        );
        updateGatherTreeBreakStanceEpisodeMetrics(run, nowMs);
        captureGatherTreeBreakStanceDiagnostics(run, step, effectiveTrigger, nowMs);
        logGatherTreeBreakStanceTransitions(
            run,
            effectiveTrigger,
            step,
            episodeElapsedMs,
            remainingDeadlineMs
        );

        if (step.outcome() == GatherTreeBreakStanceTraversalController.Outcome.REACHED) {
            run.currentAdjacentCell = new GridCell(run.breakStanceCell.x(), run.breakStanceCell.z());
            run.currentAdjacentRoute = List.of();
            run.currentAdjacentReached = true;
            run.currentAdjacentLatchLogged = true;
            run.currentAdjacentLatchHoldLogged = false;
            run.breakStanceNav3dReachedCount++;
            blockBreakController.reset();
            LOGGER.info(
                "gather_tree.break_stance_nav3d_reached instanceId={} commandId={} selectionEpisode={} target={} trigger={} start={} selectedStance={} actualStance={} routeLength={} routeAttempt={} expandedCells={} reachDistance={} verticalDelta={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason=stance_cell",
                instanceId,
                run.commandId,
                run.selectionEpisode,
                run.currentTarget.toShortString(),
                effectiveTrigger,
                run.breakStanceStart,
                run.breakStanceCell,
                playerFeet,
                run.breakStanceRoute.size(),
                run.breakStanceRouteAttempts,
                run.breakStanceExpandedCells,
                roundForLog(run.breakStanceReachDistance),
                run.breakStanceCell.y() - run.breakStanceStart.y(),
                step.waypointIndex(),
                step.remainingCells(),
                step.stableFeet(),
                step.maximumWaypointIndex(),
                step.lastProgressAgeMs(),
                step.descentPhase().name().toLowerCase(Locale.ROOT),
                episodeElapsedMs,
                remainingDeadlineMs
            );
            clearGatherTreeBreakStanceState(run, false);
            return new ControlDecision(stopFrom(effective, "gather_tree_break_stance_nav3d_reached"), InputState.stop());
        }
        if (step.outcome() == GatherTreeBreakStanceTraversalController.Outcome.REJECTED) {
            if ("break_stance_deadline".equals(step.reason())) {
                return expireGatherTreeBreakStanceTarget(effective, run, nowMs);
            }
            if ("route_stalled".equals(step.reason())) {
                run.breakStanceNav3dRouteStallCount++;
            }
            if (isGatherTreeBreakStanceReplanReason(step.reason())
                && GatherTreeBreakStanceTraversal.canCompute(run.breakStanceRouteAttempts)) {
                VoxelCell failedStance = run.breakStanceCell;
                if (failedStance != null) {
                    run.excludedBreakStances.add(failedStance);
                }
                run.breakStanceNav3dReplannedCount++;
                LOGGER.warn(
                    "gather_tree.break_stance_nav3d_replanned instanceId={} commandId={} selectionEpisode={} target={} trigger={} excludedStance={} routeAttempt={} waypoint={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
                    instanceId,
                    run.commandId,
                    run.selectionEpisode,
                    run.currentTarget.toShortString(),
                    effectiveTrigger,
                    failedStance,
                    run.breakStanceRouteAttempts,
                    step.waypoint(),
                    step.waypointIndex(),
                    step.remainingCells(),
                    step.stableFeet(),
                    step.maximumWaypointIndex(),
                    step.lastProgressAgeMs(),
                    step.descentPhase().name().toLowerCase(Locale.ROOT),
                    episodeElapsedMs,
                    remainingDeadlineMs,
                    step.reason()
                );
                clearGatherTreeBreakStanceForReplan(run, effectiveTrigger);
                return new ControlDecision(
                    stopFrom(effective, "gather_tree_break_stance_replan:" + step.reason()),
                    InputState.stop()
                );
            }
            return rejectGatherTreeBreakStance(
                effective, run, effectiveTrigger, step.reason(), nowMs, 0, step);
        }
        if (step.outcome() == GatherTreeBreakStanceTraversalController.Outcome.IDLE
            || step.waypoint() == null) {
            return rejectGatherTreeBreakStance(
                effective, run, effectiveTrigger, "traversal_inactive", nowMs);
        }

        Vec3d aim = new Vec3d(
            step.waypoint().x() + 0.5D,
            step.waypoint().y(),
            step.waypoint().z() + 0.5D
        );
        LookAngles look = lookAnglesToPoint(player, aim);
        boolean forward = step.forward() && !step.waypointAdvanced();
        InputState input = new InputState(
            forward,
            false,
            false,
            false,
            forward && step.jump(),
            step.sneak(),
            forward ? 1.0F : 0.0F,
            0.0F
        );
        String driveAction = step.descentExempt()
            ? "gather_tree_break_stance_nav3d_descend"
            : "gather_tree_break_stance_nav3d";
        return new ControlDecision(
            lookIntentForAngles(
                effective,
                look.yaw(),
                look.pitch(),
                driveAction
            ),
            input
        );
    }

    private static void captureGatherTreeBreakStanceDiagnostics(
        GatherTreeRun run,
        GatherTreeBreakStanceTraversalController.Step step,
        String trigger,
        long nowMs
    ) {
        if (run == null || step == null) {
            return;
        }
        run.breakStanceLastWaypoint = step.waypoint();
        run.breakStanceLastWaypointIndex = step.waypointIndex();
        run.breakStanceLastRemainingCells = step.remainingCells();
        run.breakStanceLastStableFeet = step.stableFeet();
        run.breakStanceLastMaximumWaypointIndex = step.maximumWaypointIndex();
        run.breakStanceLastProgressAtMs = Math.max(0L, nowMs - step.lastProgressAgeMs());
        run.breakStanceLastDescentPhase = step.descentPhase().name().toLowerCase(Locale.ROOT);
        run.breakStanceLastTrigger = trigger == null ? "" : trigger;
    }

    private void logGatherTreeBreakStanceTransitions(
        GatherTreeRun run,
        String trigger,
        GatherTreeBreakStanceTraversalController.Step step,
        long elapsedMs,
        long remainingDeadlineMs
    ) {
        if (run == null || step == null) {
            return;
        }
        if (step.waypointAdvanced()) {
            run.breakStanceNav3dProgressCount++;
            if (step.forwardResynchronized()) {
                run.breakStanceNav3dResyncCount++;
            }
            LOGGER.info(
                "gather_tree.break_stance_nav3d_progress instanceId={} commandId={} selectionEpisode={} target={} trigger={} routeAttempt={} waypoint={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
                instanceId,
                run.commandId,
                run.selectionEpisode,
                run.currentTarget == null ? "" : run.currentTarget.toShortString(),
                trigger,
                run.breakStanceRouteAttempts,
                step.waypoint(),
                step.waypointIndex(),
                step.remainingCells(),
                step.stableFeet(),
                step.maximumWaypointIndex(),
                step.lastProgressAgeMs(),
                step.descentPhase().name().toLowerCase(Locale.ROOT),
                elapsedMs,
                remainingDeadlineMs,
                step.forwardResynchronized() ? "forward_resynchronized" : "cursor_advanced"
            );
        }
        if (step.descentStarted()) {
            run.breakStanceNav3dDescentStartedCount++;
            LOGGER.info(
                "gather_tree.break_stance_nav3d_descent_started instanceId={} commandId={} selectionEpisode={} target={} trigger={} routeAttempt={} waypoint={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
                instanceId,
                run.commandId,
                run.selectionEpisode,
                run.currentTarget == null ? "" : run.currentTarget.toShortString(),
                trigger,
                run.breakStanceRouteAttempts,
                step.waypoint(),
                step.waypointIndex(),
                step.remainingCells(),
                step.stableFeet(),
                step.maximumWaypointIndex(),
                step.lastProgressAgeMs(),
                step.descentPhase().name().toLowerCase(Locale.ROOT),
                elapsedMs,
                remainingDeadlineMs,
                step.reason()
            );
        }
        if (step.descentLanded()) {
            run.breakStanceNav3dDescentLandedCount++;
            LOGGER.info(
                "gather_tree.break_stance_nav3d_descent_landed instanceId={} commandId={} selectionEpisode={} target={} trigger={} routeAttempt={} waypoint={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
                instanceId,
                run.commandId,
                run.selectionEpisode,
                run.currentTarget == null ? "" : run.currentTarget.toShortString(),
                trigger,
                run.breakStanceRouteAttempts,
                step.waypoint(),
                step.waypointIndex(),
                step.remainingCells(),
                step.stableFeet(),
                step.maximumWaypointIndex(),
                step.lastProgressAgeMs(),
                step.descentPhase().name().toLowerCase(Locale.ROOT),
                elapsedMs,
                remainingDeadlineMs,
                step.reason()
            );
        }
    }

    private static boolean isGatherTreeBreakStanceReplanReason(String reason) {
        return "route_stalled".equals(reason)
            || "route_deviation".equals(reason)
            || "route_invalidated".equals(reason)
            || "descent_landing_invalidated".equals(reason);
    }

    private void clearGatherTreeBreakStanceForReplan(GatherTreeRun run, String trigger) {
        run.breakStanceRoute = List.of();
        run.breakStanceCell = null;
        run.breakStanceTarget = null;
        run.breakStanceTrigger = trigger == null ? "" : trigger;
        run.breakStanceStart = null;
        run.breakStanceExpandedCells = 0;
        run.breakStanceReachDistance = 0.0D;
        run.breakStanceSelectedAtMs = 0L;
        run.breakStanceTraversal.clear();
        clearNavigationState();
    }

    private ControlDecision rejectGatherTreeBreakStance(
        BrainLink.Intent effective,
        GatherTreeRun run,
        String trigger,
        String reason,
        long nowMs
    ) {
        return rejectGatherTreeBreakStance(effective, run, trigger, reason, nowMs, 0);
    }

    private ControlDecision rejectGatherTreeBreakStance(
        BrainLink.Intent effective,
        GatherTreeRun run,
        String trigger,
        String reason,
        long nowMs,
        int expandedCells
    ) {
        return rejectGatherTreeBreakStance(
            effective,
            run,
            trigger,
            reason,
            nowMs,
            expandedCells,
            null
        );
    }

    private ControlDecision rejectGatherTreeBreakStance(
        BrainLink.Intent effective,
        GatherTreeRun run,
        String trigger,
        String reason,
        long nowMs,
        int expandedCells,
        GatherTreeBreakStanceTraversalController.Step traversalStep
    ) {
        if (run == null) {
            return new ControlDecision(stopFrom(effective, "gather_tree_break_stance_rejected:" + reason), InputState.stop());
        }
        BlockPos target = run.currentTarget;
        VoxelCell selected = run.breakStanceCell;
        int routeLength = run.breakStanceRoute.size();
        GatherTreeLivenessPolicy.BreakStanceEpisode episode = run.breakStanceEpisode;
        GatherTreeBreakStanceTraversalController traversal = run.breakStanceTraversal;
        long elapsedMs = episode == null
            ? (run.breakStanceSelectedAtMs <= 0L
                ? 0L
                : Math.max(0L, nowMs - run.breakStanceSelectedAtMs))
            : episode.elapsedMs(nowMs);
        long remainingDeadlineMs = episode == null ? 0L : episode.remainingMs(nowMs);
        boolean traversalActive = traversal.active();
        VoxelCell waypoint = traversalStep != null
            ? traversalStep.waypoint()
            : traversalActive ? traversal.activeWaypoint() : run.breakStanceLastWaypoint;
        int waypointIndex = traversalStep != null
            ? traversalStep.waypointIndex()
            : traversalActive ? traversal.waypointIndex() : run.breakStanceLastWaypointIndex;
        int remainingCells = traversalStep != null
            ? traversalStep.remainingCells()
            : traversalActive ? traversal.remainingCells() : run.breakStanceLastRemainingCells;
        VoxelCell stableFeet = traversalStep != null
            ? traversalStep.stableFeet()
            : traversalActive ? traversal.stableFeet() : run.breakStanceLastStableFeet;
        int maximumWaypointIndex = traversalStep != null
            ? traversalStep.maximumWaypointIndex()
            : traversalActive
                ? traversal.maximumWaypointIndex()
                : run.breakStanceLastMaximumWaypointIndex;
        long progressAgeMs = traversalStep != null
            ? traversalStep.lastProgressAgeMs()
            : traversalActive
                ? traversal.lastProgressAgeMs(nowMs)
                : Math.max(0L, nowMs - run.breakStanceLastProgressAtMs);
        String descentPhase = traversalStep != null
            ? traversalStep.descentPhase().name().toLowerCase(Locale.ROOT)
            : traversalActive
                ? traversal.descentPhase().name().toLowerCase(Locale.ROOT)
                : run.breakStanceLastDescentPhase;
        run.breakStanceNav3dRejectedCount++;
        run.breakStanceNav3dMaximumElapsedMs = Math.max(
            run.breakStanceNav3dMaximumElapsedMs,
            elapsedMs
        );
        run.breakStanceNav3dMaximumWaypointIndex = Math.max(
            run.breakStanceNav3dMaximumWaypointIndex,
            maximumWaypointIndex
        );
        LOGGER.warn(
            "gather_tree.break_stance_nav3d_rejected instanceId={} commandId={} selectionEpisode={} target={} trigger={} start={} excludedStance={} routeLength={} routeAttempt={} expandedCells={} reachDistance={} verticalDelta={} waypoint={} waypointIndex={} remainingCells={} stableFeet={} maximumWaypointIndex={} progressAgeMs={} descentPhase={} elapsedMs={} remainingDeadlineMs={} reason={}",
            instanceId,
            run.commandId,
            run.selectionEpisode,
            target == null ? "" : target.toShortString(),
            trigger,
            run.breakStanceStart,
            selected,
            routeLength,
            run.breakStanceRouteAttempts,
            expandedCells > 0 ? expandedCells : run.breakStanceExpandedCells,
            roundForLog(run.breakStanceReachDistance),
            selected == null || run.breakStanceStart == null ? 0 : selected.y() - run.breakStanceStart.y(),
            waypoint,
            waypointIndex,
            remainingCells,
            stableFeet,
            maximumWaypointIndex,
            progressAgeMs,
            descentPhase,
            elapsedMs,
            remainingDeadlineMs,
            reason
        );
        if (target != null) {
            run.abandonedTargets.add(target);
        }
        resetGatherTreeCurrentTarget(run);
        return new ControlDecision(stopFrom(effective, "gather_tree_break_stance_rejected:" + reason), InputState.stop());
    }

    private static VoxelCell gatherTreePlayerFeet(ClientPlayerEntity player) {
        if (player == null) {
            return null;
        }
        return new VoxelCell(
            (int) Math.floor(player.getX()),
            (int) Math.floor(player.getY()),
            (int) Math.floor(player.getZ())
        );
    }

    private static void recordGatherTreeFailedBreakStance(GatherTreeRun run, ClientPlayerEntity player) {
        VoxelCell feet = gatherTreePlayerFeet(player);
        if (run != null && feet != null) {
            run.excludedBreakStances.add(feet);
        }
    }

    private GatherLogPlanner.AdjacentPlan chooseGatherTreeContinuationBreakCell(
        BlockView world,
        GridPerception routePerception,
        GridCell start,
        GatherTreeRun run,
        Set<GridCell> excludedBreakCells
    ) {
        if (world == null
            || routePerception == null
            || start == null
            || run == null
            || run.currentTarget == null
            || run.completedTargets.isEmpty()
            || !isSingleAxisGatherTreeCluster(liveTreeCluster(world, run.cluster))) {
            return null;
        }
        Set<GridCell> skipped = excludedBreakCells == null ? Set.of() : excludedBreakCells;
        GridCell targetCell = new GridCell(run.currentTarget.getX(), run.currentTarget.getZ());
        List<GatherTreeContinuationCandidate> routedCandidates = new ArrayList<>();
        List<GatherTreeContinuationCandidate> directCandidates = new ArrayList<>();
        for (BlockPos completed : run.completedTargets) {
            if (completed == null) {
                continue;
            }
            GridCell completedCell = new GridCell(completed.getX(), completed.getZ());
            if (completedCell.equals(targetCell)
                || continuationBreakDistanceSquared(completedCell, targetCell) > GATHER_TREE_CONTINUATION_BREAK_DISTANCE_SQUARED
                || !isSameGatherTreeRowAxis(run, completedCell, targetCell)) {
                continue;
            }
            if (shouldUseGatherTreeRowAxisContinuationCell(
                routePerception,
                start,
                completedCell,
                targetCell,
                run.currentTarget.getY(),
                true,
                isGatherTreeRowApproachClear(world, run, completedCell, targetCell),
                skipped
            )) {
                List<GridCell> route = GridAStar.route(routePerception, start, completedCell);
                if (!route.isEmpty()) {
                    routedCandidates.add(new GatherTreeContinuationCandidate(
                        completedCell,
                        route,
                        "completed_row_axis_break_cell"
                    ));
                } else if (shouldUseGatherTreeContinuationDirectRoute(
                    routePerception,
                    start,
                    completedCell,
                    run.currentTarget.getY()
                )) {
                    directCandidates.add(new GatherTreeContinuationCandidate(
                        completedCell,
                        fallbackContinuationRoute(start, completedCell),
                        "completed_row_axis_direct_route"
                    ));
                }
            }
            for (GridCell cell : gatherTreeContinuationSideCells(run, completedCell)) {
                if (cell.equals(targetCell)
                    || skipped.contains(cell)
                    || isGatherTreeRowAxisCell(run, cell)
                    || !routePerception.inBounds(cell.x(), cell.z())
                    || routePerception.isBlocked(cell.x(), cell.z())
                    || continuationBreakDistanceSquared(cell, targetCell) > GATHER_TREE_CONTINUATION_BREAK_DISTANCE_SQUARED) {
                    continue;
                }
                List<GridCell> route = GridAStar.route(routePerception, start, cell);
                if (!route.isEmpty()) {
                    routedCandidates.add(new GatherTreeContinuationCandidate(cell, route, "completed_row_side_break_cell"));
                } else if (shouldUseGatherTreeContinuationDirectRoute(
                    routePerception,
                    start,
                    cell,
                    run.currentTarget.getY()
                )) {
                    directCandidates.add(new GatherTreeContinuationCandidate(
                        cell,
                        fallbackContinuationRoute(start, cell),
                        "completed_row_side_direct_route"
                    ));
                }
            }
        }
        if (!routedCandidates.isEmpty()) {
            routedCandidates.sort(Comparator
                .comparingInt((GatherTreeContinuationCandidate candidate) -> continuationBreakDistanceSquared(candidate.cell(), targetCell))
                .thenComparingInt((GatherTreeContinuationCandidate candidate) -> continuationBreakDistanceSquared(start, candidate.cell())));
            GatherTreeContinuationCandidate best = routedCandidates.getFirst();
            return new GatherLogPlanner.AdjacentPlan(best.cell(), best.route(), best.reason());
        }
        if (!directCandidates.isEmpty()) {
            directCandidates.sort(Comparator
                .comparingInt((GatherTreeContinuationCandidate candidate) -> continuationBreakDistanceSquared(candidate.cell(), targetCell))
                .thenComparingInt((GatherTreeContinuationCandidate candidate) -> continuationBreakDistanceSquared(start, candidate.cell())));
            GatherTreeContinuationCandidate best = directCandidates.getFirst();
            return new GatherLogPlanner.AdjacentPlan(best.cell(), best.route(), best.reason());
        }
        return null;
    }

    static boolean shouldUseGatherTreeRowAxisContinuationCell(
        GridPerception routePerception,
        GridCell start,
        GridCell cell,
        GridCell target,
        int targetY,
        boolean sameRowAxis,
        boolean approachClear,
        Set<GridCell> skipped
    ) {
        if (routePerception == null || start == null || cell == null || target == null) {
            return false;
        }
        if (!sameRowAxis || !approachClear || cell.equals(target)) {
            return false;
        }
        if (skipped != null && skipped.contains(cell)) {
            return false;
        }
        if (continuationBreakDistanceSquared(cell, target) > GATHER_TREE_CONTINUATION_BREAK_DISTANCE_SQUARED
            || continuationBreakDistanceSquared(start, cell) > GATHER_TREE_CONTINUATION_ROUTE_FALLBACK_DISTANCE_SQUARED) {
            return false;
        }
        if (!routePerception.inBounds(cell.x(), cell.z()) || routePerception.isBlocked(cell.x(), cell.z())) {
            return false;
        }
        OptionalInt surface = routePerception.surfaceY(cell.x(), cell.z());
        return surface.isPresent()
            && Math.abs(surface.getAsInt() - targetY) <= GATHER_TREE_CONTINUATION_DIRECT_MAX_SURFACE_DELTA;
    }

    static boolean shouldUseGatherTreeContinuationDirectRoute(
        GridPerception routePerception,
        GridCell start,
        GridCell cell,
        int targetY
    ) {
        if (routePerception == null || start == null || cell == null) {
            return false;
        }
        if (continuationBreakDistanceSquared(start, cell) > GATHER_TREE_CONTINUATION_ROUTE_FALLBACK_DISTANCE_SQUARED) {
            return false;
        }
        OptionalInt surface = routePerception.surfaceY(cell.x(), cell.z());
        return surface.isPresent()
            && Math.abs(surface.getAsInt() - targetY) <= GATHER_TREE_CONTINUATION_DIRECT_MAX_SURFACE_DELTA;
    }

    private static List<GridCell> gatherTreeContinuationSideCells(GatherTreeRun run, GridCell rowCell) {
        if (run == null || rowCell == null) {
            return List.of();
        }
        Map<Integer, Set<Integer>> xsByZ = new HashMap<>();
        Map<Integer, Set<Integer>> zsByX = new HashMap<>();
        for (BlockPos log : run.cluster) {
            if (log != null) {
                xsByZ.computeIfAbsent(log.getZ(), ignored -> new HashSet<>()).add(log.getX());
                zsByX.computeIfAbsent(log.getX(), ignored -> new HashSet<>()).add(log.getZ());
            }
        }
        List<GridCell> cells = new ArrayList<>();
        Set<Integer> rowXs = xsByZ.get(rowCell.z());
        if (rowXs != null && rowXs.size() >= 2) {
            cells.add(new GridCell(rowCell.x(), rowCell.z() - 1));
            cells.add(new GridCell(rowCell.x(), rowCell.z() + 1));
        }
        Set<Integer> columnZs = zsByX.get(rowCell.x());
        if (columnZs != null && columnZs.size() >= 2) {
            cells.add(new GridCell(rowCell.x() - 1, rowCell.z()));
            cells.add(new GridCell(rowCell.x() + 1, rowCell.z()));
        }
        return cells;
    }

    private record GatherTreeContinuationCandidate(GridCell cell, List<GridCell> route, String reason) {
    }

    private static List<GridCell> fallbackContinuationRoute(GridCell start, GridCell cell) {
        if (start == null || cell == null) {
            return List.of();
        }
        if (start.equals(cell)) {
            return List.of(start);
        }
        List<GridCell> route = new ArrayList<>();
        if (start.z() == cell.z()) {
            int step = Integer.compare(cell.x(), start.x());
            for (int x = start.x() + step; step != 0 && x != cell.x() + step; x += step) {
                route.add(new GridCell(x, start.z()));
            }
            return route;
        }
        if (start.x() == cell.x()) {
            int step = Integer.compare(cell.z(), start.z());
            for (int z = start.z() + step; step != 0 && z != cell.z() + step; z += step) {
                route.add(new GridCell(start.x(), z));
            }
            return route;
        }
        return List.of(cell);
    }

    private static int continuationBreakDistanceSquared(GridCell a, GridCell b) {
        int dx = a.x() - b.x();
        int dz = a.z() - b.z();
        return dx * dx + dz * dz;
    }

    private static Set<GridCell> gatherTreeBreakCellExclusions(GatherTreeRun run) {
        if (run == null) {
            return Set.of();
        }
        Set<GridCell> excluded = new HashSet<>(run.excludedAdjacentCells);
        Map<Integer, Set<Integer>> xsByZ = new HashMap<>();
        Map<Integer, Set<Integer>> zsByX = new HashMap<>();
        for (BlockPos log : run.cluster) {
            if (log != null) {
                excluded.add(new GridCell(log.getX(), log.getZ()));
                xsByZ.computeIfAbsent(log.getZ(), ignored -> new HashSet<>()).add(log.getX());
                zsByX.computeIfAbsent(log.getX(), ignored -> new HashSet<>()).add(log.getZ());
            }
        }
        for (Map.Entry<Integer, Set<Integer>> entry : xsByZ.entrySet()) {
            Set<Integer> xs = entry.getValue();
            if (xs.size() < 2) {
                continue;
            }
            int min = xs.stream().mapToInt(Integer::intValue).min().orElse(0);
            int max = xs.stream().mapToInt(Integer::intValue).max().orElse(0);
            for (int x = min - 1; x <= max + 1; x++) {
                excluded.add(new GridCell(x, entry.getKey()));
            }
        }
        for (Map.Entry<Integer, Set<Integer>> entry : zsByX.entrySet()) {
            Set<Integer> zs = entry.getValue();
            if (zs.size() < 2) {
                continue;
            }
            int min = zs.stream().mapToInt(Integer::intValue).min().orElse(0);
            int max = zs.stream().mapToInt(Integer::intValue).max().orElse(0);
            for (int z = min - 1; z <= max + 1; z++) {
                excluded.add(new GridCell(entry.getKey(), z));
            }
        }
        return excluded;
    }

    private Set<GridCell> gatherTreeBreakNavigationExclusions(BlockView world, GatherTreeRun run) {
        if (run == null) {
            return Set.of();
        }
        Set<GridCell> excluded = new HashSet<>(run.excludedAdjacentCells);
        for (BlockPos log : liveTreeCluster(world, run.cluster)) {
            if (log != null) {
                excluded.add(new GridCell(log.getX(), log.getZ()));
            }
        }
        return excluded;
    }

    private static boolean isGatherTreeRowAxisCell(GatherTreeRun run, GridCell cell) {
        if (run == null || cell == null) {
            return false;
        }
        Map<Integer, Set<Integer>> xsByZ = new HashMap<>();
        Map<Integer, Set<Integer>> zsByX = new HashMap<>();
        for (BlockPos log : run.cluster) {
            if (log != null) {
                xsByZ.computeIfAbsent(log.getZ(), ignored -> new HashSet<>()).add(log.getX());
                zsByX.computeIfAbsent(log.getX(), ignored -> new HashSet<>()).add(log.getZ());
            }
        }
        for (Map.Entry<Integer, Set<Integer>> entry : xsByZ.entrySet()) {
            if (entry.getKey() == cell.z() && entry.getValue().size() >= 2) {
                return true;
            }
        }
        for (Map.Entry<Integer, Set<Integer>> entry : zsByX.entrySet()) {
            if (entry.getKey() == cell.x() && entry.getValue().size() >= 2) {
                return true;
            }
        }
        return false;
    }

    private static boolean isSameGatherTreeRowAxis(GatherTreeRun run, GridCell start, GridCell drop) {
        if (run == null || start == null || drop == null) {
            return false;
        }
        Map<Integer, Set<Integer>> xsByZ = new HashMap<>();
        Map<Integer, Set<Integer>> zsByX = new HashMap<>();
        for (BlockPos log : run.cluster) {
            if (log != null) {
                xsByZ.computeIfAbsent(log.getZ(), ignored -> new HashSet<>()).add(log.getX());
                zsByX.computeIfAbsent(log.getX(), ignored -> new HashSet<>()).add(log.getZ());
            }
        }
        Set<Integer> row = xsByZ.get(start.z());
        if (start.z() == drop.z() && row != null && row.size() >= 2) {
            return true;
        }
        Set<Integer> column = zsByX.get(start.x());
        return start.x() == drop.x() && column != null && column.size() >= 2;
    }

    private boolean isGatherTreeRowApproachClear(BlockView world, GatherTreeRun run, GridCell start, GridCell drop) {
        if (world == null || run == null || start == null || drop == null) {
            return false;
        }
        Set<GridCell> liveLogCells = new HashSet<>();
        for (BlockPos log : liveTreeCluster(world, run.cluster)) {
            if (log != null) {
                liveLogCells.add(new GridCell(log.getX(), log.getZ()));
            }
        }
        if (start.z() == drop.z()) {
            int step = Integer.compare(drop.x(), start.x());
            for (int x = start.x() + step; step != 0 && x != drop.x(); x += step) {
                if (liveLogCells.contains(new GridCell(x, start.z()))) {
                    return false;
                }
            }
            return true;
        }
        if (start.x() == drop.x()) {
            int step = Integer.compare(drop.z(), start.z());
            for (int z = start.z() + step; step != 0 && z != drop.z(); z += step) {
                if (liveLogCells.contains(new GridCell(start.x(), z))) {
                    return false;
                }
            }
            return true;
        }
        return false;
    }

    private Set<BlockPos> discoverTreeLogCluster(BlockView world, BlockPos seed) {
        if (world == null || seed == null || !world.getBlockState(seed).isIn(BlockTags.LOGS)) {
            return Set.of();
        }
        Set<BlockPos> cluster = new HashSet<>();
        Queue<BlockPos> queue = new ArrayDeque<>();
        BlockPos immutableSeed = seed.toImmutable();
        cluster.add(immutableSeed);
        queue.add(immutableSeed);
        while (!queue.isEmpty() && cluster.size() < GATHER_TREE_CLUSTER_LIMIT) {
            BlockPos current = queue.remove();
            for (BlockPos neighbor : logNeighbors(current)) {
                if (cluster.size() >= GATHER_TREE_CLUSTER_LIMIT) {
                    break;
                }
                if (Math.abs(neighbor.getX() - seed.getX()) > GATHER_TREE_CLUSTER_RADIUS
                    || Math.abs(neighbor.getY() - seed.getY()) > GATHER_TREE_CLUSTER_RADIUS
                    || Math.abs(neighbor.getZ() - seed.getZ()) > GATHER_TREE_CLUSTER_RADIUS) {
                    continue;
                }
                BlockPos candidate = neighbor.toImmutable();
                if (cluster.contains(candidate) || !world.getBlockState(candidate).isIn(BlockTags.LOGS)) {
                    continue;
                }
                cluster.add(candidate);
                queue.add(candidate);
            }
        }
        return Set.copyOf(cluster);
    }

    private Set<BlockPos> liveTreeCluster(BlockView world, Set<BlockPos> cluster) {
        if (world == null || cluster == null || cluster.isEmpty()) {
            return Set.of();
        }
        Set<BlockPos> live = new HashSet<>();
        for (BlockPos pos : cluster) {
            if (pos != null && world.getBlockState(pos).isIn(BlockTags.LOGS)) {
                live.add(pos.toImmutable());
            }
        }
        return Set.copyOf(live);
    }

    private List<BlockPos> logNeighbors(BlockPos pos) {
        return List.of(
            pos.up(),
            pos.down(),
            pos.north(),
            pos.south(),
            pos.east(),
            pos.west()
        );
    }

