    static final class GatherTreeSearchRun {
        final String commandId;
        final GridCell origin;
        final int originFeetY;
        final long startedAtMs;
        GridCell goal = null;
        List<GridCell> route = List.of();
        String routeReason = "";
        final Set<GridCell> visitedGoals = new HashSet<>();
        final Set<GatherTreeSearchRouteRejection.Signature> rejectedRouteSignatures = new HashSet<>();
        int routeAttempts = 0;
        int routeUnavailableStreak = 0;
        boolean noRouteLogged = false;
        long nextRouteRetryAtMs = 0L;
        // PERF: cross-tick memo for selectGatherTreeLoadedLogSearchTarget (mirrors GatherTreeRun's
        // cachedTargetSelection). searchTargetCached lets a null/miss be memoized too, so the pathological
        // no-result scan does not re-run every tick under a frozen block-pos.
        GatherTreeSearchTarget cachedSearchTarget = null;
        boolean searchTargetCached = false;
        long searchTargetCacheKey = Long.MIN_VALUE;
        long searchTargetCachedAtMs = 0L;
        int edgeRouteRejectedCount = 0;
        final Map<String, Integer> edgeRouteRejectionReasons = new LinkedHashMap<>();
        int repeatedRejectedRouteSignatureCount = 0;
        int inventoryLogsBefore = -1;
        int inventoryLogsAfter = -1;
        double healthBefore = -1.0D;
        double minimumHealth = -1.0D;
        double healthAfter = -1.0D;

        GatherTreeSearchRun(String commandId, GridCell origin, int originFeetY, long startedAtMs) {
            this.commandId = commandId == null ? "" : commandId;
            this.origin = origin == null ? new GridCell(0, 0) : origin;
            this.originFeetY = originFeetY;
            this.startedAtMs = startedAtMs;
        }

        void observe(int inventoryLogs, double health) {
            if (inventoryLogsBefore < 0) {
                inventoryLogsBefore = inventoryLogs;
            }
            inventoryLogsAfter = inventoryLogs;
            if (!Double.isFinite(health) || health < 0.0D) {
                return;
            }
            if (healthBefore < 0.0D) {
                healthBefore = health;
                minimumHealth = health;
            } else {
                minimumHealth = Math.min(minimumHealth, health);
            }
            healthAfter = health;
        }

        GatherTreeSearchRouteRejection.Rejected rejectCurrentRoute() {
            GatherTreeSearchRouteRejection.Signature signature =
                GatherTreeSearchRouteRejection.signature(goal, route);
            if (signature == null) {
                return null;
            }
            GridCell rejectedGoal = goal;
            List<GridCell> rejectedRoute = List.copyOf(route);
            String rejectedReason = routeReason;
            boolean repeated = !rejectedRouteSignatures.add(signature);
            visitedGoals.add(rejectedGoal);
            goal = null;
            route = List.of();
            routeReason = "";
            clearSelectionCache();
            return new GatherTreeSearchRouteRejection.Rejected(
                rejectedGoal,
                rejectedRoute,
                rejectedReason,
                signature,
                repeated
            );
        }

        void clearSelectionCache() {
            cachedSearchTarget = null;
            searchTargetCached = false;
            searchTargetCacheKey = Long.MIN_VALUE;
            searchTargetCachedAtMs = 0L;
        }

        boolean rejects(GatherTreeSearchTarget target) {
            if (target == null) {
                return false;
            }
            GatherTreeSearchRouteRejection.Signature signature =
                GatherTreeSearchRouteRejection.signature(target.goal(), target.route());
            return signature != null && rejectedRouteSignatures.contains(signature);
        }

        void recordEdgeRouteRejection(String reason, boolean repeatedSignature) {
            String normalizedReason = reason == null || reason.isBlank() ? "unknown" : reason;
            edgeRouteRejectedCount++;
            edgeRouteRejectionReasons.merge(normalizedReason, 1, Integer::sum);
            if (repeatedSignature) {
                repeatedRejectedRouteSignatureCount++;
            }
        }

        void inheritRejectedRoutes(GatherTreeSearchRun previous) {
            if (previous == null) {
                return;
            }
            rejectedRouteSignatures.addAll(previous.rejectedRouteSignatures);
            edgeRouteRejectedCount = previous.edgeRouteRejectedCount;
            edgeRouteRejectionReasons.putAll(previous.edgeRouteRejectionReasons);
            repeatedRejectedRouteSignatureCount = previous.repeatedRejectedRouteSignatureCount;
        }

        void inheritEvidence(GatherTreeSearchRun previous) {
            if (previous == null) {
                return;
            }
            inventoryLogsBefore = previous.inventoryLogsBefore;
            inventoryLogsAfter = previous.inventoryLogsAfter;
            healthBefore = previous.healthBefore;
            minimumHealth = previous.minimumHealth;
            healthAfter = previous.healthAfter;
        }
    }

    private enum FurnaceSmeltRecipe {
        CHARCOAL("smelt_charcoal", "charcoal"),
        RAW_IRON("smelt_raw_iron", "iron_ingot");

        private final String action;
        private final String outputItemId;

        FurnaceSmeltRecipe(String action, String outputItemId) {
            this.action = action;
            this.outputItemId = outputItemId;
        }

        String action() {
            return action;
        }

        String outputItemId() {
            return outputItemId;
        }

        static FurnaceSmeltRecipe fromAction(String action) {
            if (action == null) {
                return null;
            }
            for (FurnaceSmeltRecipe recipe : values()) {
                if (recipe.action.equals(action)) {
                    return recipe;
                }
            }
            return null;
        }
    }

