    /**
     * Route-independent identity for one tool-reserve interruption.  A visible-ore target or a
     * completed lane legitimately has no replayable lane suffix, but it still owns an exact plane,
     * heading, frontier, and already-accounted epoch position.  Keeping this separate from
     * {@link IronExposureLaneContinuation} prevents an empty route from weakening those checks.
     */
    private record IronExposureIdentityContinuation(
        Object worldIdentity,
        String dimensionId,
        long workspaceSessionRevision,
        int epoch,
        String planeId,
        int planeFeetY,
        VoxelCell planeOrigin,
        IronProspectAtlas.PlaneRegion planeRegion,
        StaircaseDescentPlanner.Direction2d heading,
        int cumulativeBlocks,
        VoxelCell frontier
    ) {
        IronExposureIdentityContinuation {
            dimensionId = dimensionId == null ? "" : dimensionId;
            planeId = planeId == null || planeId.isBlank() ? "none" : planeId;
        }

        boolean complete() {
            return worldIdentity != null
                && !dimensionId.isBlank()
                && epoch > 0
                && !"none".equals(planeId)
                && planeFeetY >= IronExposureLanePlanner.MIN_PRODUCTIVE_FEET_Y
                && planeFeetY <= IronExposureLanePlanner.MAX_PRODUCTIVE_FEET_Y
                && planeOrigin != null
                && planeRegion != null
                && heading != null
                && frontier != null
                && planeId.equals("y" + planeFeetY)
                && planeOrigin.y() == planeFeetY
                && planeRegion.feetY() == planeFeetY
                && frontier.y() == planeFeetY;
        }

        String headingName() {
            return heading == null ? "none" : heading.name();
        }
    }

    /** The consumed portion of the fixed per-command budget; epoch accounting is already settled. */
    private record IronCommandBudgetContinuation(int prospectBlocks, long activeMs) {
        IronCommandBudgetContinuation {
            prospectBlocks = Math.max(0, prospectBlocks);
            activeMs = Math.max(0L, activeMs);
        }
    }

